#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
enum TransportMode {
    Pattern,
    #[default]
    Song,
}

impl TransportMode {
    const fn toggled(self) -> Self {
        match self {
            Self::Pattern => Self::Song,
            Self::Song => Self::Pattern,
        }
    }
}

fn transport_loop_end_beat(project: &Project, mode: TransportMode) -> f32 {
    match mode {
        TransportMode::Pattern => pattern_playback_length_beats(project),
        TransportMode::Song => project.song_length_beats.max(4.0),
    }
}

fn pattern_playback_length_beats(project: &Project) -> f32 {
    let Some(pattern) = project.patterns.get(
        project
            .active_pattern
            .min(project.patterns.len().saturating_sub(1)),
    ) else {
        return 4.0;
    };
    pattern_content_length_beats(pattern)
}

fn pattern_content_length_beats(pattern: &Pattern) -> f32 {
    let step_end = pattern.length_steps.max(1) as f32 / 4.0;
    let note_end = pattern
        .notes
        .iter()
        .filter_map(|note| {
            let end = note.start + note.length.max(0.0);
            end.is_finite().then_some(end)
        })
        .fold(0.0_f32, f32::max);
    let used_end = step_end.max(note_end).max(0.25);
    ((used_end / 4.0).ceil() * 4.0).max(4.0)
}

/// Creates the immutable musical projection compiled by the callback timeline.
/// Pattern mode deliberately contains one synthetic placement of the selected
/// Pattern and no Playlist audio/automation; the user's Project is never
/// mutated and never receives the synthetic clip identity.
fn transport_playback_project(project: &Project, mode: TransportMode) -> Project {
    if mode == TransportMode::Song {
        return project.clone();
    }

    let mut playback = project.clone();
    let active_pattern = project
        .patterns
        .get(
            project
                .active_pattern
                .min(project.patterns.len().saturating_sub(1)),
        )
        .cloned();
    let pattern_length = pattern_playback_length_beats(project);
    playback.song_length_beats = pattern_length;
    playback.patterns = active_pattern.iter().cloned().collect();
    playback.active_pattern = 0;
    playback.clips = active_pattern
        .map(|pattern| {
            vec![Clip {
                id: 1,
                track: 0,
                start: 0.0,
                length: pattern_length,
                name: pattern.name,
                color: [255, 142, 82],
                kind: ClipKind::Pattern,
                group_id: None,
                pattern_id: pattern.id,
                automation_id: None,
                audio_asset_id: None,
                source_offset: 0.0,
                audio_source_offset_frame: None,
                audio_source_reference: None,
                audio_length_reference: None,
                fade_in_reference: None,
                fade_out_reference: None,
                gain: 1.0,
                fade_in: 0.0,
                fade_out: 0.0,
                muted: false,
            }]
        })
        .unwrap_or_default();
    playback.automation_lanes.clear();
    playback.audio_assets.clear();
    playback.audio_clip_mixer_destinations.clear();
    playback.migration_diagnostics.clear();
    playback
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct TransportPatternSlice {
    pattern_id: u32,
    start: f32,
    length: f32,
}

fn transport_pattern_slices(project: &Project, mode: TransportMode) -> Vec<TransportPatternSlice> {
    match mode {
        TransportMode::Pattern => project
            .patterns
            .get(
                project
                    .active_pattern
                    .min(project.patterns.len().saturating_sub(1)),
            )
            .map(|pattern| {
                vec![TransportPatternSlice {
                    pattern_id: pattern.id,
                    start: 0.0,
                    length: pattern_playback_length_beats(project),
                }]
            })
            .unwrap_or_default(),
        TransportMode::Song => project
            .clips
            .iter()
            .filter(|clip| clip.kind == ClipKind::Pattern && !clip.muted)
            .map(|clip| TransportPatternSlice {
                pattern_id: clip.pattern_id,
                start: clip.start,
                length: clip.length,
            })
            .collect(),
    }
}

fn transport_timeline_compile_options(
    project: &Project,
    mode: TransportMode,
) -> TimelineCompileOptions {
    let mut options = TimelineCompileOptions::default();
    if mode == TransportMode::Pattern {
        options.legacy_piano_period_beats = f64::from(pattern_playback_length_beats(project));
    }
    options
}

fn default_playlist_viewport(song_length_beats: f32) -> Viewport2D {
    let content_end = finite_content_end(song_length_beats, 4.0);
    Viewport2D::new(
        AxisViewport::new(0.0, content_end, 1_120.0, 70.0, 0.25, 512.0)
            .expect("playlist time viewport constants are valid"),
        AxisViewport::new(0.0, PLAYLIST_TRACK_COUNT as f64, 640.0, 56.0, 18.0, 112.0)
            .expect("playlist track viewport constants are valid"),
    )
}

fn default_piano_viewport() -> Viewport2D {
    let mut pitch = AxisViewport::new(0.0, PIANO_PITCH_COUNT as f64, 576.0, 24.0, 8.0, 96.0)
        .expect("piano pitch viewport constants are valid");
    pitch
        .reveal(49.0, 73.0, 0.0)
        .expect("piano initial pitch range is finite");
    Viewport2D::new(
        AxisViewport::new(0.0, f64::from(LOOP_LENGTH), 960.0, 60.0, 1.0, 512.0)
            .expect("piano time viewport constants are valid"),
        pitch,
    )
}

fn initial_selected_channel_index(project: &Project) -> usize {
    project
        .active_pattern()
        .notes
        .iter()
        .find_map(|note| note.channel_id)
        .and_then(|channel_id| {
            project
                .channels
                .iter()
                .position(|channel| channel.id == channel_id)
        })
        .unwrap_or(0)
}

fn finite_content_end(value: f32, minimum: f64) -> f64 {
    if value.is_finite() {
        f64::from(value).max(minimum)
    } else {
        minimum
    }
}

fn set_axis_visible_units(axis: &mut AxisViewport, units: f64) {
    if !units.is_finite() || units <= 0.0 {
        return;
    }
    let desired_pixels_per_unit = axis.viewport_pixels() / units;
    let factor = desired_pixels_per_unit / axis.pixels_per_unit();
    let _ = axis.zoom_at_pixel(0.0, factor);
}

fn apply_editor_wheel(
    viewport: &mut Viewport2D,
    canvas: Rect,
    hover_position: Option<Pos2>,
    scroll: Vec2,
    modifiers: egui::Modifiers,
) {
    if scroll.length_sq() <= 0.0001 {
        return;
    }
    let pointer = hover_position.unwrap_or_else(|| canvas.center());
    let anchor_x = f64::from((pointer.x - canvas.left()).clamp(0.0, canvas.width()));
    let anchor_y = f64::from((pointer.y - canvas.top()).clamp(0.0, canvas.height()));
    let command_zoom = modifiers.command || modifiers.ctrl;
    if command_zoom {
        let delta = if scroll.y.abs() >= scroll.x.abs() {
            scroll.y
        } else {
            scroll.x
        };
        let factor = f64::from((-delta * 0.0025).exp());
        if modifiers.shift {
            let _ = viewport.y.zoom_at_pixel(anchor_y, factor);
        } else {
            let _ = viewport.x.zoom_at_pixel(anchor_x, factor);
        }
    } else if modifiers.shift || scroll.x.abs() > scroll.y.abs() {
        let delta = if scroll.x.abs() > scroll.y.abs() {
            scroll.x
        } else {
            scroll.y
        };
        let _ = viewport.x.scroll_by_pixels(f64::from(-delta));
    } else {
        let _ = viewport.y.scroll_by_pixels(f64::from(-scroll.y));
    }
}

fn playlist_track_at_pixel(axis: AxisViewport, pixel: f64) -> Option<usize> {
    if !pixel.is_finite() || pixel < 0.0 || pixel >= axis.viewport_pixels() {
        return None;
    }
    let track = axis.content_at_pixel(pixel).floor();
    (track >= 0.0 && track < PLAYLIST_TRACK_COUNT as f64).then_some(track as usize)
}

fn piano_pitch_row(note: u8) -> f64 {
    (PIANO_PITCH_COUNT - 1 - usize::from(note.min(127))) as f64
}

fn piano_pitch_at_pixel(axis: AxisViewport, pixel: f64) -> Option<u8> {
    if !pixel.is_finite() || pixel < 0.0 || pixel >= axis.viewport_pixels() {
        return None;
    }
    let row = axis.content_at_pixel(pixel).floor();
    if !(0.0..PIANO_PITCH_COUNT as f64).contains(&row) {
        return None;
    }
    Some((PIANO_PITCH_COUNT - 1 - row as usize) as u8)
}

fn piano_pattern_content_end(pattern: &Pattern) -> f64 {
    let step_end = pattern.length_steps as f64 / 4.0;
    let note_end = pattern
        .notes
        .iter()
        .filter_map(|note| {
            let end = note.start + note.length.max(0.0);
            end.is_finite().then_some(f64::from(end))
        })
        .fold(0.0_f64, f64::max);
    let used_end = step_end.max(note_end).max(f64::from(LOOP_LENGTH));
    // Keep one complete bar of editable space after the last event. FL-style
    // Piano Roll editing must grow with content instead of pinning notes to the
    // legacy sixteen-beat playback period.
    ((used_end / 4.0).ceil() + 1.0) * 4.0
}

fn content_span_is_visible(axis: AxisViewport, start: f64, end: f64) -> bool {
    if !start.is_finite() || !end.is_finite() || end <= start {
        return false;
    }
    let (visible_start, visible_end) = axis.visible_range();
    end > visible_start && start < visible_end
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct TimelineSeekIntent {
    serial: u64,
    beat: f64,
    frame: u64,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum TimelineAudioSyncPhase {
    Unavailable,
    InstallReady,
    InstallQueued {
        request_id: u64,
        generation: u64,
    },
    LoopReady,
    LoopQueued {
        request_id: u64,
        generation: u64,
        frame: u64,
    },
    SeekReady,
    SeekQueued {
        request_id: u64,
        generation: u64,
        seek_serial: u64,
        epoch: u64,
        frame: u64,
    },
    AwaitingActivation {
        generation: u64,
        seek_serial: u64,
        epoch: u64,
        frame: u64,
        activation_request_id: u64,
    },
    Active {
        generation: u64,
        epoch: u64,
    },
    AssetHandoffClearReady {
        revision: u64,
    },
    AssetHandoffClearQueued {
        request_id: u64,
        revision: u64,
    },
    FaultClearReady {
        revision: u64,
    },
    FaultClearQueued {
        request_id: u64,
        revision: u64,
    },
    Faulted,
}

impl TimelineAudioSyncPhase {
    fn label(self) -> &'static str {
        match self {
            Self::Unavailable => "fallback / audio unavailable",
            Self::InstallReady => "timeline install retry",
            Self::InstallQueued { .. } => "waiting for timeline install",
            Self::LoopReady => "loop chase retry",
            Self::LoopQueued { .. } => "waiting for loop chase",
            Self::SeekReady => "seek chase preparation",
            Self::SeekQueued { .. } => "waiting for seek chase",
            Self::AwaitingActivation { .. } => "waiting for callback activation",
            Self::Active { .. } => "sample-accurate audio timeline active",
            Self::AssetHandoffClearReady { .. } => "pausing for audio asset handoff",
            Self::AssetHandoffClearQueued { .. } => "waiting for audio asset handoff clear",
            Self::FaultClearReady { .. } => "runtime fault clear retry",
            Self::FaultClearQueued { .. } => "waiting for runtime fault clear",
            Self::Faulted => "fallback / runtime fault",
        }
    }
}

#[derive(Debug)]
struct TimelineAudioSyncState {
    session: u64,
    source_generation: Option<u64>,
    phase: TimelineAudioSyncPhase,
    desired_seek: TimelineSeekIntent,
    next_seek_serial: u64,
    loop_token: Option<u64>,
    loop_disable_request: Option<u64>,
    retry_count: u64,
    stale_confirmations: u64,
    last_error: Option<String>,
    retain_callback_ownership: bool,
    asset_handoff_silenced: bool,
    asset_handoff_frame: Option<u64>,
    asset_handoff_assets_released: bool,
}

impl TimelineAudioSyncState {
    fn new(audio_available: bool) -> Self {
        Self {
            session: 1,
            source_generation: None,
            phase: if audio_available {
                TimelineAudioSyncPhase::InstallReady
            } else {
                TimelineAudioSyncPhase::Unavailable
            },
            desired_seek: TimelineSeekIntent {
                serial: 1,
                beat: 0.0,
                frame: 0,
            },
            next_seek_serial: 2,
            loop_token: None,
            loop_disable_request: None,
            retry_count: 0,
            stale_confirmations: 0,
            last_error: None,
            retain_callback_ownership: false,
            asset_handoff_silenced: false,
            asset_handoff_frame: None,
            asset_handoff_assets_released: false,
        }
    }

    fn reset_audio_session(&mut self, audio_available: bool) {
        self.session = next_nonzero_app_id(self.session);
        self.loop_token = None;
        self.loop_disable_request = None;
        self.last_error = None;
        self.retain_callback_ownership = false;
        self.asset_handoff_silenced = false;
        self.asset_handoff_frame = None;
        self.asset_handoff_assets_released = false;
        self.phase = if audio_available && self.source_generation.is_some() {
            TimelineAudioSyncPhase::InstallReady
        } else {
            TimelineAudioSyncPhase::Unavailable
        };
    }

    fn accept_source(&mut self, generation: u64, retain_callback_ownership: bool) {
        self.source_generation = Some(generation);
        self.loop_token = None;
        self.last_error = None;
        self.retain_callback_ownership = retain_callback_ownership;
        self.phase = TimelineAudioSyncPhase::InstallReady;
    }

    fn request_seek(&mut self, beat: f64, frame: u64) -> TimelineSeekIntent {
        let intent = TimelineSeekIntent {
            serial: self.next_seek_serial,
            beat,
            frame,
        };
        self.next_seek_serial = next_nonzero_app_id(self.next_seek_serial);
        self.desired_seek = intent;
        if self.source_generation.is_some()
            && matches!(
                self.phase,
                TimelineAudioSyncPhase::Active { .. } | TimelineAudioSyncPhase::SeekReady
            )
        {
            self.phase = TimelineAudioSyncPhase::SeekReady;
        }
        intent
    }

    fn queue_full(&mut self) {
        self.retry_count = self.retry_count.saturating_add(1);
        self.last_error = Some("Timeline runtime queue full; retrying".into());
    }

    fn fault(&mut self, message: String) {
        self.last_error = Some(message);
        self.retain_callback_ownership = false;
        self.asset_handoff_silenced = false;
        self.asset_handoff_frame = None;
        self.asset_handoff_assets_released = false;
        self.phase = TimelineAudioSyncPhase::Faulted;
    }

    fn begin_fault_clear(
        &mut self,
        revision: u64,
        retain_callback_ownership: bool,
        message: String,
    ) {
        self.loop_token = None;
        self.loop_disable_request = None;
        self.last_error = Some(message);
        self.retain_callback_ownership = retain_callback_ownership;
        self.phase = TimelineAudioSyncPhase::FaultClearReady { revision };
    }

    fn begin_asset_handoff(&mut self, revision: u64, retain_callback_ownership: bool, frame: u64) {
        self.loop_token = None;
        self.loop_disable_request = None;
        self.retain_callback_ownership = retain_callback_ownership;
        self.asset_handoff_silenced = true;
        self.asset_handoff_frame = Some(frame);
        self.asset_handoff_assets_released = false;
        self.last_error = Some(
            "Pausing playback while callback audio assets are migrated without partial playback"
                .into(),
        );
        self.phase = TimelineAudioSyncPhase::AssetHandoffClearReady { revision };
    }

    fn queue_asset_handoff_clear(&mut self, revision: u64, request_id: u64) {
        self.phase = TimelineAudioSyncPhase::AssetHandoffClearQueued {
            request_id,
            revision,
        };
    }

    fn confirm_asset_handoff_clear(&mut self, request_id: u64, revision: u64) -> bool {
        let matches = matches!(
            self.phase,
            TimelineAudioSyncPhase::AssetHandoffClearQueued {
                request_id: expected_request,
                revision: expected_revision,
            } if request_id == expected_request && revision == expected_revision
        );
        if matches {
            self.retain_callback_ownership = false;
            self.phase = TimelineAudioSyncPhase::InstallReady;
            self.last_error = Some("Waiting for callback audio asset migration".into());
        } else {
            self.confirmation_is_stale();
        }
        matches
    }

    fn queue_fault_clear(&mut self, revision: u64, request_id: u64) {
        self.phase = TimelineAudioSyncPhase::FaultClearQueued {
            request_id,
            revision,
        };
    }

    fn finish_fault_clear(&mut self) {
        self.loop_token = None;
        self.loop_disable_request = None;
        self.retain_callback_ownership = false;
        self.phase = TimelineAudioSyncPhase::Faulted;
    }

    fn confirm_fault_clear(&mut self, request_id: u64, revision: u64) -> bool {
        let matches = matches!(
            self.phase,
            TimelineAudioSyncPhase::FaultClearQueued {
                request_id: expected_request,
                revision: expected_revision,
            } if request_id == expected_request && revision == expected_revision
        );
        if matches {
            self.finish_fault_clear();
        } else {
            self.confirmation_is_stale();
        }
        matches
    }

    fn confirmation_is_stale(&mut self) {
        self.stale_confirmations = self.stale_confirmations.saturating_add(1);
    }

    fn confirm_install(&mut self, request_id: u64, generation: u64) -> bool {
        let matches = matches!(
            self.phase,
            TimelineAudioSyncPhase::InstallQueued {
                request_id: expected_request,
                generation: expected_generation,
            } if expected_request == request_id && expected_generation == generation
        ) && self.source_generation == Some(generation);
        if matches {
            self.phase = TimelineAudioSyncPhase::LoopReady;
            self.last_error = None;
        } else {
            self.confirmation_is_stale();
        }
        matches
    }

    fn confirm_loop(&mut self, request_id: u64, generation: u64, frame: u64, token: u64) -> bool {
        let matches = token != 0
            && matches!(
                self.phase,
                TimelineAudioSyncPhase::LoopQueued {
                    request_id: expected_request,
                    generation: expected_generation,
                    frame: expected_frame,
                } if expected_request == request_id
                    && expected_generation == generation
                    && expected_frame == frame
            )
            && self.source_generation == Some(generation);
        if matches {
            self.loop_token = Some(token);
            self.phase = TimelineAudioSyncPhase::SeekReady;
            self.last_error = None;
        } else {
            self.confirmation_is_stale();
        }
        matches
    }

    fn confirm_chase(
        &mut self,
        request_id: u64,
        generation: u64,
        epoch: u64,
        frame: u64,
    ) -> Option<u64> {
        let seek_serial = match self.phase {
            TimelineAudioSyncPhase::SeekQueued {
                request_id: expected_request,
                generation: expected_generation,
                seek_serial,
                epoch: expected_epoch,
                frame: expected_frame,
            } if expected_request == request_id
                && expected_generation == generation
                && expected_epoch == epoch
                && expected_frame == frame
                && self.source_generation == Some(generation) =>
            {
                seek_serial
            }
            _ => {
                self.confirmation_is_stale();
                return None;
            }
        };
        self.phase = TimelineAudioSyncPhase::AwaitingActivation {
            generation,
            seek_serial,
            epoch,
            frame,
            activation_request_id: 0,
        };
        self.last_error = None;
        Some(seek_serial)
    }

    fn queue_activation(
        &mut self,
        request_id: u64,
        generation: u64,
        seek_serial: u64,
        minimum_epoch: u64,
        frame: u64,
    ) -> bool {
        if request_id == 0 {
            return false;
        }
        let matches = matches!(
            self.phase,
            TimelineAudioSyncPhase::AwaitingActivation {
                generation: expected_generation,
                seek_serial: expected_serial,
                epoch: expected_epoch,
                frame: expected_frame,
                activation_request_id: 0,
            } if expected_generation == generation
                && expected_serial == seek_serial
                && expected_epoch == minimum_epoch
                && expected_frame == frame
        );
        if matches {
            self.phase = TimelineAudioSyncPhase::AwaitingActivation {
                generation,
                seek_serial,
                epoch: minimum_epoch,
                frame,
                activation_request_id: request_id,
            };
            self.last_error = None;
        }
        matches
    }

    fn confirm_activation_receipt(
        &mut self,
        request_id: u64,
        generation: u64,
        epoch: u64,
        frame: u64,
    ) -> bool {
        match self.phase {
            TimelineAudioSyncPhase::AwaitingActivation {
                generation: expected_generation,
                seek_serial,
                epoch: expected_epoch,
                frame: expected_frame,
                activation_request_id: expected_request,
            } if expected_generation == generation
                && expected_request == request_id
                && expected_frame == frame
                && timeline_epoch_has_reached(epoch, expected_epoch) =>
            {
                self.phase = if self.desired_seek.serial == seek_serial {
                    TimelineAudioSyncPhase::Active { generation, epoch }
                } else {
                    TimelineAudioSyncPhase::SeekReady
                };
                self.retain_callback_ownership = false;
                self.asset_handoff_silenced = false;
                self.asset_handoff_frame = None;
                self.asset_handoff_assets_released = false;
                self.last_error = None;
                true
            }
            _ => false,
        }
    }

    fn observe_active_epoch(&mut self, generation: u64, epoch: u64) -> bool {
        if let TimelineAudioSyncPhase::Active {
            generation: expected_generation,
            epoch: current_epoch,
        } = self.phase
            && expected_generation == generation
            && timeline_epoch_has_reached(epoch, current_epoch)
        {
            self.phase = TimelineAudioSyncPhase::Active { generation, epoch };
            return true;
        }
        false
    }

    fn reject_activation_receipt(
        &mut self,
        request_id: u64,
        generation: u64,
        reason: TimelineTransportActivationRejectReason,
    ) -> bool {
        let matches = matches!(
            self.phase,
            TimelineAudioSyncPhase::AwaitingActivation {
                generation: expected_generation,
                activation_request_id: expected_request,
                ..
            } if expected_generation == generation && expected_request == request_id
        );
        if matches {
            self.phase = TimelineAudioSyncPhase::SeekReady;
            self.retry_count = self.retry_count.saturating_add(1);
            self.last_error = Some(format!(
                "Timeline activation rejected without disturbing active playback ({reason:?}); retrying"
            ));
        } else {
            self.confirmation_is_stale();
        }
        matches
    }
}

fn enter_timeline_asset_fallback(
    sync: &mut TimelineAudioSyncState,
    transport_loop_dirty: &mut bool,
    message: String,
) {
    sync.loop_token = None;
    sync.loop_disable_request = None;
    sync.fault(message);
    *transport_loop_dirty = true;
}

fn begin_timeline_fault_handoff(
    sync: &mut TimelineAudioSyncState,
    transport_loop_dirty: &mut bool,
    installed_revision: Option<u64>,
    callback_still_owns: bool,
    message: String,
) {
    if let Some(revision) = installed_revision {
        sync.begin_fault_clear(revision, callback_still_owns, message);
        *transport_loop_dirty = false;
    } else {
        enter_timeline_asset_fallback(sync, transport_loop_dirty, message);
    }
}

fn confirm_timeline_asset_clear(
    sync: &mut TimelineAudioSyncState,
    transport_loop_dirty: &mut bool,
    request_id: u64,
    revision: u64,
) -> Option<f64> {
    if !sync.confirm_fault_clear(request_id, revision) {
        return None;
    }
    *transport_loop_dirty = true;
    Some(sync.desired_seek.beat)
}

#[derive(Clone)]
struct TimelineAudioSource {
    generation: u64,
    fingerprint: u64,
    sample_rate: u32,
    timeline: Arc<CompiledTimeline>,
    tempo_map: TempoMap,
    loop_start_beat: f64,
    loop_start_frame: u64,
    loop_end_beat: f64,
    loop_end_frame: u64,
}

const fn next_nonzero_app_id(current: u64) -> u64 {
    let next = current.wrapping_add(1);
    if next == 0 { 1 } else { next }
}

#[derive(Clone, Copy, Debug, PartialEq)]
enum TransportSeekTarget {
    TimelineFrame { beat: f64, frame: u64 },
    LegacyBeat { beat: f64 },
}

#[derive(Clone, Copy, Debug, PartialEq)]
enum TransportLoopTarget {
    TimelineFrames {
        start_beat: f64,
        start_frame: u64,
        end_beat: f64,
        end_frame: u64,
    },
    LegacyBeats {
        start_beat: f64,
        end_beat: f64,
    },
}

fn transport_seek_target(tempo_map: Option<&TempoMap>, beat: f64) -> TransportSeekTarget {
    match tempo_map.and_then(|map| map.beat_to_frame(beat).ok()) {
        Some(frame) => TransportSeekTarget::TimelineFrame { beat, frame },
        None => TransportSeekTarget::LegacyBeat { beat },
    }
}

fn transport_loop_target(
    tempo_map: Option<&TempoMap>,
    start_beat: f64,
    end_beat: f64,
) -> TransportLoopTarget {
    let frames = tempo_map.and_then(|map| {
        Some((
            map.beat_to_frame(start_beat).ok()?,
            map.beat_to_frame(end_beat).ok()?,
        ))
    });
    match frames {
        Some((start_frame, end_frame)) => TransportLoopTarget::TimelineFrames {
            start_beat,
            start_frame,
            end_beat,
            end_frame,
        },
        None => TransportLoopTarget::LegacyBeats {
            start_beat,
            end_beat,
        },
    }
}

fn transport_beat_for_frame(
    tempo_map: Option<&TempoMap>,
    timeline_frame: u64,
    legacy_beat: f64,
) -> f64 {
    tempo_map
        .and_then(|map| map.frame_to_beat(timeline_frame).ok())
        .unwrap_or(legacy_beat)
}

fn timeline_epoch_has_reached(actual: u64, expected: u64) -> bool {
    actual != 0 && expected != 0 && actual.wrapping_sub(expected) < (1_u64 << 63)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum NoteClipScheduler {
    CallbackTimeline,
    LegacyFallback,
}

const fn note_clip_scheduler(callback_owns_timeline: bool) -> NoteClipScheduler {
    if callback_owns_timeline {
        NoteClipScheduler::CallbackTimeline
    } else {
        NoteClipScheduler::LegacyFallback
    }
}

const fn callback_note_clip_ownership(
    confirmed_revision: Option<u64>,
    confirmed_epoch: Option<u64>,
    needs_resync: bool,
    transfer_pending: bool,
) -> bool {
    transfer_pending || (confirmed_revision.is_some() && confirmed_epoch.is_some() && !needs_resync)
}

fn compiled_native_channel_automation_target(
    target: &AutomationTarget,
) -> Option<(CompiledAutomationTarget, u32)> {
    match canonicalize_automation_target(target.clone()) {
        AutomationTarget::ChannelVolume { channel } => Some((
            CompiledAutomationTarget::ChannelVolume {
                channel_id: channel,
            },
            channel,
        )),
        AutomationTarget::ChannelPan { channel } => Some((
            CompiledAutomationTarget::ChannelPan {
                channel_id: channel,
            },
            channel,
        )),
        AutomationTarget::ChannelMute { channel } => Some((
            CompiledAutomationTarget::ChannelMute {
                channel_id: channel,
            },
            channel,
        )),
        _ => None,
    }
}

fn timeline_drives_native_channel_automation(
    timeline: &CompiledTimeline,
    target: &AutomationTarget,
) -> bool {
    let Some((compiled, channel_id)) = compiled_native_channel_automation_target(target) else {
        return false;
    };
    let generator_backed = timeline.plugin_routes().iter().any(|route| {
        matches!(
            route.destination,
            PluginRouteDestination::Generator {
                channel_id: routed,
                ..
            } if routed == channel_id
        )
    });
    !generator_backed
        && timeline
            .driven_automation_targets()
            .binary_search(&compiled)
            .is_ok()
}

fn should_dispatch_legacy_automation(
    callback_owned: bool,
    desired_timeline: Option<&CompiledTimeline>,
    target: &AutomationTarget,
) -> bool {
    if callback_owned && desired_timeline.is_none() {
        // A confirmed previous revision remains audible while its replacement
        // is prepared. Project/UI state already belongs to B, so forwarding
        // B's controls here would mutate A before the atomic promotion.
        return false;
    }
    !desired_timeline
        .is_some_and(|timeline| timeline_drives_native_channel_automation(timeline, target))
}

fn native_channel_pan_release(
    project: &Project,
    timeline: &CompiledTimeline,
    beat: f32,
) -> TimelineMixerPanRelease {
    let active_automation = automation_runtime_lanes_at_beat(project, beat);
    let automation_frame =
        automation_runtime::evaluate_automation_frame(&active_automation, f64::from(beat));
    let mut tracks = Vec::new();
    for target in timeline.driven_automation_targets() {
        let CompiledAutomationTarget::ChannelPan { channel_id } = *target else {
            continue;
        };
        if timeline.plugin_routes().iter().any(|route| {
            matches!(
                route.destination,
                PluginRouteDestination::Generator {
                    channel_id: routed,
                    ..
                } if routed == channel_id
            )
        }) {
            continue;
        }
        if let Some((track_id, runtime_slot)) = project
            .channels
            .iter()
            .find(|channel| channel.id == channel_id)
            .and_then(|channel| {
                project
                    .mixer_runtime_slot(channel.mixer_track)
                    .map(|runtime_slot| (channel.mixer_track, runtime_slot))
            })
        {
            tracks.push((track_id, runtime_slot));
        }
    }
    tracks.sort_unstable();
    tracks.dedup();
    let mut release = TimelineMixerPanRelease::EMPTY;
    for (track_id, runtime_slot) in tracks {
        let Some(base) = project.mixer_track_by_id(track_id).map(|state| state.pan) else {
            continue;
        };
        let automated = if runtime_slot == 0 {
            None
        } else {
            automation_frame
                .mixer_tracks
                .iter()
                .find(|values| values.track == track_id)
                .and_then(|values| values.pan)
                .map(|pan| pan as f32)
        };
        let pan = automated.unwrap_or(base).clamp(-1.0, 1.0);
        debug_assert!(release.insert(runtime_slot, pan));
    }
    release
}

const fn audio_asset_load_is_current(result_generation: u64, current_generation: u64) -> bool {
    result_generation == current_generation
}

fn timeline_source_identity_is_current(
    source_generation: u64,
    source_fingerprint: u64,
    source_sample_rate: u32,
    compiled_generation: Option<u64>,
    compiled_fingerprint: Option<u64>,
    observed_fingerprint: u64,
    device_sample_rate: u32,
) -> bool {
    compiled_generation == Some(source_generation)
        && compiled_fingerprint == Some(source_fingerprint)
        && observed_fingerprint == source_fingerprint
        && device_sample_rate == source_sample_rate
}

fn publish_audio_transport_seek(audio: &AudioEngine, tempo_map: Option<&TempoMap>, beat: f64) {
    match transport_seek_target(tempo_map, beat) {
        TransportSeekTarget::TimelineFrame { beat, frame } => {
            audio.seek_transport_to_frame(beat, frame);
        }
        TransportSeekTarget::LegacyBeat { beat } => {
            audio.seek_transport(beat);
        }
    }
}

fn publish_audio_transport_loop(
    audio: &AudioEngine,
    tempo_map: Option<&TempoMap>,
    start_beat: f64,
    end_beat: f64,
    enabled: bool,
) {
    match transport_loop_target(tempo_map, start_beat, end_beat) {
        TransportLoopTarget::TimelineFrames {
            start_beat,
            start_frame,
            end_beat,
            end_frame,
        } => {
            audio.set_transport_loop_frames(start_beat, start_frame, end_beat, end_frame, enabled);
        }
        TransportLoopTarget::LegacyBeats {
            start_beat,
            end_beat,
        } => {
            audio.set_transport_loop(start_beat, end_beat, enabled);
        }
    }
}

type BrowserSection = (
    &'static str,
    &'static [(&'static str, &'static str)],
    Color32,
);
type AudioImportResult = Result<(u64, PathBuf, wav::WavAsset, f32, usize), (u64, String)>;

