#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct ShortcutModifiers {
    command: bool,
    non_command_control: bool,
    shift: bool,
    alt: bool,
}

impl ShortcutModifiers {
    fn from_egui(modifiers: egui::Modifiers) -> Self {
        Self {
            command: modifiers.command,
            non_command_control: modifiers.ctrl && !modifiers.command,
            shift: modifiers.shift,
            alt: modifiers.alt,
        }
    }

    const fn is_plain(self) -> bool {
        !self.command && !self.non_command_control && !self.shift && !self.alt
    }

    const fn is_command_only(self) -> bool {
        self.command && !self.non_command_control && !self.shift && !self.alt
    }

    const fn is_command_shift(self) -> bool {
        self.command && !self.non_command_control && self.shift && !self.alt
    }

    const fn is_alt_only(self) -> bool {
        !self.command && !self.non_command_control && !self.shift && self.alt
    }

    const fn is_shift_only(self) -> bool {
        !self.command && !self.non_command_control && self.shift && !self.alt
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ShortcutKey {
    Space,
    Escape,
    Enter,
    S,
    O,
    N,
    Z,
    Y,
    D,
    P,
    B,
    T,
    C,
    E,
    A,
    L,
    Q,
    U,
    F,
    G,
    Delete,
    F5,
    F6,
    F7,
    F9,
    F10,
    Num1,
    Num2,
    Num3,
    Num4,
}

impl ShortcutKey {
    const PRIORITY: [Self; 30] = [
        Self::S,
        Self::O,
        Self::N,
        Self::Z,
        Self::Y,
        Self::D,
        Self::L,
        Self::A,
        Self::Q,
        Self::U,
        Self::F,
        Self::G,
        Self::P,
        Self::B,
        Self::T,
        Self::C,
        Self::E,
        Self::Delete,
        Self::Escape,
        Self::Space,
        Self::F5,
        Self::F6,
        Self::F7,
        Self::F9,
        Self::F10,
        Self::Num1,
        Self::Num2,
        Self::Num3,
        Self::Num4,
        Self::Enter,
    ];

    const fn index(self) -> usize {
        match self {
            Self::Space => 0,
            Self::Escape => 1,
            Self::Enter => 2,
            Self::S => 3,
            Self::O => 4,
            Self::N => 5,
            Self::Z => 6,
            Self::Y => 7,
            Self::D => 8,
            Self::P => 9,
            Self::B => 10,
            Self::T => 11,
            Self::C => 12,
            Self::E => 13,
            Self::A => 14,
            Self::L => 15,
            Self::Q => 16,
            Self::U => 17,
            Self::F => 18,
            Self::Delete => 19,
            Self::F5 => 20,
            Self::F6 => 21,
            Self::F7 => 22,
            Self::F9 => 23,
            Self::F10 => 24,
            Self::Num1 => 25,
            Self::Num2 => 26,
            Self::Num3 => 27,
            Self::Num4 => 28,
            Self::G => 29,
        }
    }

    const fn from_egui(key: egui::Key) -> Option<Self> {
        match key {
            egui::Key::Space => Some(Self::Space),
            egui::Key::Escape => Some(Self::Escape),
            egui::Key::Enter => Some(Self::Enter),
            egui::Key::S => Some(Self::S),
            egui::Key::O => Some(Self::O),
            egui::Key::N => Some(Self::N),
            egui::Key::Z => Some(Self::Z),
            egui::Key::Y => Some(Self::Y),
            egui::Key::D => Some(Self::D),
            egui::Key::P => Some(Self::P),
            egui::Key::B => Some(Self::B),
            egui::Key::T => Some(Self::T),
            egui::Key::C => Some(Self::C),
            egui::Key::E => Some(Self::E),
            egui::Key::A => Some(Self::A),
            egui::Key::L => Some(Self::L),
            egui::Key::Q => Some(Self::Q),
            egui::Key::U => Some(Self::U),
            egui::Key::F => Some(Self::F),
            egui::Key::G => Some(Self::G),
            egui::Key::Delete => Some(Self::Delete),
            egui::Key::F5 => Some(Self::F5),
            egui::Key::F6 => Some(Self::F6),
            egui::Key::F7 => Some(Self::F7),
            egui::Key::F9 => Some(Self::F9),
            egui::Key::F10 => Some(Self::F10),
            egui::Key::Num1 => Some(Self::Num1),
            egui::Key::Num2 => Some(Self::Num2),
            egui::Key::Num3 => Some(Self::Num3),
            egui::Key::Num4 => Some(Self::Num4),
            _ => None,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct ShortcutChord {
    key: ShortcutKey,
    modifiers: ShortcutModifiers,
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct ShortcutPresses {
    chords: [Option<ShortcutChord>; 30],
}

impl ShortcutPresses {
    fn from_events(events: &[egui::Event]) -> Self {
        let mut presses = Self::default();
        for event in events {
            let egui::Event::Key {
                key,
                pressed: true,
                repeat: false,
                modifiers,
                ..
            } = event
            else {
                continue;
            };
            let Some(key) = ShortcutKey::from_egui(*key) else {
                continue;
            };
            presses.insert(ShortcutChord {
                key,
                modifiers: ShortcutModifiers::from_egui(*modifiers),
            });
        }
        presses
    }

    fn insert(&mut self, chord: ShortcutChord) {
        let slot = &mut self.chords[chord.key.index()];
        if slot.is_none() {
            *slot = Some(chord);
        }
    }

    fn chord(self, key: ShortcutKey) -> Option<ShortcutChord> {
        self.chords[key.index()]
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ShortcutAction {
    TogglePlay,
    ToggleTransportMode,
    TogglePlaylistFades,
    Stop,
    Save,
    Open,
    NewProject,
    Undo,
    Redo,
    Duplicate,
    Delete,
    ToggleSettings,
    View(StudioView),
    Tool(ToolMode),
    PianoTool(PianoRollTool),
    PianoTransform(PianoRollTransformKind),
    QuickLegato,
    GroupPianoNotes,
    UngroupPianoNotes,
    DismissModal(ShortcutModal),
    ConfirmModal(ShortcutModal),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct ShortcutPolicy {
    context: ShortcutContext,
}

impl ShortcutPolicy {
    const fn new(context: ShortcutContext) -> Self {
        Self { context }
    }

    fn resolve(self, chord: ShortcutChord) -> Option<ShortcutAction> {
        if let Some(modal) = self.context.top_modal {
            if self.context.text_editor_active || self.context.popup_open {
                return None;
            }
            if !chord.modifiers.is_plain() {
                return None;
            }
            return match chord.key {
                ShortcutKey::Escape => Some(ShortcutAction::DismissModal(modal)),
                ShortcutKey::F10 if modal == ShortcutModal::Settings => {
                    Some(ShortcutAction::DismissModal(modal))
                }
                ShortcutKey::Enter
                    if matches!(
                        modal,
                        ShortcutModal::ProjectLifecycle
                            | ShortcutModal::PianoTransform
                            | ShortcutModal::Settings
                            | ShortcutModal::MidiImport
                            | ShortcutModal::MidiExport
                    ) =>
                {
                    Some(ShortcutAction::ConfirmModal(modal))
                }
                _ => None,
            };
        }
        if self.context.text_editor_active || self.context.popup_open || self.context.blocking_layer
        {
            return None;
        }
        resolve_global_shortcut(chord)
    }

    fn resolve_presses(self, presses: ShortcutPresses) -> Option<ShortcutAction> {
        for key in ShortcutKey::PRIORITY {
            if let Some(action) = presses.chord(key).and_then(|chord| self.resolve(chord)) {
                return Some(action);
            }
        }
        None
    }
}

fn resolve_global_shortcut(chord: ShortcutChord) -> Option<ShortcutAction> {
    let modifiers = chord.modifiers;
    match chord.key {
        ShortcutKey::S if modifiers.is_command_only() => Some(ShortcutAction::Save),
        ShortcutKey::O if modifiers.is_command_only() => Some(ShortcutAction::Open),
        ShortcutKey::N if modifiers.is_command_only() => Some(ShortcutAction::NewProject),
        ShortcutKey::Z if modifiers.is_command_only() => Some(ShortcutAction::Undo),
        ShortcutKey::Y if modifiers.is_command_only() => Some(ShortcutAction::Redo),
        ShortcutKey::Z if modifiers.is_command_shift() => Some(ShortcutAction::Redo),
        ShortcutKey::D if modifiers.is_command_only() => Some(ShortcutAction::Duplicate),
        ShortcutKey::L if modifiers.is_command_only() => Some(ShortcutAction::QuickLegato),
        ShortcutKey::L if modifiers.is_alt_only() => Some(ShortcutAction::PianoTransform(
            PianoRollTransformKind::Articulate,
        )),
        ShortcutKey::A if modifiers.is_alt_only() => Some(ShortcutAction::PianoTransform(
            PianoRollTransformKind::Arpeggiate,
        )),
        ShortcutKey::Q if modifiers.is_alt_only() => Some(ShortcutAction::PianoTransform(
            PianoRollTransformKind::Quantize,
        )),
        ShortcutKey::S if modifiers.is_alt_only() => Some(ShortcutAction::PianoTransform(
            PianoRollTransformKind::Strum,
        )),
        ShortcutKey::U if modifiers.is_alt_only() => {
            Some(ShortcutAction::PianoTransform(PianoRollTransformKind::Chop))
        }
        ShortcutKey::F if modifiers.is_alt_only() => {
            Some(ShortcutAction::PianoTransform(PianoRollTransformKind::Flam))
        }
        ShortcutKey::G if modifiers.is_shift_only() => Some(ShortcutAction::GroupPianoNotes),
        ShortcutKey::G if modifiers.is_alt_only() => Some(ShortcutAction::UngroupPianoNotes),
        ShortcutKey::F if modifiers.is_shift_only() => Some(ShortcutAction::TogglePlaylistFades),
        ShortcutKey::L if modifiers.is_plain() => Some(ShortcutAction::ToggleTransportMode),
        ShortcutKey::S if modifiers.is_plain() => Some(ShortcutAction::Tool(ToolMode::Slip)),
        ShortcutKey::P if modifiers.is_plain() => {
            Some(ShortcutAction::PianoTool(PianoRollTool::Draw))
        }
        ShortcutKey::B if modifiers.is_plain() => {
            Some(ShortcutAction::PianoTool(PianoRollTool::Paint))
        }
        ShortcutKey::D if modifiers.is_plain() => {
            Some(ShortcutAction::PianoTool(PianoRollTool::Delete))
        }
        ShortcutKey::T if modifiers.is_plain() => {
            Some(ShortcutAction::PianoTool(PianoRollTool::Mute))
        }
        ShortcutKey::C if modifiers.is_plain() => {
            Some(ShortcutAction::PianoTool(PianoRollTool::Slice))
        }
        ShortcutKey::E if modifiers.is_plain() => {
            Some(ShortcutAction::PianoTool(PianoRollTool::Select))
        }
        ShortcutKey::Space if modifiers.is_plain() => Some(ShortcutAction::TogglePlay),
        ShortcutKey::Escape if modifiers.is_plain() => Some(ShortcutAction::Stop),
        ShortcutKey::Delete if modifiers.is_plain() => Some(ShortcutAction::Delete),
        ShortcutKey::F5 if modifiers.is_plain() => Some(ShortcutAction::View(StudioView::Playlist)),
        ShortcutKey::F6 if modifiers.is_plain() => {
            Some(ShortcutAction::View(StudioView::ChannelRack))
        }
        ShortcutKey::F7 if modifiers.is_plain() => {
            Some(ShortcutAction::View(StudioView::PianoRoll))
        }
        ShortcutKey::F9 if modifiers.is_plain() => Some(ShortcutAction::View(StudioView::Mixer)),
        ShortcutKey::F10 if modifiers.is_plain() => Some(ShortcutAction::ToggleSettings),
        ShortcutKey::Num1 if modifiers.is_plain() => Some(ShortcutAction::Tool(ToolMode::Select)),
        ShortcutKey::Num2 if modifiers.is_plain() => Some(ShortcutAction::Tool(ToolMode::Draw)),
        ShortcutKey::Num3 if modifiers.is_plain() => Some(ShortcutAction::Tool(ToolMode::Slice)),
        ShortcutKey::Num4 if modifiers.is_plain() => Some(ShortcutAction::Tool(ToolMode::Mute)),
        _ => None,
    }
}

