#[derive(Debug, Default)]
enum ProjectLifecycle {
    #[default]
    Idle,
    WaitingForBarriers {
        intent: ProjectIntent,
        stop_requested: bool,
    },
    AwaitingDecision {
        intent: ProjectIntent,
        failure: Option<String>,
    },
    Saving {
        intent: ProjectIntent,
        operation_id: u64,
    },
    CriticalIoFailed {
        intent: ProjectIntent,
        message: String,
    },
    ExitArmed {
        close_command_sent: bool,
    },
}

impl ProjectLifecycle {
    fn is_idle(&self) -> bool {
        matches!(self, Self::Idle)
    }

    fn is_modal(&self) -> bool {
        matches!(
            self,
            Self::WaitingForBarriers { .. }
                | Self::AwaitingDecision { .. }
                | Self::Saving { .. }
                | Self::CriticalIoFailed { .. }
        )
    }

    fn exit_is_armed(&self) -> bool {
        matches!(self, Self::ExitArmed { .. })
    }

    fn intent_kind(&self) -> Option<ProjectIntentKind> {
        match self {
            Self::WaitingForBarriers { intent, .. }
            | Self::AwaitingDecision { intent, .. }
            | Self::Saving { intent, .. }
            | Self::CriticalIoFailed { intent, .. } => Some(intent.kind()),
            Self::Idle | Self::ExitArmed { .. } => None,
        }
    }

    fn request(
        &mut self,
        intent: ProjectIntent,
        dirty: bool,
        barriers_active: bool,
    ) -> Option<ProjectIntent> {
        if !self.is_idle() {
            return None;
        }
        if barriers_active {
            *self = Self::WaitingForBarriers {
                intent,
                stop_requested: false,
            };
            None
        } else if dirty {
            *self = Self::AwaitingDecision {
                intent,
                failure: None,
            };
            None
        } else {
            Some(intent)
        }
    }

    fn mark_stop_requested(&mut self) {
        if let Self::WaitingForBarriers { stop_requested, .. } = self {
            *stop_requested = true;
        }
    }

    fn barriers_cleared(&mut self, dirty: bool) -> Option<ProjectIntent> {
        let state = std::mem::replace(self, Self::Idle);
        let Self::WaitingForBarriers { intent, .. } = state else {
            *self = state;
            return None;
        };
        if dirty {
            *self = Self::AwaitingDecision {
                intent,
                failure: None,
            };
            None
        } else {
            Some(intent)
        }
    }

    fn fail_critical_io(&mut self, message: String) -> bool {
        let state = std::mem::replace(self, Self::Idle);
        let Self::WaitingForBarriers { intent, .. } = state else {
            *self = state;
            return false;
        };
        *self = Self::CriticalIoFailed { intent, message };
        true
    }

    fn continue_after_critical_io_failure(&mut self, dirty: bool) -> Option<ProjectIntent> {
        let state = std::mem::replace(self, Self::Idle);
        let Self::CriticalIoFailed { intent, .. } = state else {
            *self = state;
            return None;
        };
        if dirty {
            *self = Self::AwaitingDecision {
                intent,
                failure: None,
            };
            None
        } else {
            Some(intent)
        }
    }

    fn begin_save(&mut self, operation_id: u64) -> bool {
        let state = std::mem::replace(self, Self::Idle);
        let Self::AwaitingDecision { intent, .. } = state else {
            *self = state;
            return false;
        };
        *self = Self::Saving {
            intent,
            operation_id,
        };
        true
    }

    fn discard(&mut self) -> Option<ProjectIntent> {
        let state = std::mem::replace(self, Self::Idle);
        match state {
            Self::AwaitingDecision { intent, .. } | Self::CriticalIoFailed { intent, .. } => {
                Some(intent)
            }
            other => {
                *self = other;
                None
            }
        }
    }

    fn cancel(&mut self) -> bool {
        if matches!(
            self,
            Self::WaitingForBarriers { .. }
                | Self::AwaitingDecision { .. }
                | Self::CriticalIoFailed { .. }
        ) {
            *self = Self::Idle;
            true
        } else {
            false
        }
    }

    fn complete_save(
        &mut self,
        completion: &ProjectSaveCompletion,
        current_fingerprint: u64,
    ) -> Option<ProjectIntent> {
        let state = std::mem::replace(self, Self::Idle);
        let Self::Saving {
            intent,
            operation_id,
        } = state
        else {
            *self = state;
            return None;
        };
        if operation_id != completion.operation_id {
            *self = Self::Saving {
                intent,
                operation_id,
            };
            return None;
        }

        match &completion.outcome {
            ProjectSaveOutcome::Clean if completion.fingerprint == current_fingerprint => {
                Some(intent)
            }
            ProjectSaveOutcome::Clean => {
                *self = Self::AwaitingDecision {
                    intent,
                    failure: Some(
                        "The project changed after its save snapshot; save again before continuing"
                            .into(),
                    ),
                };
                None
            }
            ProjectSaveOutcome::StalePluginState { count } => {
                *self = Self::AwaitingDecision {
                    intent,
                    failure: Some(format!(
                        "The file was written with {count} stale plug-in state(s); the project is still unsaved"
                    )),
                };
                None
            }
            ProjectSaveOutcome::TopologyTimeout(message)
            | ProjectSaveOutcome::IoFailed(message) => {
                *self = Self::AwaitingDecision {
                    intent,
                    failure: Some(message.clone()),
                };
                None
            }
        }
    }

    fn arm_exit(&mut self) {
        *self = Self::ExitArmed {
            close_command_sent: false,
        };
    }

    fn mark_close_command_sent(&mut self) -> bool {
        let Self::ExitArmed { close_command_sent } = self else {
            return false;
        };
        if *close_command_sent {
            false
        } else {
            *close_command_sent = true;
            true
        }
    }
}

