    fn select_playlist_clip_only(&mut self, clip_id: u32) {
        self.selected_clip = (clip_id != 0).then_some(clip_id);
        self.playlist_selection_ids.clear();
        if clip_id != 0 {
            self.playlist_selection_ids.insert(clip_id);
        }
    }

    fn clear_playlist_selection(&mut self) {
        self.selected_clip = None;
        self.playlist_selection_ids.clear();
    }

    fn retain_playlist_selection(&mut self) {
        self.playlist_selection_ids
            .retain(|id| self.project.clips.iter().any(|clip| clip.id == *id));
        if self
            .selected_clip
            .is_some_and(|id| !self.playlist_selection_ids.contains(&id))
        {
            self.selected_clip = self.playlist_selection_ids.iter().copied().min();
        }
    }

    fn finish_playlist_gesture(&mut self) {
        let Some(before) = self.playlist_gesture_before.take() else {
            return;
        };
        let after = std::mem::replace(&mut self.project, before);
        if commit_explicit_project_history_transaction(
            &mut self.project,
            &mut self.history_snapshot,
            &mut self.history_fingerprint,
            &mut self.undo_stack,
            &mut self.redo_stack,
            &mut self.dirty,
            after,
        ) {
            let now = Instant::now();
            self.last_history_check = now;
            self.last_history_capture = now;
            self.automation_evaluator.reset();
            self.refresh_timeline_fingerprint(now, true);
        }
        self.retain_playlist_selection();
    }

    fn finish_piano_roll_gesture(&mut self) {
        let Some(before) = self.piano_roll_gesture_before.take() else {
            return;
        };
        let after = std::mem::replace(&mut self.project, before);
        if commit_explicit_project_history_transaction(
            &mut self.project,
            &mut self.history_snapshot,
            &mut self.history_fingerprint,
            &mut self.undo_stack,
            &mut self.redo_stack,
            &mut self.dirty,
            after,
        ) {
            let now = Instant::now();
            self.last_history_check = now;
            self.last_history_capture = now;
            self.automation_evaluator.reset();
            self.refresh_timeline_fingerprint(now, true);
        }
    }

    fn quick_legato_piano_roll(&mut self) {
        if self.piano_roll_transform.is_some() {
            return;
        }
        if self.piano_roll_gesture_before.is_some() {
            self.finish_piano_roll_gesture();
        }
        let Some(channel) = self.project.channels.get(self.selected_channel) else {
            self.notify("Quick legato needs an active Channel".into());
            return;
        };
        let channel_id = channel.id;
        let channel_name = channel.name.clone();
        let notes = &self.project.active_pattern().notes;
        let expanded_selection = expand_note_group_selection(
            notes,
            &self.piano_roll_state.selection_ids,
            self.piano_roll_state.grouping_enabled,
        );
        let selected_targets = notes
            .iter()
            .filter(|note| {
                note.channel_id == Some(channel_id) && expanded_selection.contains(&note.id)
            })
            .map(|note| note.id)
            .collect::<HashSet<_>>();
        let target_ids = if selected_targets.is_empty() {
            notes
                .iter()
                .filter(|note| note.channel_id == Some(channel_id))
                .map(|note| note.id)
                .collect::<HashSet<_>>()
        } else {
            selected_targets
        };
        if target_ids.is_empty() {
            self.notify(format!(
                "{channel_name} has no editable notes for Quick legato"
            ));
            return;
        }
        let settings = PianoRollTransformSettings::Articulate(ArticulateSettings::for_preset(
            ArticulationPreset::Legato,
        ));
        let edit = match transform_piano_notes(
            notes,
            &target_ids,
            PianoRollTransformKind::Articulate,
            &settings,
            self.effective_tempo.max(1.0),
        ) {
            Ok(edit) => edit,
            Err(error) => {
                self.notify(format!("Quick legato was not applied: {error}"));
                return;
            }
        };
        let mut candidate = self.project.clone();
        candidate.active_pattern_mut().notes = edit.notes;
        let committed = commit_explicit_project_history_transaction(
            &mut self.project,
            &mut self.history_snapshot,
            &mut self.history_fingerprint,
            &mut self.undo_stack,
            &mut self.redo_stack,
            &mut self.dirty,
            candidate,
        );
        self.piano_roll_state.selection_ids = edit.selection_ids;
        self.piano_roll_state
            .retain_existing(&self.project.active_pattern().notes);
        let now = Instant::now();
        if committed {
            self.last_history_check = now;
            self.last_history_capture = now;
            self.notify(format!(
                "Quick legato applied to {} note(s) in {channel_name}",
                edit.transformed_notes
            ));
        } else {
            self.notify("Quick legato made no note changes".into());
        }
        self.automation_evaluator.reset();
        self.refresh_timeline_fingerprint(now, true);
    }

    fn begin_piano_roll_transform(&mut self, kind: PianoRollTransformKind) {
        if self.piano_roll_transform.is_some() {
            return;
        }
        if self.piano_roll_gesture_before.is_some() {
            self.finish_piano_roll_gesture();
        }
        let Some(channel) = self.project.channels.get(self.selected_channel) else {
            self.notify("Piano Roll transform needs an active Channel".into());
            return;
        };
        let channel_id = channel.id;
        let channel_name = channel.name.clone();
        let notes = &self.project.active_pattern().notes;
        let expanded_selection = expand_note_group_selection(
            notes,
            &self.piano_roll_state.selection_ids,
            self.piano_roll_state.grouping_enabled,
        );
        let selected_targets = notes
            .iter()
            .filter(|note| {
                note.channel_id == Some(channel_id) && expanded_selection.contains(&note.id)
            })
            .map(|note| note.id)
            .collect::<HashSet<_>>();
        let scope_was_selection = !selected_targets.is_empty();
        let target_ids = if scope_was_selection {
            selected_targets
        } else {
            notes
                .iter()
                .filter(|note| note.channel_id == Some(channel_id))
                .map(|note| note.id)
                .collect::<HashSet<_>>()
        };
        if target_ids.is_empty() {
            self.notify(format!(
                "{} has no editable notes for {}",
                kind.label(),
                channel_name
            ));
            return;
        }
        let snap = self.piano_roll_state.local_snap.max(0.05);
        self.piano_roll_transform = Some(PianoRollTransformSession {
            kind,
            settings: PianoRollTransformSettings::for_kind(kind, snap),
            before_project: self.project.clone(),
            before_selection_ids: self.piano_roll_state.selection_ids.clone(),
            target_ids,
            scope_was_selection,
            target_channel_name: channel_name,
            tempo_bpm: self.effective_tempo.max(1.0),
            preview_note_count: 0,
            preview_generated_count: 0,
            preview_error: None,
        });
        self.refresh_piano_roll_transform_preview();
    }

    fn refresh_piano_roll_transform_preview(&mut self) {
        let calculation = {
            let Some(session) = self.piano_roll_transform.as_ref() else {
                return;
            };
            transform_piano_notes(
                &session.before_project.active_pattern().notes,
                &session.target_ids,
                session.kind,
                &session.settings,
                session.tempo_bpm,
            )
        };
        match calculation {
            Ok(result) => {
                let Some(session) = self.piano_roll_transform.as_mut() else {
                    return;
                };
                let mut candidate = session.before_project.clone();
                candidate.active_pattern_mut().notes = result.notes;
                self.project = candidate;
                self.piano_roll_state.selection_ids = result.selection_ids;
                session.preview_note_count = result.transformed_notes;
                session.preview_generated_count = result.generated_notes;
                session.preview_error = None;
            }
            Err(error) => {
                let Some(session) = self.piano_roll_transform.as_mut() else {
                    return;
                };
                self.project = session.before_project.clone();
                self.piano_roll_state.selection_ids = session.before_selection_ids.clone();
                session.preview_note_count = 0;
                session.preview_generated_count = 0;
                session.preview_error = Some(error.to_string());
            }
        }
        self.automation_evaluator.reset();
        self.refresh_timeline_fingerprint(Instant::now(), true);
    }

    fn cancel_piano_roll_transform(&mut self) {
        let Some(session) = self.piano_roll_transform.take() else {
            return;
        };
        self.project = session.before_project;
        self.piano_roll_state.selection_ids = session.before_selection_ids;
        self.automation_evaluator.reset();
        self.refresh_timeline_fingerprint(Instant::now(), true);
        self.notify(format!("{} preview canceled", session.kind.label()));
    }

    fn accept_piano_roll_transform(&mut self) {
        let Some(session) = self.piano_roll_transform.take() else {
            return;
        };
        if let Some(error) = session.preview_error {
            self.project = session.before_project;
            self.piano_roll_state.selection_ids = session.before_selection_ids;
            self.automation_evaluator.reset();
            self.refresh_timeline_fingerprint(Instant::now(), true);
            self.notify(format!("{} was not applied: {error}", session.kind.label()));
            return;
        }
        let preview_selection = self.piano_roll_state.selection_ids.clone();
        let candidate = std::mem::replace(&mut self.project, session.before_project);
        let committed = commit_explicit_project_history_transaction(
            &mut self.project,
            &mut self.history_snapshot,
            &mut self.history_fingerprint,
            &mut self.undo_stack,
            &mut self.redo_stack,
            &mut self.dirty,
            candidate,
        );
        self.piano_roll_state.selection_ids = preview_selection;
        self.piano_roll_state
            .retain_existing(&self.project.active_pattern().notes);
        let now = Instant::now();
        if committed {
            self.last_history_check = now;
            self.last_history_capture = now;
            self.notify(format!(
                "{} applied to {} note(s){}",
                session.kind.label(),
                session.preview_note_count,
                if session.preview_generated_count == 0 {
                    String::new()
                } else {
                    format!(" · {} generated", session.preview_generated_count)
                }
            ));
        } else {
            self.notify(format!("{} made no note changes", session.kind.label()));
        }
        self.automation_evaluator.reset();
        self.refresh_timeline_fingerprint(now, true);
    }

    fn delete_selection(&mut self) {
        match self.view {
            StudioView::Playlist => {
                let selected = expand_clip_group_selection(
                    &self.project.clips,
                    &self.playlist_selection_ids,
                    self.piano_roll_state.grouping_enabled,
                );
                if selected.is_empty() {
                    return;
                }
                let mut candidate = self.project.clone();
                candidate.clips.retain(|clip| !selected.contains(&clip.id));
                candidate
                    .audio_clip_mixer_destinations
                    .retain(|destination| !selected.contains(&destination.clip_id));
                candidate.automation_lanes.retain(|automation| {
                    candidate
                        .clips
                        .iter()
                        .any(|clip| clip.automation_id == Some(automation.id))
                });
                normalize_playlist_clip_groups(&mut candidate.clips);
                if commit_explicit_project_history_transaction(
                    &mut self.project,
                    &mut self.history_snapshot,
                    &mut self.history_fingerprint,
                    &mut self.undo_stack,
                    &mut self.redo_stack,
                    &mut self.dirty,
                    candidate,
                ) {
                    self.clear_playlist_selection();
                    let now = Instant::now();
                    self.last_history_check = now;
                    self.last_history_capture = now;
                    self.refresh_timeline_fingerprint(now, true);
                }
            }
            StudioView::PianoRoll => {
                let selected = expand_note_group_selection(
                    &self.project.active_pattern().notes,
                    &self.piano_roll_state.selection_ids,
                    self.piano_roll_state.grouping_enabled,
                );
                self.project
                    .active_pattern_mut()
                    .notes
                    .retain(|note| !selected.contains(&note.id));
                normalize_piano_note_groups(&mut self.project.active_pattern_mut().notes);
                self.piano_roll_state.clear_selection();
            }
            StudioView::ChannelRack | StudioView::Mixer => {}
        }
    }

    fn toggle_play(&mut self) {
        if !self.audio_restart_state.allows_realtime_session_actions() {
            self.notify(
                "Playback remains paused until the audio device transaction confirms".into(),
            );
            return;
        }
        if self.playing && !self.midi_recording.is_idle() {
            self.request_midi_recording_stop(MidiRecordAfterStop::PauseAtCurrent);
            return;
        }
        if !self.playing && !self.plugin_runtime_is_ready_for_transport() {
            self.notify(
                "Playback is waiting for the current project's plug-in graph to be confirmed"
                    .into(),
            );
            return;
        }
        let callback_owned = self.callback_timeline_owns_note_clip();
        self.playing = !self.playing;
        if !self.playing {
            self.stop_all_plugin_notes();
            if let Some(audio) = &self.audio {
                audio.set_playing(false);
            }
            return;
        }
        if callback_owned && self.request_timeline_resume_chase() {
            // The chase confirmation publishes the exact discontinuity and
            // resumes playback. Until then the callback remains paused.
            return;
        }
        if let Some(audio) = &self.audio {
            audio.set_playing(true);
        }
    }

    fn stop(&mut self) {
        if self.input_recorder.is_some() {
            self.finish_input_recording();
        }
        if !self.midi_recording.is_idle() {
            self.request_midi_recording_stop(MidiRecordAfterStop::StopAndResetZero);
            return;
        }
        self.playing = false;
        self.recording = false;
        self.beat_position = 0.0;
        self.last_step = usize::MAX;
        self.active_audio_clips.clear();
        self.pending_generator_note_offs.clear();
        if let Some(audio) = &self.audio {
            // Pause is immediate; the frame-zero discontinuity below still
            // waits for its exact prepared one-shot chase.
            audio.set_playing(false);
            audio.set_recording(false);
        }
        self.publish_transport_seek(0.0);
    }

    fn toggle_record(&mut self) {
        if !self.audio_restart_state.allows_realtime_session_actions() {
            self.notify("Recording is unavailable during an audio device transaction".into());
            return;
        }
        if !self.midi_recording.is_idle() {
            self.request_midi_recording_stop(MidiRecordAfterStop::ContinuePlayback);
            return;
        }
        if self.active_midi_input_owner().is_some() {
            self.begin_midi_recording();
            return;
        }
        if self.input_recorder.is_some() {
            self.finish_input_recording();
            return;
        }
        if self.pending_recording.is_some() {
            self.notify("The previous recording is still being written".into());
            return;
        }
        if !self.plugin_runtime_is_ready_for_transport() {
            self.notify(
                "Recording is waiting for the current project's plug-in graph to be confirmed"
                    .into(),
            );
            return;
        }

        let Some(path) = self.next_recording_path() else {
            return;
        };
        match InputRecorder::start_with_profile_to_path(
            path,
            &self.audio_preferences.requested_input,
        ) {
            Ok(recorder) => {
                let device = recorder.device_name().to_owned();
                let channels = recorder.channels();
                let sample_rate = recorder.sample_rate();
                let maximum_minutes =
                    recorder.status().maximum_frames as f64 / f64::from(sample_rate.max(1)) / 60.0;
                self.recording_started_beat = self.beat_position;
                self.recording_track = self
                    .selected_clip
                    .and_then(|id| {
                        self.project
                            .clips
                            .iter()
                            .find(|clip| clip.id == id)
                            .map(|clip| clip.track)
                    })
                    .unwrap_or(4);
                self.input_recorder = Some(recorder);
                self.recording = true;
                self.playing = true;
                let wait_for_chase =
                    self.callback_timeline_owns_note_clip() && self.request_timeline_resume_chase();
                if let Some(audio) = &self.audio {
                    if !wait_for_chase {
                        audio.set_playing(true);
                    }
                    audio.set_recording(true);
                }
                self.notify(format!(
                    "Recording {device} ({channels} ch, {sample_rate} Hz; safe WAV limit {maximum_minutes:.1} min)"
                ));
            }
            Err(error) => self.notify(format!("Unable to record: {error}")),
        }
    }

    fn next_recording_path(&mut self) -> Option<PathBuf> {
        let timestamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_millis();
        let file_name = format!("Recording-{timestamp}.wav");
        if let Some(directory) = &self.recordings_dir {
            return Some(directory.join(file_name));
        }
        rfd::FileDialog::new()
            .add_filter("24-bit WAV audio", &["wav"])
            .set_file_name(file_name)
            .save_file()
    }

    fn finish_input_recording(&mut self) {
        let Some(recorder) = self.input_recorder.take() else {
            return;
        };
        self.recording = false;
        if let Some(audio) = &self.audio {
            audio.set_recording(false);
        }
        match recorder.stop() {
            Ok(pending) => {
                self.pending_recording = Some(pending);
                self.notify("Finalizing 24-bit WAV recording…".into());
            }
            Err(error) => self.report_project_lifecycle_critical_io_failure(format!(
                "Unable to finalize recording: {error}"
            )),
        }
    }

    fn poll_recording(&mut self) {
        let active_must_stop = self.input_recorder.as_ref().is_some_and(|recorder| {
            let status = recorder.status();
            status.writer_errors != 0 || status.limit_reached
        });
        if active_must_stop {
            self.finish_input_recording();
        }
        let ready = self
            .pending_recording
            .as_ref()
            .is_some_and(PendingRecording::is_finished);
        if !ready {
            return;
        }
        let Some(pending) = self.pending_recording.take() else {
            return;
        };
        match pending.finish() {
            Ok(metadata) => self.add_recording_to_project(metadata, true),
            Err(error) => self.report_project_lifecycle_critical_io_failure(format!(
                "Recording write failed: {error}"
            )),
        }
    }

    fn toggle_realtime_master_capture(&mut self) {
        if self.master_capture.is_some() {
            self.request_realtime_master_capture_stop();
        } else {
            self.start_realtime_master_capture();
        }
    }

    fn start_realtime_master_capture(&mut self) {
        if !self.audio_restart_state.allows_realtime_session_actions() {
            self.notify(
                "Realtime Master Capture is unavailable during an audio device transaction".into(),
            );
            return;
        }
        if self.pending_master_capture.is_some() {
            self.notify("The previous Realtime Master Capture is still being finalized".into());
            return;
        }
        let Some(sample_rate) = self
            .audio
            .as_ref()
            .map(|audio| audio.snapshot().sample_rate)
            .filter(|sample_rate| *sample_rate != 0)
        else {
            self.notify("Realtime Master Capture requires an active audio device".into());
            return;
        };
        let file_name = format!("{}-realtime-master.wav", self.project.name);
        let Some(path) = rfd::FileDialog::new()
            .add_filter("24-bit stereo WAV audio", &["wav"])
            .set_file_name(file_name)
            .save_file()
        else {
            return;
        };
        if path.exists() {
            self.notify(format!(
                "Realtime Master Capture will not overwrite {}. Choose a new path.",
                path.display()
            ));
            return;
        }
        let session = match MasterCaptureSession::start_to_path(path.clone(), sample_rate) {
            Ok(session) => session,
            Err(error) => {
                self.notify(format!("Unable to start Realtime Master Capture: {error}"));
                return;
            }
        };
        let (endpoint, control) = session.into_parts();
        let capture_id = control.session_id();
        let queued = self
            .audio
            .as_mut()
            .is_some_and(|audio| audio.install_master_capture(capture_id, endpoint));
        if !queued {
            drop(control);
            self.notify(
                "Realtime Master Capture was not queued; the audio command queue is full".into(),
            );
            return;
        }
        self.master_capture = Some(ActiveMasterCapture {
            capture_id,
            path: path.clone(),
            control,
            phase: MasterCapturePhase::Installing,
            start_device_frame: None,
        });
        self.last_master_capture = None;
        self.notify(format!(
            "Installing Realtime Master Capture at {} Hz: {}",
            sample_rate,
            path.display()
        ));
    }

    fn request_realtime_master_capture_stop(&mut self) {
        let Some(capture_id) = self.master_capture.as_ref().and_then(|capture| {
            (capture.phase != MasterCapturePhase::Stopping).then_some(capture.capture_id)
        }) else {
            return;
        };
        let queued = self
            .audio
            .as_mut()
            .is_some_and(|audio| audio.stop_master_capture(capture_id));
        if queued {
            if let Some(capture) = self.master_capture.as_mut()
                && capture.capture_id == capture_id
            {
                capture.phase = MasterCapturePhase::Stopping;
            }
            self.notify("Stopping Realtime Master Capture at the next callback boundary...".into());
        } else {
            self.notify("Realtime Master Capture stop was not queued; it will be retried".into());
        }
    }

    fn poll_master_capture(&mut self) {
        for _ in 0..MAX_MASTER_CAPTURE_EVENTS_PER_FRAME {
            let event = self
                .audio
                .as_mut()
                .and_then(AudioEngine::next_master_capture_event);
            let Some(event) = event else {
                break;
            };
            self.handle_master_capture_event(event);
        }

        let must_stop = self.master_capture.as_ref().is_some_and(|capture| {
            let status = capture.control.status();
            capture.phase != MasterCapturePhase::Stopping
                && (status.writer_errors != 0 || status.limit_reached)
        });
        if must_stop {
            self.request_realtime_master_capture_stop();
        }

        let ready = self
            .pending_master_capture
            .as_ref()
            .is_some_and(|capture| capture.pending.is_finished());
        if !ready {
            return;
        }
        let Some(capture) = self.pending_master_capture.take() else {
            return;
        };
        match capture.pending.finish() {
            Ok(metadata) => {
                let warning = master_capture_metadata_diagnostics(&metadata);
                if metadata.is_valid() {
                    self.notify(format!(
                        "Realtime Master Capture saved {:.2}s to {}",
                        metadata.duration.as_secs_f32(),
                        metadata.path.display()
                    ));
                } else {
                    let message = format!(
                        "Realtime Master Capture saved but is INVALID ({warning}): {}",
                        metadata.path.display()
                    );
                    self.report_project_lifecycle_critical_io_failure(message);
                }
                self.last_master_capture = Some(metadata);
            }
            Err(error) => self.report_project_lifecycle_critical_io_failure(format!(
                "Realtime Master Capture finalization failed for {}: {error}",
                capture.path.display()
            )),
        }
    }

    fn handle_master_capture_event(&mut self, event: MasterCaptureEndpointEvent) {
        match event {
            MasterCaptureEndpointEvent::Installed {
                capture_id,
                start_device_frame,
                success,
                returned_endpoint,
            } => {
                let matches_active = self
                    .master_capture
                    .as_ref()
                    .is_some_and(|capture| capture.capture_id == capture_id);
                if success && matches_active {
                    debug_assert!(returned_endpoint.is_none());
                    if let Some(capture) = self.master_capture.as_mut() {
                        if capture.phase == MasterCapturePhase::Installing {
                            capture.phase = MasterCapturePhase::Running;
                        }
                        capture.start_device_frame = Some(start_device_frame);
                    }
                    self.notify(format!(
                        "Realtime Master Capture started at device frame {start_device_frame}"
                    ));
                } else {
                    drop(returned_endpoint);
                    if matches_active {
                        let capture = self.master_capture.take();
                        drop(capture);
                        self.report_project_lifecycle_critical_io_failure(
                            "Audio callback rejected Realtime Master Capture".into(),
                        );
                    }
                }
            }
            MasterCaptureEndpointEvent::Stopped {
                capture_id,
                end_device_frame: _,
                returned_endpoint,
            } => {
                if let Some(endpoint) = returned_endpoint {
                    self.finalize_detached_master_capture(capture_id, endpoint);
                } else if self
                    .master_capture
                    .as_ref()
                    .is_some_and(|capture| capture.capture_id == capture_id)
                {
                    let capture = self.master_capture.take();
                    drop(capture);
                    self.report_project_lifecycle_critical_io_failure(
                        "Audio callback could not return the requested master tap".into(),
                    );
                }
            }
            MasterCaptureEndpointEvent::Cleared {
                capture_id,
                returned_endpoint,
                ..
            } => match (capture_id, returned_endpoint) {
                (Some(capture_id), Some(endpoint)) => {
                    self.finalize_detached_master_capture(capture_id, endpoint);
                }
                (capture_id, None)
                    if self.master_capture.as_ref().is_some_and(|capture| {
                        capture_id.is_none_or(|capture_id| capture.capture_id == capture_id)
                    }) =>
                {
                    let capture = self.master_capture.take();
                    drop(capture);
                    self.report_project_lifecycle_critical_io_failure(
                        "Audio callback cleared the master tap without returning its endpoint"
                            .into(),
                    );
                }
                (_, returned_endpoint) => drop(returned_endpoint),
            },
        }
    }

    fn finalize_detached_master_capture(
        &mut self,
        capture_id: u64,
        endpoint: MasterCaptureEndpoint,
    ) {
        let matches_active = self
            .master_capture
            .as_ref()
            .is_some_and(|capture| capture.capture_id == capture_id);
        if !matches_active {
            drop(endpoint);
            return;
        }
        let Some(capture) = self.master_capture.take() else {
            drop(endpoint);
            return;
        };
        match capture.control.stop(endpoint) {
            Ok(pending) => {
                self.pending_master_capture = Some(FinalizingMasterCapture {
                    path: capture.path,
                    pending,
                });
                self.notify("Finalizing Realtime Master Capture as durable PCM24 WAV...".into());
            }
            Err(error) => self.report_project_lifecycle_critical_io_failure(format!(
                "Unable to finalize Realtime Master Capture {}: {error}",
                capture.path.display()
            )),
        }
    }

    fn add_recording_to_project(&mut self, metadata: RecordingMetadata, notify_and_load: bool) {
        let asset_id = self
            .project
            .audio_assets
            .iter()
            .map(|asset| asset.id)
            .max()
            .unwrap_or(0)
            + 1;
        let clip_id = self
            .project
            .clips
            .iter()
            .map(|clip| clip.id)
            .max()
            .unwrap_or(0)
            + 1;
        let name = metadata
            .path
            .file_stem()
            .and_then(|value| value.to_str())
            .unwrap_or("Recording")
            .to_owned();
        let duration_beats = (metadata.duration.as_secs_f32() * self.effective_tempo / 60.0)
            .max(self.snap.max(0.0625));
        self.project.audio_assets.push(AudioAsset {
            id: asset_id,
            name: name.clone(),
            path: metadata.path.clone(),
            sample_rate: metadata.sample_rate,
            channels: metadata.channels,
            bits_per_sample: metadata.bits_per_sample,
            frames: metadata.frames,
            waveform_peaks: Vec::new(),
        });
        self.project.clips.push(crate::model::Clip {
            id: clip_id,
            track: self.recording_track,
            start: self.recording_started_beat,
            length: duration_beats,
            name,
            color: [255, 207, 99],
            kind: ClipKind::Audio,
            group_id: None,
            pattern_id: self.project.active_pattern().id,
            automation_id: None,
            audio_asset_id: Some(asset_id),
            source_offset: 0.0,
            audio_source_offset_frame: Some(0),
            audio_source_reference: None,
            audio_length_reference: None,
            fade_in_reference: None,
            fade_out_reference: None,
            gain: 1.0,
            fade_in: 0.0,
            fade_out: 0.0,
            muted: false,
        });
        if let Some(mixer_track_id) = self
            .project
            .mixer_track_id_at_runtime_slot(self.recording_track.saturating_add(1).min(31))
        {
            self.project
                .audio_clip_mixer_destinations
                .push(AudioClipMixerDestination {
                    clip_id,
                    mixer_track_id,
                });
        }
        self.project.song_length_beats = self
            .project
            .song_length_beats
            .max(self.recording_started_beat + duration_beats);
        self.select_playlist_clip_only(clip_id);
        self.view = StudioView::Playlist;
        self.dirty = true;
        if !notify_and_load {
            return;
        }
        self.queue_audio_asset_load(asset_id, metadata.path.clone());
        let mut diagnostics = Vec::new();
        if metadata.dropouts != 0 {
            diagnostics.push(format!("{} dropouts", metadata.dropouts));
        }
        if metadata.truncated {
            diagnostics.push(format!(
                "truncated at the safe WAV import limit; {} samples omitted",
                metadata.limit_discarded_samples
            ));
        }
        let diagnostics = if diagnostics.is_empty() {
            String::new()
        } else {
            format!(" ({})", diagnostics.join(", "))
        };
        self.notify(format!(
            "Recorded {:.2}s to {}{diagnostics}",
            metadata.duration.as_secs_f32(),
            metadata.path.display(),
        ));
    }

    fn handle_shortcuts(
        &mut self,
        ctx: &egui::Context,
        modal_at_frame_start: Option<ShortcutModal>,
        blocker_at_frame_start: bool,
    ) {
        let context = self.shortcut_context(ctx, modal_at_frame_start, blocker_at_frame_start);
        let policy = ShortcutPolicy::new(context);
        let presses = ctx.input(|input| ShortcutPresses::from_events(&input.events));
        if let Some(action) = policy.resolve_presses(presses) {
            self.apply_shortcut_action(action);
        }
    }

    fn shortcut_context(
        &self,
        ctx: &egui::Context,
        modal_at_frame_start: Option<ShortcutModal>,
        blocker_at_frame_start: bool,
    ) -> ShortcutContext {
        ShortcutContext {
            // A focused non-text widget must not permanently swallow Space.
            // Actual text/numeric editors and open popups still own keyboard
            // input so typing or choosing a menu item never starts transport.
            text_editor_active: ctx.text_edit_focused(),
            popup_open: ctx.any_popup_open(),
            blocking_layer: blocker_at_frame_start || self.shortcut_blocking_layer_active(),
            top_modal: modal_at_frame_start.or_else(|| self.top_shortcut_modal()),
        }
    }

    fn shortcut_blocking_layer_active(&self) -> bool {
        !self.project_lifecycle.is_idle()
            || self.project_media.open
            || self.audio_restart_state.locks_session_actions()
            || self.recovery_available
            || self.save_barrier.is_some()
            || self.queued_save_request.is_some()
            || self.pending_recording.is_some()
            || self.pending_master_capture.is_some()
            || self.export_dialog.is_open()
    }

    fn top_shortcut_modal(&self) -> Option<ShortcutModal> {
        if self.project_lifecycle.is_modal() {
            Some(ShortcutModal::ProjectLifecycle)
        } else if self.recovery_available {
            Some(ShortcutModal::Recovery)
        } else if self.project_media.open {
            Some(ShortcutModal::ProjectMedia)
        } else if self.export_dialog.is_open() {
            Some(ShortcutModal::WavExport)
        } else if self.piano_roll_transform.is_some() {
            Some(ShortcutModal::PianoTransform)
        } else if self.pending_midi_export.is_some() {
            Some(ShortcutModal::MidiExport)
        } else if self.pending_midi_import.is_some() {
            Some(ShortcutModal::MidiImport)
        } else if self.show_settings {
            Some(ShortcutModal::Settings)
        } else if self.show_plugins || self.plugin_picker_target.is_some() {
            Some(ShortcutModal::PluginManager)
        } else {
            None
        }
    }

    fn apply_shortcut_action(&mut self, action: ShortcutAction) {
        match action {
            ShortcutAction::TogglePlay => self.toggle_play(),
            ShortcutAction::ToggleTransportMode => self.toggle_transport_mode(),
            ShortcutAction::TogglePlaylistFades => {
                if self.view == StudioView::Playlist {
                    self.show_playlist_fades = !self.show_playlist_fades;
                }
            }
            ShortcutAction::Stop => self.stop(),
            ShortcutAction::Save => self.save_project(),
            ShortcutAction::Open => self.open_project(),
            ShortcutAction::NewProject => self.new_project(),
            ShortcutAction::Undo => self.undo(),
            ShortcutAction::Redo => self.redo(),
            ShortcutAction::Duplicate => self.duplicate_selection(),
            ShortcutAction::Delete => self.delete_selection(),
            ShortcutAction::ToggleSettings => self.show_settings = !self.show_settings,
            ShortcutAction::View(view) => self.view = view,
            ShortcutAction::Tool(tool) => {
                if self.view == StudioView::Playlist {
                    self.tool_mode = tool;
                }
            }
            ShortcutAction::PianoTool(tool) => {
                if self.view == StudioView::PianoRoll {
                    self.piano_roll_state.tool = tool;
                } else if self.view == StudioView::Playlist {
                    self.tool_mode = match tool {
                        PianoRollTool::Draw => ToolMode::Draw,
                        PianoRollTool::Paint => ToolMode::Paint,
                        PianoRollTool::Delete => ToolMode::Delete,
                        PianoRollTool::Mute => ToolMode::Mute,
                        PianoRollTool::Slice => ToolMode::Slice,
                        PianoRollTool::Select => ToolMode::Select,
                        PianoRollTool::Stamp => return,
                    };
                }
            }
            ShortcutAction::PianoTransform(kind) => {
                if self.view == StudioView::PianoRoll {
                    self.begin_piano_roll_transform(kind);
                }
            }
            ShortcutAction::QuickLegato => {
                if self.view == StudioView::PianoRoll {
                    self.quick_legato_piano_roll();
                }
            }
            ShortcutAction::GroupPianoNotes => {
                if self.view == StudioView::PianoRoll {
                    self.group_piano_roll_selection();
                } else if self.view == StudioView::Playlist {
                    self.group_playlist_selection();
                }
            }
            ShortcutAction::UngroupPianoNotes => {
                if self.view == StudioView::PianoRoll {
                    self.ungroup_piano_roll_selection();
                } else if self.view == StudioView::Playlist {
                    self.ungroup_playlist_selection();
                }
            }
            ShortcutAction::DismissModal(modal) => self.dismiss_shortcut_modal(modal),
            ShortcutAction::ConfirmModal(modal) => self.confirm_shortcut_modal(modal),
        }
    }

    fn dismiss_shortcut_modal(&mut self, modal: ShortcutModal) {
        match modal {
            ShortcutModal::ProjectLifecycle => self.cancel_project_lifecycle(),
            ShortcutModal::ProjectMedia => self.project_media.close(),
            ShortcutModal::PianoTransform => self.cancel_piano_roll_transform(),
            ShortcutModal::PluginManager => {
                self.show_plugins = false;
                self.plugin_picker_target = None;
            }
            ShortcutModal::Settings => self.show_settings = false,
            ShortcutModal::MidiImport => self.pending_midi_import = None,
            ShortcutModal::MidiExport => self.pending_midi_export = None,
            ShortcutModal::WavExport => {
                self.export_dialog.close();
                self.export_error = None;
            }
            // Recovery owns the startup surface until the user explicitly restores or discards.
            ShortcutModal::Recovery => {}
        }
    }

    fn confirm_shortcut_modal(&mut self, modal: ShortcutModal) {
        match modal {
            ShortcutModal::ProjectLifecycle => self.save_project_for_lifecycle(),
            ShortcutModal::PianoTransform => self.accept_piano_roll_transform(),
            ShortcutModal::Settings => self.show_settings = false,
            ShortcutModal::MidiImport => self.confirm_midi_import(),
            ShortcutModal::MidiExport => self.confirm_midi_export(),
            // WAV review requires the explicit destination button; Enter must
            // never skip review or reuse an overwrite choice.
            ShortcutModal::ProjectMedia
            | ShortcutModal::PluginManager
            | ShortcutModal::Recovery
            | ShortcutModal::WavExport => {}
        }
    }

    fn advance_fallback_transport(&self, delta_seconds: f32) -> (f32, f32, bool) {
        let song_length = self.transport_loop_end_beat();
        if let Some(map) = &self.tempo_map {
            let current_beat = f64::from(self.beat_position).clamp(0.0, map.max_beat());
            if let Ok(advance) =
                map.advance_looping(current_beat, f64::from(delta_seconds.max(0.0)))
            {
                return (
                    advance.beat as f32,
                    advance.traveled_beats.min(f64::from(f32::MAX)) as f32,
                    advance.completed_loops != 0,
                );
            }
        }

        let delta_beats = delta_seconds * self.effective_tempo / 60.0;
        let next_beat = self.beat_position + delta_beats;
        let looped = next_beat >= song_length;
        (next_beat % song_length, delta_beats, looped)
    }

    fn refresh_transport_clock(&mut self) {
        let now = Instant::now();
        let delta = (now - self.last_frame).as_secs_f32().min(0.1);
        self.frame_time_ms = self.frame_time_ms * 0.88 + delta * 1000.0 * 0.12;
        self.last_frame = now;
        let meter_graph = self
            .timeline_audio_source
            .as_ref()
            .filter(|source| source.generation == self.timeline_desired_generation)
            .map(|source| {
                (
                    source.generation,
                    source.timeline.mixer_graph().fingerprint(),
                )
            });
        self.mixer_meters = self
            .audio
            .as_mut()
            .map_or_else(crate::audio_meter::MeterReadings::default, |audio| {
                audio.poll_meters(now, meter_graph)
            });
        self.refresh_tempo_map_device_rate();
        let song_length = self.transport_loop_end_beat();
        self.transport_delta_beats = 0.0;
        if self.transport_loop_dirty {
            self.publish_current_transport_loop();
        }

        if let Some(audio) = &self.audio {
            let snapshot = audio.snapshot();
            let previous_beat = self.beat_position;
            let current_beat = transport_beat_for_frame(
                self.tempo_map.as_ref(),
                snapshot.timeline_frame,
                snapshot.beat_position,
            ) as f32;
            let loop_delta = snapshot
                .transport_loop_count
                .wrapping_sub(self.last_audio_loop_count);
            let epoch_changed = snapshot.transport_epoch != self.last_audio_transport_epoch;

            self.transport_clock_playing = snapshot.transport_playing;
            self.transport_delta_beats = if snapshot.transport_playing {
                if loop_delta != 0 {
                    (song_length - previous_beat).max(0.0)
                        + current_beat
                        + song_length * loop_delta.saturating_sub(1) as f32
                } else if !epoch_changed && current_beat >= previous_beat {
                    current_beat - previous_beat
                } else {
                    0.0
                }
            } else {
                0.0
            };
            self.beat_position = current_beat.clamp(0.0, song_length);
            if epoch_changed {
                self.pending_generator_note_offs.clear();
                self.active_audio_clips.clear();
                self.last_step = usize::MAX;
            }
            self.last_audio_transport_epoch = snapshot.transport_epoch;
            self.last_audio_loop_count = snapshot.transport_loop_count;
            return;
        }

        self.transport_clock_playing = self.playing;
        if self.playing {
            let (next_beat, delta_beats, looped) = self.advance_fallback_transport(delta);
            self.beat_position = next_beat;
            self.transport_delta_beats = delta_beats;
            if looped {
                self.stop_all_plugin_notes();
                self.active_audio_clips.clear();
                self.pending_generator_note_offs.clear();
                self.last_step = usize::MAX;
            }
        }
    }

    fn update_transport(&mut self, ctx: &egui::Context) {
        if note_clip_scheduler(self.callback_timeline_owns_note_clip())
            == NoteClipScheduler::CallbackTimeline
        {
            // The callback owns note and audio-clip scheduling only after its
            // revision+epoch activation is fully confirmed. Legacy state is
            // discarded here so it cannot leak note-offs/stops into the new
            // sample-accurate path. Native internal Channel Volume/Pan/Mute
            // are callback-owned; unsupported targets stay on the legacy
            // compatibility bridge.
            self.pending_generator_note_offs.clear();
            self.active_audio_clips.clear();
            self.last_step = usize::MAX;
            if self.transport_clock_playing {
                ctx.request_repaint_after(Duration::from_millis(8));
            }
            return;
        }
        self.advance_generator_note_offs();
        if !self.transport_clock_playing {
            return;
        }

        let song_length = self.transport_loop_end_beat();
        if self.last_step != usize::MAX
            && swung_step_index(self.beat_position, self.effective_swing) < self.last_step
        {
            self.last_step = usize::MAX;
        }
        if self.view == StudioView::Playlist {
            let beat = f64::from(self.beat_position.clamp(0.0, song_length));
            let (view_start, view_end) = self.playlist_viewport.x.visible_range();
            if beat < view_start || beat >= view_end {
                let _ = self.playlist_viewport.x.reveal(beat, beat, 0.0);
            }
        }
        let transport_step = swung_step_index(self.beat_position, self.effective_swing);
        let first_step = if self.last_step == usize::MAX || transport_step < self.last_step {
            transport_step
        } else {
            self.last_step.saturating_add(1)
        };
        let pattern_slices = transport_pattern_slices(&self.project, self.transport_mode);
        for scheduled_step in first_step..=transport_step {
            let scheduled_beat = swung_step_beat(scheduled_step, self.effective_swing);
            let mut scheduled_channel_notes = Vec::new();
            let mut scheduled_steps = HashSet::new();
            let mut scheduled_notes = HashSet::new();
            let note_map = [36_u8, 39, 54, 43, 64];
            let any_channel_solo = self.project.channels.iter().any(|channel| channel.solo);

            for slice in pattern_slices.iter().filter(|slice| {
                scheduled_beat >= slice.start && scheduled_beat < slice.start + slice.length
            }) {
                let Some(pattern) = self
                    .project
                    .patterns
                    .iter()
                    .find(|pattern| pattern.id == slice.pattern_id)
                else {
                    continue;
                };
                let relative_beat = (scheduled_beat - slice.start).max(0.0);
                let pattern_step = swung_step_index(relative_beat, self.effective_swing)
                    % pattern.length_steps.max(1);
                if scheduled_steps.insert((pattern.id, pattern_step)) {
                    for (index, channel) in self.project.channels.iter().enumerate() {
                        let enabled = pattern
                            .channel_steps
                            .get(index)
                            .is_some_and(|steps| steps[pattern_step % 16]);
                        let muted = self
                            .runtime_channel_mutes
                            .get(index)
                            .copied()
                            .unwrap_or(channel.muted)
                            || (any_channel_solo && !channel.solo);
                        if enabled && !muted {
                            scheduled_channel_notes.push((
                                channel.id,
                                note_map.get(index).copied().unwrap_or(60),
                                self.runtime_channel_volumes
                                    .get(index)
                                    .copied()
                                    .unwrap_or(channel.volume),
                                0.25,
                                channel.mixer_track,
                            ));
                        }
                    }
                }

                let piano_period = if self.transport_mode == TransportMode::Pattern {
                    slice.length.max(0.25)
                } else {
                    LOOP_LENGTH
                };
                let piano_step =
                    swung_step_index(relative_beat % piano_period, self.effective_swing);
                for note in pattern.notes.iter().filter(|note| {
                    !note.muted && swung_step_index(note.start, self.effective_swing) == piano_step
                }) {
                    let Some(channel_id) = note.channel_id else {
                        continue;
                    };
                    let Some((channel_index, channel)) = self
                        .project
                        .channels
                        .iter()
                        .enumerate()
                        .find(|(_, channel)| channel.id == channel_id)
                    else {
                        continue;
                    };
                    let muted = self
                        .runtime_channel_mutes
                        .get(channel_index)
                        .copied()
                        .unwrap_or(channel.muted)
                        || (any_channel_solo && !channel.solo);
                    if !muted && scheduled_notes.insert((pattern.id, piano_step, note.id)) {
                        scheduled_channel_notes.push((
                            channel.id,
                            note.note,
                            note.velocity
                                * self
                                    .runtime_channel_volumes
                                    .get(channel_index)
                                    .copied()
                                    .unwrap_or(channel.volume),
                            note.length,
                            channel.mixer_track,
                        ));
                    }
                }
            }
            for (channel_id, note, velocity, length_beats, mixer_track) in scheduled_channel_notes {
                let Some(mixer_track) = self.project.mixer_runtime_slot(mixer_track) else {
                    continue;
                };
                self.trigger_channel_note(
                    channel_id,
                    note,
                    velocity,
                    scheduled_beat,
                    length_beats,
                    mixer_track,
                );
            }
        }
        self.last_step = transport_step;
        self.sync_audio_clips();
        ctx.request_repaint_after(Duration::from_millis(8));
    }

    fn sync_audio_clips(&mut self) {
        let mut desired = HashSet::new();
        let mut clip_states = Vec::new();
        if self.transport_mode == TransportMode::Song {
            for clip in &self.project.clips {
                let Some(asset_id) = clip.audio_asset_id else {
                    continue;
                };
                let Some(runtime_asset_id) = self.loaded_audio_assets.get(&asset_id).copied()
                else {
                    continue;
                };
                let Some(asset) = self
                    .project
                    .audio_assets
                    .iter()
                    .find(|asset| asset.id == asset_id)
                else {
                    continue;
                };
                let Some((source_frame, gain, mixer_track)) = audio_clip_playback_state(
                    clip,
                    asset,
                    self.beat_position,
                    self.tempo_map.as_ref(),
                    self.effective_tempo,
                ) else {
                    continue;
                };
                desired.insert(clip.id);
                clip_states.push((clip.id, runtime_asset_id, source_frame, gain, mixer_track));
            }
        }

        let previous = self.active_audio_clips.clone();
        let mut next_active = HashSet::new();
        let generation = self.audio_asset_generation;
        if let Some(audio) = &mut self.audio {
            for clip_id in previous.difference(&desired).copied() {
                let runtime_clip_id = runtime_audio_clip_id(generation, clip_id);
                if !audio.stop_clip(runtime_clip_id) {
                    next_active.insert(clip_id);
                }
            }
            for (clip_id, asset_id, source_frame, gain, mixer_track) in clip_states {
                let runtime_clip_id = runtime_audio_clip_id(generation, clip_id);
                let queued = if previous.contains(&clip_id) {
                    audio.sync_clip(runtime_clip_id, asset_id, source_frame, gain, mixer_track)
                } else {
                    audio.play_clip(runtime_clip_id, asset_id, source_frame, gain, mixer_track)
                };
                if queued || previous.contains(&clip_id) {
                    next_active.insert(clip_id);
                }
            }
        }
        self.active_audio_clips = next_active;
    }

    fn update_project_state(&mut self) {
        // A Piano Roll transform mutates a private preview candidate in `self.project`.
        // Never dirty-check or autosave that candidate before Accept commits it.
        if self.piano_roll_transform.is_some() {
            return;
        }
        if self.last_dirty_check.elapsed() >= Duration::from_millis(750) {
            if self.history_fingerprint != self.project_fingerprint {
                self.dirty = true;
            }
            self.last_dirty_check = Instant::now();
        }
        if self.dirty && self.last_autosave.elapsed() >= AUTOSAVE_INTERVAL {
            self.autosave();
        }
    }

    fn timeline_sample_rate(&self) -> u32 {
        self.audio
            .as_ref()
            .map(|audio| audio.snapshot().sample_rate)
            .filter(|sample_rate| *sample_rate != 0)
            .unwrap_or(self.tempo_map_sample_rate.max(1))
    }

    fn refresh_timeline_fingerprint(&mut self, now: Instant, force: bool) {
        if !force
            && now.saturating_duration_since(self.timeline_last_fingerprint_check)
                < TIMELINE_FINGERPRINT_INTERVAL
        {
            return;
        }
        self.timeline_last_fingerprint_check = now;
        let fingerprint = timeline_playback_fingerprint(
            &self.project,
            self.transport_mode,
            self.timeline_sample_rate(),
        );
        if fingerprint == self.timeline_observed_fingerprint {
            return;
        }
        self.timeline_observed_fingerprint = fingerprint;
        self.timeline_desired_generation = self.timeline_desired_generation.wrapping_add(1).max(1);
        self.timeline_compile_deadline = now + TIMELINE_COMPILE_DEBOUNCE;
        self.timeline_deferred_job = None;
        self.invalidate_pending_timeline_audio_generation();
        if self.timeline_worker_available {
            self.timeline_compile_error = None;
        }
    }

    fn invalidate_pending_timeline_audio_generation(&mut self) {
        self.timeline_pending_chase = None;
        self.timeline_pending_loop_chase = None;
        self.timeline_audio_sync.loop_token = None;
        self.timeline_audio_sync.loop_disable_request = None;
        let active = self.audio.as_ref().and_then(|audio| {
            let (revision, epoch) = audio.confirmed_timeline_identity()?;
            (audio.timeline_runtime_is_synchronized()
                && !audio.timeline_runtime_needs_resync()
                && self
                    .timeline_audio_source
                    .as_ref()
                    .is_some_and(|source| source.generation == revision))
            .then_some((revision, epoch))
        });
        self.timeline_audio_sync.phase = active.map_or(
            TimelineAudioSyncPhase::Unavailable,
            |(generation, epoch)| TimelineAudioSyncPhase::Active { generation, epoch },
        );
        self.timeline_audio_sync.retain_callback_ownership = false;
    }

    fn poll_timeline_compile(&mut self, ctx: &egui::Context) {
        let now = Instant::now();
        self.refresh_timeline_fingerprint(now, false);

        let mut results = Vec::with_capacity(MAX_TIMELINE_RESULTS_PER_FRAME);
        let mut disconnected = false;
        for _ in 0..MAX_TIMELINE_RESULTS_PER_FRAME {
            match self.timeline_compile_receiver.try_recv() {
                Ok(result) => results.push(result),
                Err(mpsc::TryRecvError::Empty) => break,
                Err(mpsc::TryRecvError::Disconnected) => {
                    disconnected = true;
                    break;
                }
            }
        }
        if !results.is_empty() {
            self.refresh_timeline_fingerprint(now, true);
        }
        for worker_result in results {
            if self.timeline_pending_generation == Some(worker_result.generation) {
                self.timeline_pending_generation = None;
            }
            if !timeline_result_is_current(
                &worker_result,
                self.timeline_desired_generation,
                self.timeline_observed_fingerprint,
                self.timeline_sample_rate(),
            ) {
                continue;
            }
            self.timeline_compile_elapsed = Some(worker_result.elapsed);
            match worker_result.result {
                Ok(timeline) => {
                    self.timeline_compile_stats = Some(timeline.stats());
                    self.timeline_compile_diagnostics = timeline.diagnostics().to_vec();
                    self.timeline_compile_error = None;
                    self.timeline_compiled_generation = Some(worker_result.generation);
                    self.timeline_compiled_fingerprint = Some(worker_result.fingerprint);
                    self.compiled_timeline = Some(Arc::clone(&timeline));
                    self.accept_timeline_audio_source(
                        worker_result.generation,
                        worker_result.fingerprint,
                        worker_result.sample_rate,
                        timeline,
                    );
                }
                Err(error) => {
                    self.compiled_timeline = None;
                    self.timeline_compiled_generation = None;
                    self.timeline_compiled_fingerprint = None;
                    self.timeline_compile_stats = None;
                    self.timeline_compile_diagnostics.clear();
                    self.timeline_compile_error = Some(error);
                    if self.timeline_audio_source.is_none() {
                        self.transport_loop_dirty = true;
                    }
                }
            }
        }
        if disconnected && self.timeline_worker_available {
            self.timeline_worker_available = false;
            self.timeline_pending_generation = None;
            self.timeline_deferred_job = None;
            self.timeline_compile_error = Some("Timeline compiler worker stopped".into());
            if self.timeline_audio_source.is_none() {
                self.transport_loop_dirty = true;
            }
        }

        let needs_enqueue = self.timeline_worker_available
            && self.timeline_last_enqueued_generation != Some(self.timeline_desired_generation)
            && now >= self.timeline_compile_deadline;
        if needs_enqueue && self.timeline_deferred_job.is_none() {
            self.timeline_deferred_job = Some(TimelineCompileJob {
                generation: self.timeline_desired_generation,
                fingerprint: self.timeline_observed_fingerprint,
                sample_rate: self.timeline_sample_rate(),
                project: transport_playback_project(&self.project, self.transport_mode),
                options: transport_timeline_compile_options(&self.project, self.transport_mode),
            });
        }
        if let Some(job) = self.timeline_deferred_job.take() {
            let generation = job.generation;
            match self.timeline_compile_sender.try_send(job) {
                Ok(()) => {
                    self.timeline_last_enqueued_generation = Some(generation);
                    self.timeline_pending_generation = Some(generation);
                }
                Err(mpsc::TrySendError::Full(job)) => {
                    self.timeline_deferred_job = Some(job);
                }
                Err(mpsc::TrySendError::Disconnected(_)) => {
                    self.timeline_worker_available = false;
                    self.timeline_compile_error =
                        Some("Timeline compiler worker is unavailable".into());
                }
            }
        }

        let current = self.timeline_compiled_generation == Some(self.timeline_desired_generation)
            && self.timeline_compiled_fingerprint == Some(self.timeline_observed_fingerprint);
        if self.timeline_worker_available
            && (!current
                || self.timeline_pending_generation.is_some()
                || self.timeline_deferred_job.is_some())
        {
            ctx.request_repaint_after(Duration::from_millis(16));
        }
    }

    fn accept_timeline_audio_source(
        &mut self,
        generation: u64,
        fingerprint: u64,
        sample_rate: u32,
        timeline: Arc<CompiledTimeline>,
    ) {
        let tempo_map = self
            .tempo_map
            .as_ref()
            .filter(|map| {
                map.sample_rate() == sample_rate
                    && map.duration_frames() == timeline.duration_frames()
            })
            .cloned()
            .or_else(|| {
                let transport_project =
                    transport_playback_project(&self.project, self.transport_mode);
                TempoMap::from_project(&transport_project, sample_rate).ok()
            });
        let Some(tempo_map) = tempo_map else {
            self.timeline_audio_source = None;
            self.timeline_pending_chase = None;
            self.timeline_pending_loop_chase = None;
            self.fault_timeline_audio("Compiled timeline has no matching tempo map".into());
            return;
        };
        if tempo_map.duration_frames() != timeline.duration_frames() {
            self.timeline_audio_source = None;
            self.timeline_pending_chase = None;
            self.timeline_pending_loop_chase = None;
            self.fault_timeline_audio(format!(
                "Timeline/tempo duration mismatch: {} != {} frames",
                timeline.duration_frames(),
                tempo_map.duration_frames()
            ));
            return;
        }
        self.tempo_map = Some(tempo_map.clone());
        self.tempo_map_error = None;
        self.tempo_map_fingerprint =
            transport_tempo_map_fingerprint(&self.project, self.transport_mode);
        self.tempo_map_sample_rate = sample_rate;

        let loop_start_beat = 0.0;
        let loop_start_frame = 0;
        let loop_end_beat = tempo_map.max_beat();
        let loop_end_frame = tempo_map.duration_frames();
        let seek_beat = f64::from(self.beat_position).clamp(0.0, loop_end_beat);
        let seek_frame = tempo_map.beat_to_frame(seek_beat).unwrap_or(0);
        let retain_callback_ownership = self.callback_timeline_owns_note_clip();
        self.timeline_pending_chase = None;
        self.timeline_pending_loop_chase = None;
        self.timeline_audio_source = Some(TimelineAudioSource {
            generation,
            fingerprint,
            sample_rate,
            timeline,
            tempo_map,
            loop_start_beat,
            loop_start_frame,
            loop_end_beat,
            loop_end_frame,
        });
        self.timeline_audio_sync
            .accept_source(generation, retain_callback_ownership);
        self.timeline_audio_sync.request_seek(seek_beat, seek_frame);
        self.transport_loop_dirty = false;
        if self.audio.is_none() {
            self.timeline_audio_sync.reset_audio_session(false);
        }
    }

    fn disable_timeline_loop_until_chased(&mut self) {
        let Some(source) = &self.timeline_audio_source else {
            return;
        };
        let Some(audio) = &self.audio else {
            return;
        };
        let request_id = audio.set_transport_loop_frames(
            source.loop_start_beat,
            source.loop_start_frame,
            source.loop_end_beat,
            source.loop_end_frame,
            false,
        );
        self.timeline_audio_sync.loop_disable_request = Some(request_id);
    }

    fn fault_timeline_audio(&mut self, message: String) {
        self.timeline_pending_chase = None;
        self.timeline_pending_loop_chase = None;
        if self.timeline_audio_sync.asset_handoff_silenced {
            self.timeline_audio_sync.asset_handoff_silenced = false;
            self.timeline_audio_sync.asset_handoff_frame = None;
            self.timeline_audio_sync.asset_handoff_assets_released = false;
            if let Some(audio) = &self.audio {
                audio.set_playing(
                    self.playing && self.audio_restart_state.allows_realtime_session_actions(),
                );
            }
        }
        let resident_revision = self
            .audio
            .as_ref()
            .and_then(AudioEngine::resident_timeline_revision);
        let callback_still_owns = self.audio.as_ref().is_some_and(|audio| {
            audio.confirmed_timeline_identity().is_some()
                && audio.timeline_runtime_is_synchronized()
                && !audio.timeline_runtime_needs_resync()
        });
        // Clear is a callback-confirmed ownership handoff. Until that
        // acknowledgement, a healthy old timeline remains the sole clip
        // scheduler; reopening legacy here would double-trigger it.
        begin_timeline_fault_handoff(
            &mut self.timeline_audio_sync,
            &mut self.transport_loop_dirty,
            resident_revision,
            callback_still_owns,
            message,
        );
    }

    fn callback_timeline_owns_note_clip(&self) -> bool {
        self.audio.as_ref().is_some_and(|audio| {
            let identity = audio.confirmed_timeline_identity();
            callback_note_clip_ownership(
                identity.map(|identity| identity.0),
                identity.map(|identity| identity.1),
                audio.timeline_runtime_needs_resync(),
                self.timeline_audio_sync.retain_callback_ownership
                    || self.timeline_audio_sync.asset_handoff_silenced
                    || matches!(
                        self.timeline_audio_sync.phase,
                        TimelineAudioSyncPhase::AwaitingActivation { .. }
                    ),
            )
        })
    }

    fn timeline_audio_matches_desired(&self) -> bool {
        let TimelineAudioSyncPhase::Active { generation, epoch } = self.timeline_audio_sync.phase
        else {
            return false;
        };
        let Some(source) = &self.timeline_audio_source else {
            return false;
        };
        let Some(audio) = &self.audio else {
            return false;
        };
        source.generation == generation
            && timeline_source_identity_is_current(
                source.generation,
                source.fingerprint,
                source.sample_rate,
                self.timeline_compiled_generation,
                self.timeline_compiled_fingerprint,
                self.timeline_observed_fingerprint,
                self.timeline_sample_rate(),
            )
            && audio.confirmed_timeline_identity() == Some((generation, epoch))
            && audio.timeline_runtime_is_synchronized()
            && !audio.timeline_runtime_needs_resync()
    }

    fn timeline_generator_routes_state(
        &self,
        timeline: &CompiledTimeline,
    ) -> RequiredGeneratorRouteState {
        let requirements = match timeline_generator_route_requirements(timeline) {
            Ok(requirements) => requirements,
            Err(error) => return RequiredGeneratorRouteState::Failed(error),
        };
        let mut confirmed = self
            .running_generator_chains
            .iter()
            .filter(|(_, chain)| {
                plugin_runtime_session_is_current(chain.project_session, self.project_session)
            })
            .map(|(&channel_id, chain)| ConfirmedGeneratorRoute {
                channel_id,
                endpoint_id: chain.endpoint_id,
                plugin_instance_id: chain.instance_id,
                mixer_track: chain.mixer_track,
            })
            .collect::<Vec<_>>();
        confirmed.sort_unstable_by_key(|route| route.channel_id);
        let pending_channels = self
            .pending_generator_chains
            .keys()
            .chain(self.pending_generator_removals.keys())
            .chain(self.pending_generator_routes.keys())
            .copied()
            .collect::<HashSet<_>>();
        required_generator_route_state(&requirements, &confirmed, &pending_channels)
    }

    fn ensure_timeline_generator_routes_ready(&mut self, timeline: &CompiledTimeline) -> bool {
        match self.timeline_generator_routes_state(timeline) {
            RequiredGeneratorRouteState::Ready => true,
            RequiredGeneratorRouteState::Pending {
                channel_id,
                plugin_instance_id,
            } => {
                self.timeline_audio_sync.last_error = Some(format!(
                    "Waiting for callback-confirmed generator channel {channel_id} instance {plugin_instance_id}"
                ));
                false
            }
            RequiredGeneratorRouteState::Failed(error) => {
                self.fault_timeline_audio(format!(
                    "Compiled generator route is not callback-ready: {error}"
                ));
                false
            }
        }
    }

    fn poll_timeline_audio_runtime(&mut self, ctx: &egui::Context) {
        let Some(audio) = self.audio.as_mut() else {
            if self.timeline_audio_sync.phase != TimelineAudioSyncPhase::Unavailable {
                self.timeline_pending_chase = None;
                self.timeline_pending_loop_chase = None;
                self.timeline_audio_sync.reset_audio_session(false);
            }
            return;
        };
        if !self.audio_restart_state.allows_runtime_dispatch() {
            audio.reclaim_retired_timeline_resources();
            for _ in 0..MAX_TIMELINE_RUNTIME_EVENTS_PER_FRAME {
                if audio.next_timeline_runtime_event().is_none() {
                    break;
                }
            }
            return;
        }
        if self.timeline_audio_sync.asset_handoff_silenced
            && !matches!(
                self.timeline_audio_sync.phase,
                TimelineAudioSyncPhase::AwaitingActivation { .. }
            )
            && audio.snapshot().transport_playing
        {
            // UI Play updates the desired intent during migration, but the
            // callback remains paused until the atomic timeline activation.
            audio.set_playing(false);
        }

        audio.reclaim_retired_timeline_resources();
        let mut events = Vec::with_capacity(MAX_TIMELINE_RUNTIME_EVENTS_PER_FRAME);
        for _ in 0..MAX_TIMELINE_RUNTIME_EVENTS_PER_FRAME {
            let Some(event) = audio.next_timeline_runtime_event() else {
                break;
            };
            events.push(event);
        }
        for event in events {
            self.handle_timeline_runtime_event(event);
        }

        self.observe_timeline_runtime_activation();
        self.recover_timeline_runtime_if_needed();
        self.drive_timeline_fault_clear();
        self.drive_timeline_audio_sync();

        if !matches!(
            self.timeline_audio_sync.phase,
            TimelineAudioSyncPhase::Active { .. }
                | TimelineAudioSyncPhase::Unavailable
                | TimelineAudioSyncPhase::Faulted
        ) {
            ctx.request_repaint_after(Duration::from_millis(8));
        }
    }

    fn handle_timeline_runtime_event(&mut self, event: TimelineRuntimeEvent) {
        match event {
            TimelineRuntimeEvent::Installed {
                request_id,
                revision,
            } => {
                self.timeline_audio_sync
                    .confirm_install(request_id, revision);
            }
            TimelineRuntimeEvent::LoopChaseInstalled {
                request_id,
                revision,
                frame,
                token,
            } => {
                self.timeline_audio_sync
                    .confirm_loop(request_id, revision, frame, token);
            }
            TimelineRuntimeEvent::ChaseInstalled {
                request_id,
                revision,
                epoch,
                frame,
            } => {
                let Some(seek_serial) = self
                    .timeline_audio_sync
                    .confirm_chase(request_id, revision, epoch, frame)
                else {
                    return;
                };
                self.timeline_audio_sync.phase = TimelineAudioSyncPhase::AwaitingActivation {
                    generation: revision,
                    seek_serial,
                    epoch,
                    frame,
                    activation_request_id: 0,
                };
                self.drive_timeline_transport_activation();
            }
            TimelineRuntimeEvent::TransportActivationApplied {
                request_id,
                revision,
                epoch,
                frame,
            } => {
                if self
                    .timeline_audio_sync
                    .confirm_activation_receipt(request_id, revision, epoch, frame)
                {
                    // The callback now owns native Channel automation. Force
                    // every still-legacy target to publish a fresh full value
                    // in this same UI tick while callback-owned native targets
                    // are filtered at the dispatch boundary.
                    self.automation_evaluator.reset();
                    if let Some(audio) = self.audio.as_mut() {
                        let _ = audio.acknowledge_timeline_resync(revision, epoch);
                    }
                    self.reconcile_timeline_audio_assets();
                } else {
                    self.timeline_audio_sync.confirmation_is_stale();
                }
            }
            TimelineRuntimeEvent::TransportActivationRejected {
                request_id,
                revision,
                reason,
            } => {
                self.timeline_audio_sync
                    .reject_activation_receipt(request_id, revision, reason);
            }
            TimelineRuntimeEvent::Rejected {
                request_id,
                revision,
                reason,
            } => self.handle_timeline_runtime_rejection(request_id, revision, reason),
            TimelineRuntimeEvent::Cleared {
                request_id,
                revision,
            } => {
                if matches!(
                    self.timeline_audio_sync.phase,
                    TimelineAudioSyncPhase::AssetHandoffClearQueued { .. }
                ) {
                    self.timeline_audio_sync
                        .confirm_asset_handoff_clear(request_id, revision);
                    return;
                }
                // Only the callback confirmation releases old scheduling
                // ownership. The next tick can now publish the exact legacy
                // loop without any overlap.
                if let Some(beat) = confirm_timeline_asset_clear(
                    &mut self.timeline_audio_sync,
                    &mut self.transport_loop_dirty,
                    request_id,
                    revision,
                ) {
                    // Callback ownership is gone. Reset the delta baseline so
                    // every legacy compatibility target, including a Channel
                    // pan whose numeric value did not change, is restored on
                    // the next apply_automation pass.
                    self.automation_evaluator.reset();
                    // Seek/Stop intents that arrived while Clear was queued
                    // are replayed only after callback ownership is gone.
                    if let Some(audio) = &self.audio {
                        publish_audio_transport_seek(audio, self.tempo_map.as_ref(), beat);
                    }
                }
            }
            TimelineRuntimeEvent::ShutdownComplete { .. } => {
                self.timeline_audio_sync.confirmation_is_stale();
            }
        }
    }

    fn drive_timeline_fault_clear(&mut self) {
        let (revision, asset_handoff) = match self.timeline_audio_sync.phase {
            TimelineAudioSyncPhase::FaultClearReady { revision } => (revision, false),
            TimelineAudioSyncPhase::AssetHandoffClearReady { revision } => (revision, true),
            _ => return,
        };
        let Some(audio) = self.audio.as_mut() else {
            if asset_handoff {
                self.timeline_audio_sync.retain_callback_ownership = false;
                self.timeline_audio_sync.phase = TimelineAudioSyncPhase::InstallReady;
            } else {
                self.timeline_audio_sync.finish_fault_clear();
            }
            self.transport_loop_dirty = true;
            return;
        };
        if asset_handoff && audio.snapshot().transport_playing {
            // set_playing(false) is mailbox-based. Do not release A or any of
            // its resident assets until the callback has observed the pause.
            audio.set_playing(false);
            return;
        }
        if audio.resident_timeline_revision() != Some(revision) {
            if asset_handoff {
                self.timeline_audio_sync.retain_callback_ownership = false;
                self.timeline_audio_sync.phase = TimelineAudioSyncPhase::InstallReady;
            } else {
                self.timeline_audio_sync.finish_fault_clear();
                self.transport_loop_dirty = true;
                self.automation_evaluator.reset();
            }
            return;
        }
        match audio.clear_compiled_timeline(revision) {
            Ok(request_id) => {
                if asset_handoff {
                    self.timeline_audio_sync
                        .queue_asset_handoff_clear(revision, request_id);
                } else {
                    self.timeline_audio_sync
                        .queue_fault_clear(revision, request_id);
                }
            }
            Err(TimelineControlError::CommandQueueFull) => {
                self.timeline_audio_sync.queue_full();
            }
            Err(error) => {
                self.timeline_audio_sync.retry_count =
                    self.timeline_audio_sync.retry_count.saturating_add(1);
                self.timeline_audio_sync.last_error = Some(format!(
                    "Unable to release faulted callback timeline ({error}); retrying"
                ));
            }
        }
    }

    fn handle_timeline_runtime_rejection(
        &mut self,
        request_id: u64,
        revision: u64,
        reason: TimelineRejectReason,
    ) {
        let retry_phase = match self.timeline_audio_sync.phase {
            TimelineAudioSyncPhase::InstallQueued {
                request_id: expected,
                generation,
            } if expected == request_id && generation == revision => {
                Some(TimelineAudioSyncPhase::InstallReady)
            }
            TimelineAudioSyncPhase::LoopQueued {
                request_id: expected,
                generation,
                ..
            } if expected == request_id && generation == revision => {
                Some(TimelineAudioSyncPhase::LoopReady)
            }
            TimelineAudioSyncPhase::SeekQueued {
                request_id: expected,
                generation,
                ..
            } if expected == request_id && generation == revision => {
                Some(TimelineAudioSyncPhase::SeekReady)
            }
            TimelineAudioSyncPhase::FaultClearQueued {
                request_id: expected,
                revision: expected_revision,
            } if expected == request_id && expected_revision == revision => {
                Some(TimelineAudioSyncPhase::FaultClearReady { revision })
            }
            TimelineAudioSyncPhase::AssetHandoffClearQueued {
                request_id: expected,
                revision: expected_revision,
            } if expected == request_id && expected_revision == revision => {
                Some(TimelineAudioSyncPhase::AssetHandoffClearReady { revision })
            }
            _ => None,
        };
        if let Some(phase) = retry_phase {
            self.timeline_audio_sync.phase = phase;
            self.timeline_audio_sync.retry_count =
                self.timeline_audio_sync.retry_count.saturating_add(1);
            self.timeline_audio_sync.last_error =
                Some(format!("Timeline request rejected ({reason:?}); retrying"));
        } else {
            self.timeline_audio_sync.confirmation_is_stale();
        }
    }

    fn observe_timeline_runtime_activation(&mut self) {
        let Some(audio) = self.audio.as_mut() else {
            return;
        };
        let confirmed_identity = audio.confirmed_timeline_identity();
        if let Some((revision, epoch)) = confirmed_identity {
            // A replacement chase is resident before its transport one-shot
            // promotes the candidate. Local rejection state can only be
            // acknowledged after the callback publishes that exact active pair.
            let _ = audio.acknowledge_timeline_resync(revision, epoch);
        }
        let active = confirmed_identity.is_some()
            && audio.timeline_runtime_is_synchronized()
            && !audio.timeline_runtime_needs_resync();
        if !active {
            return;
        }
        let (revision, epoch) = confirmed_identity.expect("active runtime has an identity");
        // Loop wraps advance the epoch entirely inside the callback. The
        // reusable template remains resident; the UI only observes it.
        if self
            .timeline_audio_sync
            .observe_active_epoch(revision, epoch)
        {
            self.reconcile_timeline_audio_assets();
        }
    }

    fn recover_timeline_runtime_if_needed(&mut self) {
        let Some(audio) = &self.audio else {
            return;
        };
        if !audio.timeline_runtime_needs_resync()
            || !matches!(
                self.timeline_audio_sync.phase,
                TimelineAudioSyncPhase::Active { .. }
            )
        {
            return;
        }
        let snapshot = audio.snapshot();
        let Some(source) = &self.timeline_audio_source else {
            self.fault_timeline_audio(
                "Timeline runtime needs resync but its source is unavailable".into(),
            );
            return;
        };
        let frame = snapshot
            .timeline_frame
            .min(source.timeline.duration_frames());
        let beat = source
            .tempo_map
            .frame_to_beat(frame)
            .unwrap_or(snapshot.beat_position);
        self.timeline_audio_sync.request_seek(beat, frame);
    }

    fn ensure_timeline_audio_assets_ready(&mut self, timeline: &CompiledTimeline) -> bool {
        let required = timeline_required_audio_asset_ids(timeline);
        if required.len() > audio::MAX_REGISTERED_AUDIO_ASSETS {
            self.fault_timeline_audio(format!(
                "Timeline requires {} audio assets, but the callback table supports {}",
                required.len(),
                audio::MAX_REGISTERED_AUDIO_ASSETS
            ));
            return false;
        }
        if matches!(
            self.timeline_audio_sync.phase,
            TimelineAudioSyncPhase::AssetHandoffClearReady { .. }
                | TimelineAudioSyncPhase::AssetHandoffClearQueued { .. }
        ) {
            return false;
        }

        // Decode and validate every addition before pausing or releasing the
        // healthy active revision. A failure here is non-destructive: A keeps
        // rendering and the normal fault handoff remains callback-confirmed.
        if let Err(error) = self.queue_timeline_audio_assets(timeline) {
            self.fault_timeline_audio(error);
            return false;
        }
        let requires_handoff = match timeline_audio_asset_preflight(
            &required,
            &self.loaded_audio_assets,
            &self.pending_audio_asset_unregistrations,
            &self.prepared_audio_asset_registrations,
            &self.pending_audio_asset_registrations,
            &self.failed_audio_assets,
            self.audio_asset_generation,
            self.pending_audio_asset_clear.is_none(),
        ) {
            TimelineAudioAssetPreflight::Ready { requires_handoff } => requires_handoff,
            TimelineAudioAssetPreflight::Loading(asset_id) => {
                self.timeline_audio_sync.last_error =
                    Some(format!("Decoding audio asset {asset_id} before handoff"));
                return false;
            }
            TimelineAudioAssetPreflight::Failed(asset_id) => {
                let detail = self
                    .failed_audio_assets
                    .get(&asset_id)
                    .map(|failure| failure.message.as_str())
                    .unwrap_or("audio asset decode failed");
                self.fault_timeline_audio(format!(
                    "Timeline audio asset {asset_id} is unavailable; legacy fallback active: {detail}"
                ));
                return false;
            }
        };
        if self.pending_audio_asset_clear.is_some() {
            self.timeline_audio_sync.last_error =
                Some("Waiting for the callback audio asset session barrier".into());
            return false;
        }

        if self.timeline_audio_sync.asset_handoff_silenced
            && self
                .audio
                .as_ref()
                .and_then(AudioEngine::resident_timeline_revision)
                .is_none()
        {
            let released = self.release_obsolete_timeline_audio_assets(&required);
            self.timeline_audio_sync.asset_handoff_assets_released = released;
            if !released {
                self.timeline_audio_sync.last_error = Some(
                    "Waiting for every obsolete callback audio asset to acknowledge removal".into(),
                );
                return false;
            }
        }

        if requires_handoff {
            if let Some(revision) = self
                .audio
                .as_ref()
                .and_then(AudioEngine::resident_timeline_revision)
            {
                let callback_still_owns = self.callback_timeline_owns_note_clip();
                let frame = self
                    .audio
                    .as_ref()
                    .map(|audio| audio.snapshot().timeline_frame)
                    .unwrap_or(0);
                if let Some(audio) = &self.audio {
                    audio.set_playing(false);
                }
                self.timeline_audio_sync
                    .begin_asset_handoff(revision, callback_still_owns, frame);
                return false;
            }

            // With no callback timeline resident, legacy scheduling remains
            // suppressed and the device stays paused until every obsolete
            // callback asset has acknowledged removal.
            if !self.timeline_audio_sync.asset_handoff_silenced {
                self.timeline_audio_sync.asset_handoff_silenced = true;
                self.timeline_audio_sync.asset_handoff_assets_released = false;
                self.timeline_audio_sync.asset_handoff_frame = self
                    .audio
                    .as_ref()
                    .map(|audio| audio.snapshot().timeline_frame);
                if let Some(audio) = &self.audio {
                    audio.set_playing(false);
                }
            }
            let _ = self.release_obsolete_timeline_audio_assets(&required);
            self.timeline_audio_sync.last_error =
                Some("Waiting for callback-confirmed removal of obsolete audio assets".into());
            return false;
        }

        self.drive_prepared_audio_asset_registrations();
        match required_audio_asset_state(
            required,
            &self.loaded_audio_assets,
            &self.pending_audio_asset_unregistrations,
            &self.failed_audio_assets,
            self.audio_asset_generation,
            self.pending_audio_asset_clear.is_some(),
        ) {
            RequiredAudioAssetState::Ready => true,
            RequiredAudioAssetState::Loading(asset_id) => {
                self.timeline_audio_sync.last_error = Some(format!(
                    "Waiting for callback confirmation of audio asset {asset_id}"
                ));
                false
            }
            RequiredAudioAssetState::Failed(asset_id) => {
                let detail = self
                    .failed_audio_assets
                    .get(&asset_id)
                    .map(|failure| failure.message.as_str())
                    .unwrap_or("audio asset registration failed");
                self.fault_timeline_audio(format!(
                    "Timeline audio asset {asset_id} is unavailable; legacy fallback active: {detail}"
                ));
                false
            }
        }
    }

    fn drive_timeline_audio_sync(&mut self) {
        let Some((timeline, generation)) = self
            .timeline_audio_source
            .as_ref()
            .map(|source| (Arc::clone(&source.timeline), source.generation))
        else {
            return;
        };
        if matches!(
            self.timeline_audio_sync.phase,
            TimelineAudioSyncPhase::InstallReady
                | TimelineAudioSyncPhase::LoopReady
                | TimelineAudioSyncPhase::SeekReady
        ) && !self.ensure_timeline_generator_routes_ready(&timeline)
        {
            return;
        }
        if self.audio.is_none() {
            return;
        }
        if self.timeline_audio_sync.phase == TimelineAudioSyncPhase::InstallReady
            && !self.ensure_timeline_audio_assets_ready(&timeline)
        {
            return;
        }
        match self.timeline_audio_sync.phase {
            TimelineAudioSyncPhase::InstallReady => {
                let timeline = Arc::clone(&timeline);
                let result = self
                    .audio
                    .as_mut()
                    .expect("audio checked above")
                    .install_compiled_timeline(generation, timeline);
                match result {
                    Ok(request_id) => {
                        self.timeline_audio_sync.phase = TimelineAudioSyncPhase::InstallQueued {
                            request_id,
                            generation,
                        };
                        self.timeline_audio_sync.last_error = None;
                    }
                    Err(error)
                        if error.reason == TimelineResourceQueueFailure::CommandQueueFull =>
                    {
                        drop(error.resource);
                        self.timeline_audio_sync.queue_full();
                    }
                    Err(error) => {
                        let reason = error.reason;
                        drop(error.resource);
                        self.fault_timeline_audio(format!("Timeline install failed: {reason:?}"));
                    }
                }
            }
            TimelineAudioSyncPhase::LoopReady => self.drive_timeline_loop_chase(),
            TimelineAudioSyncPhase::SeekReady => self.drive_timeline_seek_chase(),
            TimelineAudioSyncPhase::AwaitingActivation {
                activation_request_id: 0,
                ..
            } => self.drive_timeline_transport_activation(),
            _ => {}
        }
    }

    fn drive_timeline_transport_activation(&mut self) {
        let TimelineAudioSyncPhase::AwaitingActivation {
            generation,
            seek_serial,
            epoch: minimum_epoch,
            frame,
            activation_request_id: 0,
        } = self.timeline_audio_sync.phase
        else {
            return;
        };
        let Some(source) = self.timeline_audio_source.as_ref() else {
            self.fault_timeline_audio(
                "Seek chase was confirmed after its compiled source was released".into(),
            );
            return;
        };
        if source.generation != generation {
            self.timeline_audio_sync.confirmation_is_stale();
            return;
        }
        let Some(loop_token) = self.timeline_audio_sync.loop_token else {
            self.timeline_audio_sync.last_error =
                Some("Waiting for the exact loop chase token before activation".into());
            return;
        };
        let newer_seek_waiting = self.timeline_audio_sync.desired_seek.serial != seek_serial;
        let beat = source
            .tempo_map
            .frame_to_beat(frame)
            .unwrap_or(self.timeline_audio_sync.desired_seek.beat);
        let mixer_pan_release =
            native_channel_pan_release(&self.project, &source.timeline, beat as f32);
        let spec = TimelineTransportActivationSpec {
            revision: generation,
            target_epoch: minimum_epoch,
            minimum_epoch,
            frame,
            beat_q32: audio::beat_to_q32(beat),
            loop_start_frame: source.loop_start_frame,
            loop_end_frame: source.loop_end_frame,
            loop_start_q32: audio::beat_to_q32(source.loop_start_beat),
            loop_end_q32: audio::beat_to_q32(source.loop_end_beat),
            loop_token,
            loop_enabled: !newer_seek_waiting,
            playing: self.playing
                && !newer_seek_waiting
                && self.audio_restart_state.allows_realtime_session_actions(),
            mixer_pan_release,
        };
        let Some(audio) = self.audio.as_mut() else {
            self.timeline_audio_sync.reset_audio_session(false);
            return;
        };
        match audio.activate_timeline_transport(spec) {
            Ok(request_id) => {
                let _ = self.timeline_audio_sync.queue_activation(
                    request_id,
                    generation,
                    seek_serial,
                    minimum_epoch,
                    frame,
                );
            }
            Err(TimelineControlError::CommandQueueFull) => {
                self.timeline_audio_sync.queue_full();
            }
            Err(error) => {
                self.timeline_audio_sync.phase = TimelineAudioSyncPhase::SeekReady;
                self.timeline_audio_sync.retry_count =
                    self.timeline_audio_sync.retry_count.saturating_add(1);
                self.timeline_audio_sync.last_error = Some(format!(
                    "Unable to queue atomic timeline activation ({error}); retrying"
                ));
            }
        }
    }

    fn drive_timeline_loop_chase(&mut self) {
        let Some(timeline) = self
            .timeline_audio_source
            .as_ref()
            .map(|source| Arc::clone(&source.timeline))
        else {
            return;
        };
        if !self.ensure_timeline_generator_routes_ready(&timeline) {
            return;
        }
        let source = self
            .timeline_audio_source
            .as_ref()
            .expect("timeline source was cloned above");
        if self.timeline_pending_loop_chase.is_none() {
            let result = self
                .audio
                .as_ref()
                .expect("loop chase requires audio")
                .prepare_timeline_loop_chase(
                    &source.timeline,
                    source.generation,
                    source.loop_start_frame,
                    TimelineChaseOptions::default(),
                );
            match result {
                Ok(chase) => self.timeline_pending_loop_chase = Some(chase),
                Err(error) => {
                    self.fault_timeline_audio(format!("Unable to prepare loop chase: {error}"));
                    return;
                }
            }
        }
        let chase = self
            .timeline_pending_loop_chase
            .take()
            .expect("loop chase was prepared above");
        match self
            .audio
            .as_mut()
            .expect("loop chase requires audio")
            .install_timeline_loop_chase(chase)
        {
            Ok(request_id) => {
                self.timeline_audio_sync.phase = TimelineAudioSyncPhase::LoopQueued {
                    request_id,
                    generation: source.generation,
                    frame: source.loop_start_frame,
                };
                self.timeline_audio_sync.last_error = None;
            }
            Err(error) if error.reason == TimelineResourceQueueFailure::CommandQueueFull => {
                self.timeline_pending_loop_chase = Some(error.resource);
                self.timeline_audio_sync.queue_full();
            }
            Err(error) => {
                let reason = error.reason;
                drop(error.resource);
                self.fault_timeline_audio(format!("Loop chase install failed: {reason:?}"));
            }
        }
    }

    fn drive_timeline_seek_chase(&mut self) {
        let Some(timeline) = self
            .timeline_audio_source
            .as_ref()
            .map(|source| Arc::clone(&source.timeline))
        else {
            return;
        };
        if !self.ensure_timeline_generator_routes_ready(&timeline) {
            return;
        }
        if !self.ensure_timeline_audio_assets_ready(&timeline) {
            return;
        }
        let source = self
            .timeline_audio_source
            .as_ref()
            .expect("timeline source was cloned above");
        let snapshot = self
            .audio
            .as_ref()
            .expect("seek chase requires audio")
            .snapshot();
        let intent = self.timeline_audio_sync.desired_seek;
        let frame = intent.frame.min(source.timeline.duration_frames());
        let epoch = next_nonzero_app_id(snapshot.transport_epoch);
        if self.timeline_pending_chase.is_none() {
            let result = self
                .audio
                .as_ref()
                .expect("seek chase requires audio")
                .prepare_timeline_chase(
                    &source.timeline,
                    source.generation,
                    epoch,
                    frame,
                    TimelineChaseOptions::default(),
                );
            match result {
                Ok(chase) => self.timeline_pending_chase = Some(chase),
                Err(error) => {
                    self.fault_timeline_audio(format!("Unable to prepare seek chase: {error}"));
                    return;
                }
            }
        }
        let chase = self
            .timeline_pending_chase
            .take()
            .expect("seek chase was prepared above");
        match self
            .audio
            .as_mut()
            .expect("seek chase requires audio")
            .install_timeline_chase(chase)
        {
            Ok(request_id) => {
                self.timeline_audio_sync.phase = TimelineAudioSyncPhase::SeekQueued {
                    request_id,
                    generation: source.generation,
                    seek_serial: intent.serial,
                    epoch,
                    frame,
                };
                self.timeline_audio_sync.last_error = None;
            }
            Err(error) if error.reason == TimelineResourceQueueFailure::CommandQueueFull => {
                self.timeline_pending_chase = Some(error.resource);
                self.timeline_audio_sync.queue_full();
            }
            Err(error) => {
                let reason = error.reason;
                drop(error.resource);
                self.fault_timeline_audio(format!("Seek chase install failed: {reason:?}"));
            }
        }
    }

    pub fn latest_compiled_timeline(&self) -> Option<(u64, Arc<CompiledTimeline>)> {
        let generation = self.timeline_compiled_generation?;
        if generation == self.timeline_desired_generation
            && self.timeline_compiled_fingerprint == Some(self.timeline_observed_fingerprint)
        {
            Some((generation, Arc::clone(self.compiled_timeline.as_ref()?)))
        } else {
            None
        }
    }

    /// Reserved for the later audio scheduler hand-off. No audio command is
    /// emitted by the current control-plane integration.
    #[allow(dead_code)]
    pub fn take_latest_compiled_timeline(&mut self) -> Option<(u64, Arc<CompiledTimeline>)> {
        let (generation, timeline) = self.latest_compiled_timeline()?;
        if generation <= self.timeline_taken_generation {
            return None;
        }
        self.timeline_taken_generation = generation;
        Some((generation, timeline))
    }

    fn project_is_dirty_now(&mut self) -> bool {
        let changed = project_fingerprint(&self.project) != self.project_fingerprint;
        if changed {
            self.dirty = true;
        }
        self.dirty
    }

    fn project_lifecycle_barriers_active(&self) -> bool {
        self.audio_restart_state.locks_session_actions()
            || self.save_barrier.is_some()
            || self.queued_save_request.is_some()
            || !self.midi_recording.is_idle()
            || self.input_recorder.is_some()
            || self.pending_recording.is_some()
            || self.master_capture.is_some()
            || self.pending_master_capture.is_some()
    }

    fn request_project_intent(&mut self, intent: ProjectIntent) {
        if self.audio_restart_state.locks_session_actions() {
            self.notify(
                "Finish or retry the audio device transaction before changing projects".into(),
            );
            return;
        }
        if self.deferred_project_intent_after_midi.is_some()
            || self.deferred_recovery_project_after_midi.is_some()
        {
            self.notify("A project transition is waiting for MIDI input teardown".into());
            return;
        }
        if !self.project_lifecycle.is_idle() {
            self.notify("Finish or cancel the current project transition first".into());
            return;
        }
        if self.recovery_available && !matches!(intent, ProjectIntent::Quit) {
            self.notify("Restore or discard the recovery point before changing projects".into());
            return;
        }
        let dirty = self.project_is_dirty_now();
        let barriers_active = self.project_lifecycle_barriers_active();
        if let Some(intent) = self
            .project_lifecycle
            .request(intent, dirty, barriers_active)
        {
            self.commit_project_intent(intent);
        }
    }

    fn drive_project_lifecycle(&mut self) {
        let stop_requested = matches!(
            self.project_lifecycle,
            ProjectLifecycle::WaitingForBarriers {
                stop_requested: true,
                ..
            }
        );
        if stop_requested {
            if !self.midi_recording.is_idle() {
                self.request_midi_recording_stop(MidiRecordAfterStop::StopAndResetZero);
            }
            if self.input_recorder.is_some() {
                self.finish_input_recording();
            }
            if self.master_capture.is_some() {
                self.request_realtime_master_capture_stop();
            }
        }
        if !matches!(
            self.project_lifecycle,
            ProjectLifecycle::WaitingForBarriers { .. }
        ) || self.project_lifecycle_barriers_active()
        {
            return;
        }
        let dirty = self.project_is_dirty_now();
        if let Some(intent) = self.project_lifecycle.barriers_cleared(dirty) {
            self.commit_project_intent(intent);
        }
    }

    fn report_project_lifecycle_critical_io_failure(&mut self, message: String) {
        if !self.project_lifecycle.fail_critical_io(message.clone()) {
            self.notify(message);
        }
    }

    fn stop_lifecycle_barriers_and_continue(&mut self) {
        if !matches!(
            self.project_lifecycle,
            ProjectLifecycle::WaitingForBarriers { .. }
        ) {
            return;
        }
        self.project_lifecycle.mark_stop_requested();
        if !self.midi_recording.is_idle() {
            self.request_midi_recording_stop(MidiRecordAfterStop::StopAndResetZero);
        }
        if self.input_recorder.is_some() {
            self.finish_input_recording();
        }
        if self.master_capture.is_some() {
            self.request_realtime_master_capture_stop();
        }
    }

    fn continue_after_lifecycle_io_failure(&mut self) {
        let dirty = self.project_is_dirty_now();
        if let Some(intent) = self
            .project_lifecycle
            .continue_after_critical_io_failure(dirty)
        {
            self.commit_project_intent(intent);
        }
    }

    fn save_project_for_lifecycle(&mut self) {
        if !matches!(
            self.project_lifecycle,
            ProjectLifecycle::AwaitingDecision { .. }
        ) {
            return;
        }
        let path = self.saved_path.clone().or_else(|| {
            rfd::FileDialog::new()
                .add_filter("Citrus project", &["citrus"])
                .set_file_name(format!("{}.citrus", self.project.name))
                .save_file()
        });
        let Some(path) = path else {
            return;
        };
        let operation_id = self.allocate_project_lifecycle_operation_id();
        if !self.project_lifecycle.begin_save(operation_id) {
            return;
        }
        self.begin_project_save(ProjectSaveRequest::Manual {
            path,
            lifecycle: Some(LifecycleSaveIdentity { operation_id }),
        });
    }

    fn discard_project_for_lifecycle(&mut self) {
        let was_dirty = self.project_is_dirty_now();
        let Some(intent) = self.project_lifecycle.discard() else {
            return;
        };
        let discards_for_quit = matches!(&intent, ProjectIntent::Quit);
        if was_dirty && discards_for_quit {
            if let Some(path) = &self.autosave_path {
                let _ = std::fs::remove_file(path);
            }
            self.recovery_available = false;
            self.suppress_drop_recovery = true;
        }
        self.commit_project_intent(intent);
    }

    fn cancel_project_lifecycle(&mut self) {
        if self.project_lifecycle.cancel() {
            self.notify("Project transition canceled".into());
        }
    }

    fn intercept_window_close_request(&mut self, ctx: &egui::Context) -> bool {
        let close_requested = ctx.input(|input| input.viewport().close_requested());
        if !close_requested || self.project_lifecycle.exit_is_armed() {
            return false;
        }
        ctx.send_viewport_cmd(egui::ViewportCommand::CancelClose);
        self.project_media.close();
        if self.piano_roll_transform.is_some() {
            // Preview candidates are never eligible for save, recovery, or quit handling.
            self.cancel_piano_roll_transform();
        }
        if self.project_lifecycle.is_idle() {
            self.request_project_intent(ProjectIntent::Quit);
        }
        true
    }

    fn dispatch_armed_window_close(&mut self, ctx: &egui::Context, canceled_this_frame: bool) {
        if canceled_this_frame && self.project_lifecycle.exit_is_armed() {
            ctx.request_repaint();
        } else if self.project_lifecycle.mark_close_command_sent() {
            ctx.send_viewport_cmd(egui::ViewportCommand::Close);
        }
    }

    fn project_lifecycle_dialog(&mut self, ctx: &egui::Context) {
        if !self.project_lifecycle.is_modal() {
            return;
        }

        let has_active_capture = !self.midi_recording.is_idle()
            || self.input_recorder.is_some()
            || self.master_capture.is_some();
        let transition_name = match self.project_lifecycle.intent_kind() {
            Some(ProjectIntentKind::New) => "NEW PROJECT",
            Some(ProjectIntentKind::Open) => "OPEN PROJECT",
            Some(ProjectIntentKind::Quit) => "QUIT",
            None => "PROJECT",
        };
        let mut action = None;
        let style = ctx.style_of(egui::Theme::Dark);
        let response = egui::Modal::new(Id::new("project-lifecycle-modal"))
            .backdrop_color(Color32::from_black_alpha(180))
            .frame(
                egui::Frame::window(style.as_ref())
                    .fill(theme::PANEL)
                    .stroke(Stroke::new(1.0, theme::ORANGE))
                    .corner_radius(9)
                    .inner_margin(egui::Margin::same(18)),
            )
            .show(ctx, |ui| {
                ui.set_width(460.0);
                match &self.project_lifecycle {
                    ProjectLifecycle::WaitingForBarriers {
                        intent,
                        stop_requested,
                    } => {
                        ui.heading(format!("{transition_name} - finish active work first"));
                        ui.label(format!(
                            "Citrus Studio must finish active recording, capture, or save work before it can {}.",
                            intent.verb()
                        ));
                        ui.add_space(8.0);
                        ui.horizontal(|ui| {
                            ui.spinner();
                            ui.label(if *stop_requested {
                                "Stopping and committing active media..."
                            } else {
                                "Waiting for a safe transition point..."
                            });
                        });
                        ui.add_space(14.0);
                        ui.horizontal(|ui| {
                            if ui
                                .add_enabled(
                                    has_active_capture,
                                    egui::Button::new("STOP & CONTINUE"),
                                )
                                .clicked()
                            {
                                action = Some(ProjectLifecycleDialogAction::StopAndContinue);
                            }
                            if ui.button("CANCEL").clicked() {
                                action = Some(ProjectLifecycleDialogAction::Cancel);
                            }
                        });
                    }
                    ProjectLifecycle::AwaitingDecision { intent, failure } => {
                        ui.heading(format!("{transition_name} - unsaved project changes"));
                        ui.label(format!(
                            "Save your current project before you {}?",
                            intent.verb()
                        ));
                        if let Some(failure) = failure {
                            ui.add_space(8.0);
                            ui.colored_label(theme::ORANGE, failure);
                        }
                        ui.add_space(14.0);
                        ui.horizontal(|ui| {
                            if ui.button("SAVE").clicked() {
                                action = Some(ProjectLifecycleDialogAction::Save);
                            }
                            if ui.button("DISCARD").clicked() {
                                action = Some(ProjectLifecycleDialogAction::Discard);
                            }
                            if ui.button("CANCEL").clicked() {
                                action = Some(ProjectLifecycleDialogAction::Cancel);
                            }
                        });
                    }
                    ProjectLifecycle::Saving { intent, .. } => {
                        ui.heading("Saving project");
                        ui.horizontal(|ui| {
                            ui.spinner();
                            ui.label(format!(
                                "Capturing plug-in state before Citrus Studio can {}...",
                                intent.verb()
                            ));
                        });
                    }
                    ProjectLifecycle::CriticalIoFailed { intent, message } => {
                        ui.heading("Media commit failed");
                        ui.label(format!(
                            "Citrus Studio could not durably finish active media before trying to {}.",
                            intent.verb()
                        ));
                        ui.add_space(8.0);
                        ui.colored_label(theme::ORANGE, message);
                        ui.add_space(8.0);
                        ui.label("Continue Anyway can discard the failed recording or capture result.");
                        ui.add_space(14.0);
                        ui.horizontal(|ui| {
                            if ui.button("CONTINUE ANYWAY").clicked() {
                                action = Some(ProjectLifecycleDialogAction::ContinueAnyway);
                            }
                            if ui.button("CANCEL").clicked() {
                                action = Some(ProjectLifecycleDialogAction::Cancel);
                            }
                        });
                    }
                    ProjectLifecycle::Idle | ProjectLifecycle::ExitArmed { .. } => {}
                }
            });

        if response.should_close()
            && matches!(
                self.project_lifecycle,
                ProjectLifecycle::WaitingForBarriers { .. }
                    | ProjectLifecycle::AwaitingDecision { .. }
                    | ProjectLifecycle::CriticalIoFailed { .. }
            )
        {
            action = Some(ProjectLifecycleDialogAction::Cancel);
        }
        match action {
            Some(ProjectLifecycleDialogAction::StopAndContinue) => {
                self.stop_lifecycle_barriers_and_continue();
            }
            Some(ProjectLifecycleDialogAction::Save) => self.save_project_for_lifecycle(),
            Some(ProjectLifecycleDialogAction::Discard) => self.discard_project_for_lifecycle(),
            Some(ProjectLifecycleDialogAction::ContinueAnyway) => {
                self.continue_after_lifecycle_io_failure();
            }
            Some(ProjectLifecycleDialogAction::Cancel) => self.cancel_project_lifecycle(),
            None => {}
        }
    }

    fn handle_project_save_completion(&mut self, completion: ProjectSaveCompletion) {
        let current_fingerprint = project_fingerprint(&self.project);
        if completion.fingerprint != current_fingerprint {
            self.dirty = true;
        }
        if let Some(intent) = self
            .project_lifecycle
            .complete_save(&completion, current_fingerprint)
        {
            self.commit_project_intent(intent);
        }
    }

    fn commit_project_intent(&mut self, intent: ProjectIntent) {
        if !self.midi_input.state.is_disconnected() {
            self.deferred_project_intent_after_midi = Some(intent);
            self.request_midi_input_disconnect(MidiInputDisconnectReason::ProjectChange);
            return;
        }
        match intent {
            ProjectIntent::New => {
                self.install_project(Project::blank(), None, false);
                self.project_lifecycle = ProjectLifecycle::Idle;
                self.notify("Created a new blank project".into());
            }
            ProjectIntent::Open { path } => {
                // The user may have saved the current dirty project to this exact path while
                // the Open intent was waiting. Reload at commit time so we never install stale
                // pre-dialog bytes over the file that was just saved.
                let project = match Project::load(&path) {
                    Ok(project) => project,
                    Err(error) => {
                        self.project_lifecycle = ProjectLifecycle::Idle;
                        self.notify(format!(
                            "Open was canceled because {} could not be reloaded: {error}",
                            path.display()
                        ));
                        return;
                    }
                };
                let diagnostic_count = project.migration_diagnostics.len();
                self.install_project(project, Some(path.clone()), false);
                self.project_lifecycle = ProjectLifecycle::Idle;
                if diagnostic_count == 0 {
                    self.notify(format!("Opened {}", path.display()));
                } else {
                    self.notify(format!(
                        "Opened {} with {diagnostic_count} v7 migration diagnostic(s); unresolved Piano routes and audio offsets are highlighted",
                        path.display()
                    ));
                }
            }
            ProjectIntent::Quit => self.project_lifecycle.arm_exit(),
        }
    }

    fn install_project(&mut self, project: Project, saved_path: Option<PathBuf>, dirty: bool) {
        debug_assert!(!self.project_lifecycle_barriers_active());
        debug_assert!(self.midi_input.state.is_disconnected());
        self.stop();
        self.stop_all_plugin_notes();
        self.clear_pending_midi_routing();
        self.export_job.cancel();
        self.export_error = None;
        self.export_dialog.close();
        self.plugin_parameter_edits.fail_all();
        self.plugin_parameter_edit_draft_desired.clear();
        self.project_media.close();
        self.project_session = next_project_session(self.project_session);
        self.cached_audio_assets.clear();
        self.pending_generator_routes.clear();
        self.generator_audibility.clear();
        self.show_plugins = false;
        self.plugin_parameter_editor = None;
        self.plugin_picker_target = None;
        self.show_settings = false;
        let selected_channel = initial_selected_channel_index(&project);
        self.project = project;
        self.saved_path = saved_path;
        self.view = StudioView::Playlist;
        self.selected_channel = selected_channel;
        self.selected_mixer = 0;
        self.clear_playlist_selection();
        self.playlist_gesture_before = None;
        self.playlist_viewport = default_playlist_viewport(self.project.song_length_beats);
        self.piano_viewport = default_piano_viewport();
        self.piano_roll_state.clear_selection();
        self.piano_roll_gesture_before = None;
        self.piano_roll_transform = None;
        self.runtime_channel_volumes = self
            .project
            .channels
            .iter()
            .map(|channel| channel.volume)
            .collect();
        self.runtime_channel_mutes = self
            .project
            .channels
            .iter()
            .map(|channel| channel.muted)
            .collect();
        self.master_volume = self
            .project
            .mixer_tracks
            .first()
            .map_or(0.72, |track| track.volume);
        self.undo_stack.clear();
        self.redo_stack.clear();
        self.automation_evaluator.reset();
        self.sync_history_observer();
        if dirty {
            self.project_fingerprint = project_fingerprint(&self.project);
            self.dirty = true;
            self.last_autosave = Instant::now();
            self.recovery_available = false;
        } else {
            self.mark_saved();
        }
        self.publish_current_transport_loop();
        self.sync_mixer_to_audio();
        self.rebuild_all_insert_chains();
        self.rebuild_all_generator_chains();
        self.queue_project_audio_assets();
        self.refresh_timeline_fingerprint(Instant::now(), true);
    }

    fn autosave(&mut self) {
        self.autosave_with_notice(false);
    }

    fn autosave_with_notice(&mut self, announce: bool) {
        self.last_autosave = Instant::now();
        if !self.project_lifecycle.is_idle() {
            if announce {
                self.notify("Recovery save is paused during a project transition".into());
            }
            return;
        }
        if self.save_barrier.is_some() {
            if announce {
                self.notify("Recovery save not started because another save is in progress".into());
            }
            return;
        }
        let Some(path) = self.autosave_path.clone() else {
            if announce {
                self.notify("Recovery path is unavailable".into());
            }
            return;
        };
        self.begin_project_save(ProjectSaveRequest::Autosave { path, announce });
    }

    fn begin_project_save(&mut self, request: ProjectSaveRequest) {
        if self.audio_restart_state.locks_session_actions() {
            if request.is_manual() {
                self.notify("Save is unavailable during an audio device transaction".into());
            }
            return;
        }
        if !self.midi_recording.is_idle() {
            if request.is_manual() {
                self.queued_save_after_midi_recording = Some(request);
                self.request_midi_recording_stop(MidiRecordAfterStop::ContinuePlayback);
                self.notify(
                    "Manual save is waiting for the exact MIDI recording stop and Project commit"
                        .into(),
                );
            } else if request.announce_success() {
                self.notify("Recovery save is paused while a MIDI take is active".into());
            }
            return;
        }
        let targets_recovery = request.is_manual()
            && self
                .autosave_path
                .as_ref()
                .is_some_and(|recovery| paths_refer_to_same_file(request.path(), recovery));
        if targets_recovery {
            let message = "Choose a project path other than Citrus Studio's reserved recovery file";
            self.notify(message.into());
            if let Some(identity) = request.lifecycle_identity() {
                self.handle_project_save_completion(ProjectSaveCompletion {
                    operation_id: identity.operation_id,
                    fingerprint: project_fingerprint(&self.project),
                    outcome: ProjectSaveOutcome::IoFailed(message.into()),
                });
            }
            return;
        }
        if self.save_barrier.is_some() {
            if request.is_manual() {
                self.queued_save_request = Some(request);
                self.notify("Manual save queued after the current plug-in state save".into());
            }
            return;
        }

        self.save_barrier = Some(PluginStateSaveBarrier {
            request,
            request_id: self.allocate_save_state_request_id(),
            requests_initialized: false,
            pending_requests: Vec::new(),
            waiting: HashSet::new(),
            stale: HashSet::new(),
            started_at: Instant::now(),
            parameter_edits_drained: false,
        });
    }

    fn plugin_topology_is_settling(&self) -> bool {
        !self.pending_insert_chains.is_empty()
            || !self.pending_insert_removals.is_empty()
            || !self.deferred_insert_rebuilds.is_empty()
            || !self.pending_generator_chains.is_empty()
            || !self.pending_generator_removals.is_empty()
            || !self.pending_generator_routes.is_empty()
            || !self.deferred_generator_rebuilds.is_empty()
    }

    fn plugin_runtime_is_ready_for_transport(&self) -> bool {
        plugin_runtime_transport_ready(
            self.project_session,
            self.plugin_topology_is_settling(),
            self.running_insert_chains
                .values()
                .map(|chain| chain.project_session)
                .chain(
                    self.running_generator_chains
                        .values()
                        .map(|chain| chain.project_session),
                ),
        )
    }

    fn current_plugin_state_probes(&self) -> Vec<PluginStateProbe> {
        let mut probes = Vec::new();
        let mut seen = HashSet::new();
        let mut insert_tracks = self
            .running_insert_chains
            .keys()
            .copied()
            .collect::<Vec<_>>();
        insert_tracks.sort_unstable();
        for track in insert_tracks {
            let Some(chain) = self.running_insert_chains.get(&track) else {
                continue;
            };
            if !plugin_runtime_session_is_current(chain.project_session, self.project_session) {
                continue;
            }
            for (slot, instance_id) in chain.instance_ids.iter().copied().enumerate() {
                let belongs_to_project = self
                    .project
                    .plugin_instances
                    .iter()
                    .any(|instance| instance.id == instance_id)
                    && self.project.mixer_insert_slots.iter().any(|slot_ref| {
                        self.project.mixer_runtime_slot(slot_ref.track) == Some(track)
                            && slot_ref.plugin_instance_id == instance_id
                    });
                if belongs_to_project && seen.insert(instance_id) {
                    probes.push(PluginStateProbe::Insert {
                        project_session: self.project_session,
                        track,
                        endpoint_id: chain.endpoint_id,
                        slot,
                        instance_id,
                    });
                }
            }
        }
        let mut generator_channels = self
            .running_generator_chains
            .keys()
            .copied()
            .collect::<Vec<_>>();
        generator_channels.sort_unstable();
        for channel_id in generator_channels {
            let Some(chain) = self.running_generator_chains.get(&channel_id) else {
                continue;
            };
            if !plugin_runtime_session_is_current(chain.project_session, self.project_session) {
                continue;
            }
            let belongs_to_project = self
                .project
                .plugin_instances
                .iter()
                .any(|instance| instance.id == chain.instance_id)
                && self.project.channels.iter().any(|channel| {
                    channel.id == channel_id
                        && channel.instrument_plugin_instance_id == Some(chain.instance_id)
                });
            if belongs_to_project && seen.insert(chain.instance_id) {
                probes.push(PluginStateProbe::Generator {
                    project_session: self.project_session,
                    channel_id,
                    endpoint_id: chain.endpoint_id,
                    instance_id: chain.instance_id,
                });
            }
        }
        probes
    }

    fn request_plugin_state_probe(&self, probe: PluginStateProbe, request_id: u64) -> Option<bool> {
        if !plugin_runtime_session_is_current(probe.project_session(), self.project_session) {
            return None;
        }
        match probe {
            PluginStateProbe::Insert {
                project_session,
                track,
                endpoint_id,
                slot,
                instance_id,
            } => self.running_insert_chains.get(&track).and_then(|chain| {
                (project_session == self.project_session
                    && chain.project_session == project_session
                    && chain.endpoint_id == endpoint_id
                    && chain.instance_ids.get(slot) == Some(&instance_id))
                .then(|| chain.control.request_state_tagged(slot, request_id))
            }),
            PluginStateProbe::Generator {
                project_session,
                channel_id,
                endpoint_id,
                instance_id,
            } => self
                .running_generator_chains
                .get(&channel_id)
                .and_then(|chain| {
                    (project_session == self.project_session
                        && chain.project_session == project_session
                        && chain.endpoint_id == endpoint_id
                        && chain.instance_id == instance_id)
                        .then(|| chain.control.request_state_tagged(0, request_id))
                }),
        }
    }

    fn poll_save_barrier(&mut self) {
        let Some(mut barrier) = self.save_barrier.take() else {
            return;
        };

        let now = Instant::now();
        if !barrier.parameter_edits_drained {
            match parameter_edit_save_barrier_status(
                self.plugin_parameter_edits.reserved_len(),
                now.saturating_duration_since(barrier.started_at),
            ) {
                ParameterEditSaveBarrierStatus::TimedOut => {
                    let failed = self.plugin_parameter_edits.fail_all().len();
                    self.plugin_parameter_edit_draft_desired.clear();
                    self.notify(format!(
                        "{failed} plug-in parameter edit(s) timed out; the project was not saved"
                    ));
                    self.abort_project_save(
                        barrier,
                        &format!(
                            "{failed} plug-in parameter edit(s) did not reach a terminal receipt"
                        ),
                    );
                    return;
                }
                ParameterEditSaveBarrierStatus::Waiting => {
                    self.save_barrier = Some(barrier);
                    return;
                }
                ParameterEditSaveBarrierStatus::Drained => {}
            }
            barrier.parameter_edits_drained = true;
            // Parameter edits, topology confirmation, and state capture each receive a full,
            // independent timeout budget. No state probe is sent before this transition.
            barrier.started_at = now;
        }
        if !barrier.requests_initialized {
            if self.plugin_topology_is_settling() {
                if barrier.timed_out(now) {
                    self.abort_project_save(
                        barrier,
                        "the plug-in graph did not reach a confirmed topology",
                    );
                } else {
                    self.save_barrier = Some(barrier);
                }
                return;
            }
            barrier.pending_requests = self.current_plugin_state_probes();
            barrier.requests_initialized = true;
            // Topology confirmation and state capture each receive the full timeout budget.
            barrier.started_at = now;
        }

        if !barrier.timed_out(now) && !barrier.pending_requests.is_empty() {
            let pending = std::mem::take(&mut barrier.pending_requests);
            for probe in pending {
                match self.request_plugin_state_probe(probe, barrier.request_id) {
                    Some(true) => {
                        barrier.waiting.insert(probe.instance_id());
                    }
                    Some(false) => barrier.pending_requests.push(probe),
                    None => {
                        barrier.stale.insert(probe.instance_id());
                    }
                }
            }
        }

        if barrier.timed_out(Instant::now()) {
            barrier.expire_unresolved();
        }
        if barrier.ready() {
            self.finish_project_save(barrier);
        } else {
            self.save_barrier = Some(barrier);
        }
    }

    fn abort_project_save(&mut self, barrier: PluginStateSaveBarrier, reason: &str) {
        let lifecycle = barrier.request.lifecycle_identity();
        if barrier.request.is_manual() {
            self.notify(format!("Save not completed: {reason}"));
        } else if barrier.request.announce_success() {
            self.notify(format!("Recovery point not written: {reason}"));
        }
        if let Some(identity) = lifecycle {
            self.handle_project_save_completion(ProjectSaveCompletion {
                operation_id: identity.operation_id,
                fingerprint: project_fingerprint(&self.project),
                outcome: ProjectSaveOutcome::TopologyTimeout(reason.into()),
            });
            self.queued_save_request = None;
        } else if let Some(request) = self.queued_save_request.take() {
            self.begin_project_save(request);
        }
    }

    fn finish_project_save(&mut self, barrier: PluginStateSaveBarrier) {
        let path = barrier.request.path().clone();
        let manual = barrier.request.is_manual();
        let announce = barrier.request.announce_success();
        let lifecycle = barrier.request.lifecycle_identity();
        let stale_count = barrier.stale.len();
        let saved_fingerprint = project_fingerprint(&self.project);
        let save_result = self.project.save(&path);
        let lifecycle_outcome = match &save_result {
            Ok(()) if stale_count == 0 => ProjectSaveOutcome::Clean,
            Ok(()) => ProjectSaveOutcome::StalePluginState { count: stale_count },
            Err(error) => ProjectSaveOutcome::IoFailed(error.to_string()),
        };
        match save_result {
            Ok(()) if manual => {
                self.saved_path = Some(path.clone());
                if stale_count == 0 {
                    self.mark_saved();
                    self.notify(format!(
                        "Saved {} · format v{} requires an updated Citrus Studio build",
                        path.display(),
                        crate::model::CURRENT_PROJECT_FORMAT_VERSION
                    ));
                } else {
                    self.dirty = true;
                    self.last_autosave = Instant::now();
                    self.notify(format!(
                        "Saved {} with {stale_count} stale plug-in state(s); the project remains marked unsaved",
                        path.display()
                    ));
                }
            }
            Ok(()) => {
                if stale_count > 0 {
                    self.notify(format!(
                        "Autosave completed with {stale_count} stale plug-in state(s)"
                    ));
                } else if announce {
                    self.notify("Recovery point written".into());
                }
            }
            Err(error) if manual => self.notify(format!("Save failed: {error}")),
            Err(error) => self.notify(format!("Autosave failed: {error}")),
        }
        if let Some(identity) = lifecycle {
            self.handle_project_save_completion(ProjectSaveCompletion {
                operation_id: identity.operation_id,
                fingerprint: saved_fingerprint,
                outcome: lifecycle_outcome,
            });
            self.queued_save_request = None;
        } else if let Some(request) = self.queued_save_request.take() {
            self.begin_project_save(request);
        }
    }

    fn mark_saved(&mut self) {
        self.project_fingerprint = project_fingerprint(&self.project);
        self.history_fingerprint = self.project_fingerprint;
        if transport_tempo_map_fingerprint(&self.project, self.transport_mode)
            != self.tempo_map_fingerprint
        {
            self.rebuild_tempo_map();
        }
        self.history_snapshot = self.project.clone();
        self.last_history_check = Instant::now();
        self.last_history_capture = Instant::now() - Duration::from_millis(500);
        self.dirty = false;
        self.last_autosave = Instant::now();
        self.recovery_available = false;
        if let Some(path) = &self.autosave_path {
            let saved_uses_recovery_path = self
                .saved_path
                .as_ref()
                .is_some_and(|saved| paths_refer_to_same_file(saved, path));
            if !saved_uses_recovery_path {
                let _ = std::fs::remove_file(path);
            }
        }
    }

