/// Maps the legacy UI-thread evaluator onto the audio commands used by the
/// mixer. The target is canonicalized here as a final boundary guard so callers
/// cannot accidentally address master volume/pan through track-zero commands.
fn legacy_mixer_automation_audio_command(
    project: &Project,
    target: &AutomationTarget,
    value: f32,
) -> Option<AudioCommand> {
    match canonicalize_automation_target(target.clone()) {
        AutomationTarget::MasterVolume => Some(AudioCommand::SetMaster(value)),
        AutomationTarget::MasterPan => Some(AudioCommand::SetMasterPan(value)),
        AutomationTarget::MixerVolume { track } => project
            .mixer_runtime_slot(track)
            .map(|track| AudioCommand::SetTrackGain { track, gain: value }),
        AutomationTarget::MixerPan { track } => project
            .mixer_runtime_slot(track)
            .map(|track| AudioCommand::SetTrackPan { track, pan: value }),
        AutomationTarget::MixerMute { track } => {
            project
                .mixer_runtime_slot(track)
                .map(|track| AudioCommand::SetTrackMuted {
                    track,
                    muted: value >= 0.5,
                })
        }
        AutomationTarget::Tempo
        | AutomationTarget::Swing
        | AutomationTarget::ChannelVolume { .. }
        | AutomationTarget::ChannelPan { .. }
        | AutomationTarget::ChannelMute { .. }
        | AutomationTarget::PluginParameter { .. } => None,
    }
}

fn canonicalized_runtime_lane(source: &AutomationLane) -> AutomationLane {
    let target = canonicalize_automation_target(source.target().clone());
    if target == *source.target() {
        return source.clone();
    }

    // Rebuild only the transient copy. Using `set_target` would normalize from
    // a custom source range into the default range and could alter saved values.
    let mut lane = AutomationLane::new(target);
    lane.set_enabled(source.is_enabled());
    lane.set_curve(source.curve());
    lane.set_value_range(source.value_range())
        .expect("an existing automation lane has a validated value range");
    lane.set_loop_region(source.loop_region())
        .expect("an existing automation lane has a validated loop region");
    lane.replace_points(source.points().iter().copied());
    lane
}

fn automation_runtime_lanes_at_beat(project: &Project, beat: f32) -> Vec<ProjectAutomation> {
    if !beat.is_finite() {
        return Vec::new();
    }
    let mut active = Vec::new();
    for automation in &project.automation_lanes {
        let placements = project
            .clips
            .iter()
            .filter(|clip| {
                clip.kind == ClipKind::Automation && clip.automation_id == Some(automation.id)
            })
            .collect::<Vec<_>>();
        if placements.is_empty() {
            let mut runtime_automation = automation.clone();
            runtime_automation.lane = canonicalized_runtime_lane(&automation.lane);
            active.push(runtime_automation);
            continue;
        }
        for placement in placements {
            if placement.muted
                || beat < placement.start
                || beat >= placement.start + placement.length
            {
                continue;
            }
            let source_beat = placement.source_offset + (beat - placement.start);
            let Some(value) = automation.lane.evaluate(f64::from(source_beat)) else {
                continue;
            };
            let mut lane = AutomationLane::new(canonicalize_automation_target(
                automation.lane.target().clone(),
            ));
            lane.set_curve(automation.lane.curve());
            lane.set_enabled(automation.lane.is_enabled());
            let _ = lane.set_value_range(automation.lane.value_range());
            lane.replace_points([AutomationPoint::new(f64::from(beat), value)]);
            active.push(ProjectAutomation {
                id: automation.id,
                name: automation.name.clone(),
                lane,
            });
        }
    }
    active
}

fn project_has_active_vst_placements(project: &Project) -> bool {
    project.plugin_instances.iter().any(|instance| {
        instance.enabled
            && !instance.bypass
            && (project
                .mixer_insert_slots
                .iter()
                .any(|slot_ref| slot_ref.plugin_instance_id == instance.id)
                || project
                    .channels
                    .iter()
                    .any(|channel| channel.instrument_plugin_instance_id == Some(instance.id)))
    })
}

fn plugin_target_label(target: PluginPickerTarget) -> String {
    match target {
        PluginPickerTarget::MixerSlot { track, slot } => {
            format!("mixer {track:02}, slot {:02}", slot + 1)
        }
        PluginPickerTarget::ChannelDevice { channel } => {
            format!("channel {:02} generator", channel + 1)
        }
    }
}

fn plugin_target_has_instance(project: &Project, target: PluginPickerTarget) -> bool {
    match target {
        PluginPickerTarget::MixerSlot { track, slot } => {
            plugin_slot_view(project, track, slot).is_some()
        }
        PluginPickerTarget::ChannelDevice { channel } => {
            channel_plugin_view(project, channel).is_some()
        }
    }
}

fn plugin_target_expected_label(target: PluginPickerTarget) -> &'static str {
    match target {
        PluginPickerTarget::MixerSlot { .. } => "effect",
        PluginPickerTarget::ChannelDevice { .. } => "instrument",
    }
}

fn plugin_descriptor_matches_target(
    descriptor: &PluginDescriptor,
    target: PluginPickerTarget,
) -> bool {
    match target {
        PluginPickerTarget::MixerSlot { .. } => !descriptor.is_instrument,
        PluginPickerTarget::ChannelDevice { .. } => descriptor.is_instrument,
    }
}

fn snapshot_mixer_plugin_track(project: &Project, track: usize) -> MixerPluginTrackState {
    let track_id = project.mixer_track_id_at_runtime_slot(track);
    let mut slots = project
        .mixer_insert_slots
        .iter()
        .filter(|slot_ref| Some(slot_ref.track) == track_id)
        .cloned()
        .collect::<Vec<_>>();
    slots.sort_by_key(|slot_ref| slot_ref.slot);
    let instances = slots
        .iter()
        .filter_map(|slot_ref| {
            project
                .plugin_instances
                .iter()
                .find(|instance| instance.id == slot_ref.plugin_instance_id)
                .cloned()
        })
        .collect();
    MixerPluginTrackState { slots, instances }
}

fn mixer_track_matches_state(
    project: &Project,
    track: usize,
    expected: &MixerPluginTrackState,
) -> bool {
    let current = snapshot_mixer_plugin_track(project, track);
    current.slots == expected.slots
}

fn restore_mixer_plugin_track(project: &mut Project, track: usize, state: &MixerPluginTrackState) {
    let track_id = project.mixer_track_id_at_runtime_slot(track);
    let current_ids = project
        .mixer_insert_slots
        .iter()
        .filter(|slot_ref| Some(slot_ref.track) == track_id)
        .map(|slot_ref| slot_ref.plugin_instance_id)
        .collect::<HashSet<_>>();
    project
        .mixer_insert_slots
        .retain(|slot_ref| Some(slot_ref.track) != track_id);
    project.plugin_instances.retain(|instance| {
        !current_ids.contains(&instance.id)
            || project
                .mixer_insert_slots
                .iter()
                .any(|slot_ref| slot_ref.plugin_instance_id == instance.id)
            || project
                .channels
                .iter()
                .any(|channel| channel.instrument_plugin_instance_id == Some(instance.id))
    });

    for previous in &state.instances {
        if let Some(instance) = project
            .plugin_instances
            .iter_mut()
            .find(|instance| instance.id == previous.id)
        {
            *instance = previous.clone();
        } else {
            project.plugin_instances.push(previous.clone());
        }
    }
    project.mixer_insert_slots.extend(state.slots.clone());
    project
        .mixer_insert_slots
        .sort_by_key(|slot_ref| (slot_ref.track, slot_ref.slot));
}

fn snapshot_channel_generator(project: &Project, channel_id: u32) -> Option<ChannelGeneratorState> {
    let channel = project
        .channels
        .iter()
        .find(|channel| channel.id == channel_id)?;
    let instance_id = channel.instrument_plugin_instance_id;
    let instance = instance_id.and_then(|instance_id| {
        project
            .plugin_instances
            .iter()
            .find(|instance| instance.id == instance_id)
            .cloned()
    });
    Some(ChannelGeneratorState {
        channel_id,
        instance_id,
        instance,
    })
}

fn generator_instance_is_active(
    project: &Project,
    channel_id: u32,
    running_instance_id: u64,
) -> bool {
    let Some(channel) = project
        .channels
        .iter()
        .find(|channel| channel.id == channel_id)
    else {
        return false;
    };
    if channel.instrument_plugin_instance_id != Some(running_instance_id) {
        return false;
    }
    project
        .plugin_instances
        .iter()
        .find(|instance| instance.id == running_instance_id)
        .is_some_and(|instance| {
            instance.runtime_status == PluginRuntimeStatus::Loaded
                && instance.enabled
                && !instance.bypass
        })
}

fn generator_install_confirmation_matches(
    expected_channel_id: u32,
    expected_endpoint_id: u64,
    expected_plugin_instance_id: u64,
    actual_channel_id: u32,
    actual_endpoint_id: u64,
    actual_plugin_instance_id: u64,
) -> bool {
    expected_channel_id == actual_channel_id
        && expected_endpoint_id == actual_endpoint_id
        && expected_plugin_instance_id == actual_plugin_instance_id
}

fn next_project_session(current: u64) -> u64 {
    next_nonzero_app_id(current)
}

fn plugin_runtime_session_is_current(chain_session: u64, project_session: u64) -> bool {
    chain_session == project_session
}

fn plugin_parameter_catalog_attempt_timed_out(
    phase: PluginParameterCatalogPhase,
    has_request_state: bool,
    has_local_error: bool,
    elapsed: Duration,
) -> bool {
    phase == PluginParameterCatalogPhase::Loading
        && has_request_state
        && !has_local_error
        && elapsed >= PLUGIN_PARAMETER_CATALOG_TIMEOUT
}

fn plugin_endpoint_confirmation_needs_rebuild(
    confirmation_session: u64,
    project_session: u64,
    had_deferred_rebuild: bool,
) -> bool {
    !plugin_runtime_session_is_current(confirmation_session, project_session)
        || had_deferred_rebuild
}

fn plugin_rebuild_error_is_transient(error: &str) -> bool {
    error.ends_with("queue is full")
}

fn plugin_runtime_transport_ready<I>(
    project_session: u64,
    topology_is_settling: bool,
    running_chain_sessions: I,
) -> bool
where
    I: IntoIterator<Item = u64>,
{
    !topology_is_settling
        && running_chain_sessions
            .into_iter()
            .all(|session| plugin_runtime_session_is_current(session, project_session))
}

fn generator_parameter_route<I>(routes: I, instance_id: u64) -> Option<(u32, usize)>
where
    I: IntoIterator<Item = (u32, u64)>,
{
    routes
        .into_iter()
        .find_map(|(channel_id, candidate)| (candidate == instance_id).then_some((channel_id, 0)))
}

fn generator_midi_velocity(velocity: f32) -> Option<u8> {
    (velocity.is_finite() && velocity > 0.0)
        .then(|| (velocity.clamp(0.0, 1.0) * 127.0).round().clamp(1.0, 127.0) as u8)
}

fn plugin_parameter_base_value(project: &Project, instance_id: u64, parameter: u32) -> Option<f32> {
    project
        .plugin_instances
        .iter()
        .find(|plugin| plugin.id == instance_id)
        .and_then(|plugin| plugin.parameters.get(&parameter))
        .copied()
}

fn plugin_parameter_playlist_track(project: &Project, instance_id: u64) -> Option<usize> {
    project
        .mixer_insert_slots
        .iter()
        .find(|slot| slot.plugin_instance_id == instance_id)
        .and_then(|slot| project.mixer_runtime_slot(slot.track))
        .or_else(|| {
            project
                .channels
                .iter()
                .find(|channel| channel.instrument_plugin_instance_id == Some(instance_id))
                .and_then(|channel| project.mixer_runtime_slot(channel.mixer_track))
        })
}

fn next_available_automation_id(project: &Project) -> Option<u64> {
    let mut used = project
        .automation_lanes
        .iter()
        .map(|automation| automation.id)
        .filter(|id| *id != 0)
        .collect::<HashSet<_>>();
    used.extend(
        project
            .clips
            .iter()
            .filter_map(|clip| clip.automation_id)
            .filter(|id| *id != 0),
    );
    let upper = u64::try_from(used.len()).ok()?.checked_add(1)?;
    (1..=upper).find(|candidate| !used.contains(candidate))
}

fn next_available_clip_id(project: &Project) -> Option<u32> {
    let used = project
        .clips
        .iter()
        .map(|clip| clip.id)
        .filter(|id| *id != 0)
        .collect::<HashSet<_>>();
    let upper = u32::try_from(used.len()).ok()?.checked_add(1)?;
    (1..=upper).find(|candidate| !used.contains(candidate))
}

#[allow(clippy::too_many_arguments)]
fn ensure_plugin_parameter_automation(
    project: &mut Project,
    instance_id: u64,
    parameter_id: u32,
    current_normalized: f32,
    parameter_name: &str,
    requested_start: f32,
    snap: f32,
    playlist_track: usize,
) -> Result<PluginParameterAutomationSelection, String> {
    if !current_normalized.is_finite() || !(0.0..=1.0).contains(&current_normalized) {
        return Err("the plug-in returned an invalid normalized value".into());
    }
    let Some(plugin_index) = project
        .plugin_instances
        .iter()
        .position(|plugin| plugin.id == instance_id)
    else {
        return Err("the plug-in instance no longer exists".into());
    };
    let target = AutomationTarget::PluginParameter {
        instance: instance_id,
        parameter: parameter_id,
    };
    let matching = project
        .automation_lanes
        .iter()
        .enumerate()
        .filter_map(|(index, automation)| (automation.lane.target() == &target).then_some(index))
        .collect::<Vec<_>>();
    if matching.len() > 1 {
        return Err("multiple automation lanes already target this plug-in parameter".into());
    }

    let created_lane = matching.is_empty();
    let (automation_id, new_lane_name) = if let Some(index) = matching.first().copied() {
        let automation_id = project.automation_lanes[index].id;
        if automation_id == 0 {
            return Err("the existing automation lane has a reserved zero identity".into());
        }
        (automation_id, None)
    } else {
        let automation_id = next_available_automation_id(project)
            .ok_or_else(|| "no automation identity is available".to_owned())?;
        let display_parameter = if parameter_name.trim().is_empty() {
            format!("Parameter {parameter_id}")
        } else {
            parameter_name.trim().to_owned()
        };
        let name = format!(
            "{} · {display_parameter}",
            project.plugin_instances[plugin_index].name
        );
        (automation_id, Some(name))
    };

    let existing_clip = project
        .clips
        .iter()
        .filter(|clip| {
            clip.kind == ClipKind::Automation && clip.automation_id == Some(automation_id)
        })
        .min_by(|left, right| {
            left.start
                .total_cmp(&right.start)
                .then_with(|| left.id.cmp(&right.id))
        })
        .map(|clip| clip.id);
    if let Some(clip_id) = existing_clip {
        debug_assert!(!created_lane);
        return Ok(PluginParameterAutomationSelection {
            clip_id,
            created_lane,
            created_clip: false,
        });
    }

    let clip_id = next_available_clip_id(project)
        .ok_or_else(|| "no Playlist clip identity is available".to_owned())?;
    let song_length = project.song_length_beats;
    let grid = if snap.is_finite() && snap > 0.0 {
        snap
    } else {
        0.25
    };
    let max_start = (song_length - grid.min(song_length)).max(0.0);
    let start = if requested_start.is_finite() {
        ((requested_start / grid).floor() * grid).clamp(0.0, max_start)
    } else {
        0.0
    };
    let length = 4.0_f32.min(song_length - start);
    if !length.is_finite() || length <= 0.0 {
        return Err("the project has no room for an automation clip".into());
    }
    let name = if let Some(name) = new_lane_name {
        name
    } else {
        project
            .automation_lanes
            .iter()
            .find(|automation| automation.id == automation_id)
            .map(|automation| automation.name.clone())
            .ok_or_else(|| "the automation lane disappeared".to_owned())?
    };
    let pattern_id = project.active_pattern().id;
    if created_lane {
        let mut lane = AutomationLane::new(target);
        lane.set_curve(AutomationCurve::Tension);
        lane.replace_points([
            AutomationPoint::new(0.0, f64::from(current_normalized)),
            AutomationPoint::new(f64::from(length), f64::from(current_normalized)),
        ]);
        project.automation_lanes.push(ProjectAutomation {
            id: automation_id,
            name: name.clone(),
            lane,
        });
    }
    project.plugin_instances[plugin_index]
        .parameters
        .entry(parameter_id)
        .or_insert(current_normalized);
    project.clips.push(Clip {
        id: clip_id,
        track: playlist_track.min(PLAYLIST_TRACK_COUNT.saturating_sub(1)),
        start,
        length,
        name,
        color: [184, 106, 255],
        kind: ClipKind::Automation,
        group_id: None,
        pattern_id,
        automation_id: Some(automation_id),
        audio_asset_id: None,
        source_offset: 0.0,
        audio_source_offset_frame: None,
        audio_source_reference: None,
        audio_length_reference: None,
        fade_in_reference: None,
        fade_out_reference: None,
        gain: 1.0,
        fade_in: 0.0,
        fade_out: 0.0,
        muted: false,
    });
    Ok(PluginParameterAutomationSelection {
        clip_id,
        created_lane,
        created_clip: true,
    })
}

fn plugin_parameter_replay_values(project: &Project, instance_id: u64) -> Vec<(u32, f32)> {
    project
        .plugin_instances
        .iter()
        .find(|plugin| plugin.id == instance_id)
        .map(|plugin| {
            plugin
                .parameters
                .iter()
                .map(|(parameter, value)| (*parameter, *value))
                .collect()
        })
        .unwrap_or_default()
}

fn initialize_ready_plugin_slot(
    project: &Project,
    instance_ids: &[u64],
    slot: usize,
    control: &PluginChainControl,
) -> ReadyInitializationFailures {
    let mut failures = ReadyInitializationFailures::default();
    if let Some(instance_id) = instance_ids.get(slot) {
        for (parameter, value) in plugin_parameter_replay_values(project, *instance_id) {
            if !control.set_parameter(slot, parameter, value) {
                failures.parameter_commands = failures.parameter_commands.saturating_add(1);
            }
        }
    }
    if !control.request_state(slot) {
        failures.state_requests = 1;
    }
    failures
}

fn runtime_event_instance_id(instance_ids: &[u64], event: &RuntimeEvent) -> Option<u64> {
    let slot = match event {
        RuntimeEvent::SlotReady { slot, .. }
        | RuntimeEvent::SlotFault { slot, .. }
        | RuntimeEvent::ParameterValue { slot, .. }
        | RuntimeEvent::ParameterCatalogPage { slot, .. }
        | RuntimeEvent::ParameterSetAck { slot, .. }
        | RuntimeEvent::ParameterCommandFailed { slot, .. }
        | RuntimeEvent::State { slot, .. } => *slot,
        RuntimeEvent::ShutdownComplete => return None,
    };
    instance_ids.get(slot).copied()
}

fn runtime_parameter_edit_receipt_slot(receipt: RuntimeParameterEditReceipt) -> usize {
    match receipt {
        RuntimeParameterEditReceipt::Applied { slot, .. }
        | RuntimeParameterEditReceipt::Failed { slot, .. } => usize::from(slot),
    }
}

fn runtime_parameter_edit_receipt_parameter(receipt: RuntimeParameterEditReceipt) -> u32 {
    match receipt {
        RuntimeParameterEditReceipt::Applied { id, .. }
        | RuntimeParameterEditReceipt::Failed { id, .. } => id,
    }
}

fn map_runtime_parameter_edit_receipt(
    route: ParameterEditRoute,
    receipt: RuntimeParameterEditReceipt,
) -> WorkerEditReceipt {
    match receipt {
        RuntimeParameterEditReceipt::Applied {
            edit_id, effective, ..
        } => WorkerEditReceipt::Applied {
            edit_id: crate::plugin_parameter_edit::ParameterEditId(edit_id.get()),
            route,
            effective_normalized: effective,
        },
        RuntimeParameterEditReceipt::Failed {
            edit_id, reason, ..
        } => WorkerEditReceipt::Failed {
            edit_id: crate::plugin_parameter_edit::ParameterEditId(edit_id.get()),
            route,
            reason: match reason {
                RuntimeParameterEditFailureReason::BackendRejected => {
                    WorkerFailureReason::BackendRejected
                }
                RuntimeParameterEditFailureReason::SlotUnavailable => {
                    WorkerFailureReason::MissingSlot
                }
                RuntimeParameterEditFailureReason::SlotFaulted
                | RuntimeParameterEditFailureReason::BackendPanicked
                | RuntimeParameterEditFailureReason::EndpointDropped
                | RuntimeParameterEditFailureReason::WorkerStopped => {
                    WorkerFailureReason::InstanceFaulted
                }
                RuntimeParameterEditFailureReason::InputGap
                | RuntimeParameterEditFailureReason::EpochReset
                | RuntimeParameterEditFailureReason::WorkerEpochMismatch => {
                    WorkerFailureReason::ProtocolFault
                }
            },
        },
    }
}

fn apply_plugin_runtime_event_for_session(
    project: &mut Project,
    project_session: u64,
    event_session: u64,
    instance_ids: &[u64],
    event: &RuntimeEvent,
) -> Option<String> {
    plugin_runtime_session_is_current(event_session, project_session)
        .then(|| apply_plugin_runtime_event(project, instance_ids, event))
        .flatten()
}

fn channel_generator_matches_state(
    project: &Project,
    channel_id: u32,
    expected: &ChannelGeneratorState,
) -> bool {
    snapshot_channel_generator(project, channel_id)
        .is_some_and(|current| current.instance_id == expected.instance_id)
}

fn restore_channel_generator(project: &mut Project, state: &ChannelGeneratorState) {
    let Some(channel_index) = project
        .channels
        .iter()
        .position(|channel| channel.id == state.channel_id)
    else {
        return;
    };
    let replaced_id = project.channels[channel_index].instrument_plugin_instance_id;
    project.channels[channel_index].instrument_plugin_instance_id = state.instance_id;

    if let Some(replaced_id) = replaced_id
        && Some(replaced_id) != state.instance_id
        && !project
            .channels
            .iter()
            .any(|channel| channel.instrument_plugin_instance_id == Some(replaced_id))
        && !project
            .mixer_insert_slots
            .iter()
            .any(|slot_ref| slot_ref.plugin_instance_id == replaced_id)
    {
        project
            .plugin_instances
            .retain(|instance| instance.id != replaced_id);
    }
    if let Some(previous) = &state.instance {
        if let Some(instance) = project
            .plugin_instances
            .iter_mut()
            .find(|instance| instance.id == previous.id)
        {
            *instance = previous.clone();
        } else {
            project.plugin_instances.push(previous.clone());
        }
    }
}

fn plugin_instance_runtime_spec(instance: &PluginInstance) -> PluginLoadSpec {
    PluginLoadSpec {
        descriptor: PluginDescriptor {
            id: instance.uid.clone(),
            name: instance.name.clone(),
            vendor: instance.vendor.clone(),
            path: instance.path.clone(),
            format: match instance.format {
                ProjectPluginFormat::Vst2 => ScannedPluginFormat::Vst2,
                ProjectPluginFormat::Vst3 => ScannedPluginFormat::Vst3,
            },
            category: project_plugin_role_label(instance.role).to_owned(),
            is_instrument: instance.role == PluginRole::Instrument,
            verified: instance.path.exists(),
        },
        class_uid: None,
        vst3_helper_path: None,
        initial_state: instance.opaque_state.clone(),
        enabled: instance.enabled,
        bypassed: instance.bypass,
        wet: instance.wet,
    }
}

fn channel_generator_runtime_spec(
    project: &Project,
    channel_id: u32,
) -> Result<Option<(u64, usize, PluginLoadSpec)>, String> {
    let channel = project
        .channels
        .iter()
        .find(|channel| channel.id == channel_id)
        .ok_or_else(|| format!("channel {channel_id} does not exist"))?;
    let Some(instance_id) = channel.instrument_plugin_instance_id else {
        return Ok(None);
    };
    let instance = project
        .plugin_instances
        .iter()
        .find(|instance| instance.id == instance_id)
        .ok_or_else(|| {
            format!("channel {channel_id} references missing plug-in instance {instance_id}")
        })?;
    let mixer_runtime_slot = project
        .mixer_runtime_slot(channel.mixer_track)
        .ok_or_else(|| format!("channel {channel_id} has a missing mixer destination"))?;
    Ok(Some((
        instance_id,
        mixer_runtime_slot,
        plugin_instance_runtime_spec(instance),
    )))
}

fn mixer_track_runtime_specs(
    project: &Project,
    track: usize,
) -> Result<(Vec<u64>, Vec<PluginLoadSpec>), String> {
    let state = snapshot_mixer_plugin_track(project, track);
    if state.instances.len() != state.slots.len() {
        return Err(format!(
            "mixer {track:02} contains a plug-in slot with a missing instance"
        ));
    }
    let mut instance_ids = Vec::with_capacity(state.instances.len());
    let mut specs = Vec::with_capacity(state.instances.len());
    for instance in state.instances {
        instance_ids.push(instance.id);
        specs.push(plugin_instance_runtime_spec(&instance));
    }
    Ok((instance_ids, specs))
}

fn runtime_slot_for_instance(instance_ids: &[u64], instance_id: u64) -> Option<usize> {
    instance_ids
        .iter()
        .position(|candidate| *candidate == instance_id)
}

fn mark_mixer_track_runtime_pending(project: &mut Project, track: usize) {
    let track_id = project.mixer_track_id_at_runtime_slot(track);
    let instance_ids = project
        .mixer_insert_slots
        .iter()
        .filter(|slot_ref| Some(slot_ref.track) == track_id)
        .map(|slot_ref| slot_ref.plugin_instance_id)
        .collect::<HashSet<_>>();
    for instance in &mut project.plugin_instances {
        if instance_ids.contains(&instance.id)
            && instance.runtime_status != PluginRuntimeStatus::Missing
        {
            instance.runtime_status = PluginRuntimeStatus::Unloaded;
        }
    }
}

fn mark_mixer_track_runtime_error(project: &mut Project, track: usize, error: &str) {
    let track_id = project.mixer_track_id_at_runtime_slot(track);
    let instance_ids = project
        .mixer_insert_slots
        .iter()
        .filter(|slot_ref| Some(slot_ref.track) == track_id)
        .map(|slot_ref| slot_ref.plugin_instance_id)
        .collect::<HashSet<_>>();
    let status = if error.contains("does not exist") || error.contains("missing") {
        PluginRuntimeStatus::Missing
    } else if error.contains("audio engine is unavailable") {
        PluginRuntimeStatus::Unloaded
    } else {
        PluginRuntimeStatus::Crashed
    };
    for instance in &mut project.plugin_instances {
        if instance_ids.contains(&instance.id) {
            instance.runtime_status = status;
        }
    }
}

fn mark_channel_generator_runtime_pending(project: &mut Project, channel_id: u32) {
    let instance_id = project
        .channels
        .iter()
        .find(|channel| channel.id == channel_id)
        .and_then(|channel| channel.instrument_plugin_instance_id);
    if let Some(instance) = project
        .plugin_instances
        .iter_mut()
        .find(|instance| Some(instance.id) == instance_id)
        && instance.runtime_status != PluginRuntimeStatus::Missing
    {
        instance.runtime_status = PluginRuntimeStatus::Unloaded;
    }
}

fn mark_channel_generator_runtime_error(project: &mut Project, channel_id: u32, error: &str) {
    let instance_id = project
        .channels
        .iter()
        .find(|channel| channel.id == channel_id)
        .and_then(|channel| channel.instrument_plugin_instance_id);
    let status = if error.contains("does not exist") || error.contains("missing") {
        PluginRuntimeStatus::Missing
    } else if error.contains("audio engine is unavailable") {
        PluginRuntimeStatus::Unloaded
    } else {
        PluginRuntimeStatus::Crashed
    };
    if let Some(instance) = project
        .plugin_instances
        .iter_mut()
        .find(|instance| Some(instance.id) == instance_id)
    {
        instance.runtime_status = status;
    }
}

fn take_due_generator_note_offs(
    pending: &mut Vec<PendingGeneratorNoteOff>,
    transport_epoch: u64,
    current_frame: u64,
    limit: usize,
) -> Vec<PendingGeneratorNoteOff> {
    pending.retain(|note_off| note_off.transport_epoch == transport_epoch);
    let mut due = Vec::with_capacity(limit.min(pending.len()));
    let mut index = 0;
    while index < pending.len() && due.len() < limit {
        if pending[index].due_frame <= current_frame {
            due.push(pending.remove(index));
        } else {
            index += 1;
        }
    }
    due
}

fn note_duration_frames(
    tempo_map: Option<&TempoMap>,
    start_beat: f32,
    length_beats: f32,
    fallback_tempo: f32,
    sample_rate: u32,
) -> u64 {
    let length_beats = if length_beats.is_finite() {
        length_beats.max(0.01)
    } else {
        0.25
    };
    let start = f64::from(start_beat.max(0.0));
    let end = start + f64::from(length_beats);
    let seconds = tempo_map
        .filter(|map| end <= map.max_beat())
        .and_then(|map| {
            let start_seconds = map.beat_to_seconds(start).ok()?;
            let end_seconds = map.beat_to_seconds(end).ok()?;
            Some((end_seconds - start_seconds).max(0.0))
        })
        .unwrap_or_else(|| {
            f64::from(length_beats) * 60.0 / f64::from(fallback_tempo.clamp(20.0, 400.0))
        });
    (seconds * f64::from(sample_rate.max(1)))
        .round()
        .clamp(1.0, u64::MAX as f64) as u64
}

fn piano_note_ids(project: &Project) -> HashSet<u64> {
    project
        .patterns
        .iter()
        .flat_map(|pattern| &pattern.notes)
        .map(|note| note.id)
        .filter(|id| *id != 0)
        .collect()
}

fn allocate_piano_note_id(used: &mut HashSet<u64>) -> Option<u64> {
    let upper = u64::try_from(used.len()).ok()?.saturating_add(1);
    (1..=upper).find(|candidate| used.insert(*candidate))
}

fn requeue_generator_note_offs(
    pending: &mut Vec<PendingGeneratorNoteOff>,
    failed: Vec<PendingGeneratorNoteOff>,
    capacity: usize,
) {
    for note_off in failed {
        if let Some(existing) = pending
            .iter_mut()
            .find(|existing| existing.note_instance_id == note_off.note_instance_id)
        {
            existing.due_frame = existing.due_frame.min(note_off.due_frame);
        } else if pending.len() < capacity {
            pending.push(note_off);
        }
    }
}

fn apply_plugin_runtime_event(
    project: &mut Project,
    instance_ids: &[u64],
    event: &RuntimeEvent,
) -> Option<String> {
    let slot = match event {
        RuntimeEvent::SlotReady { slot, .. }
        | RuntimeEvent::SlotFault { slot, .. }
        | RuntimeEvent::ParameterValue { slot, .. }
        | RuntimeEvent::ParameterCatalogPage { slot, .. }
        | RuntimeEvent::ParameterSetAck { slot, .. }
        | RuntimeEvent::ParameterCommandFailed { slot, .. }
        | RuntimeEvent::State { slot, .. } => *slot,
        RuntimeEvent::ShutdownComplete => return None,
    };
    let instance_id = *instance_ids.get(slot)?;
    let instance = project
        .plugin_instances
        .iter_mut()
        .find(|instance| instance.id == instance_id)?;
    match event {
        RuntimeEvent::SlotReady { .. } => {
            instance.runtime_status = PluginRuntimeStatus::Loaded;
            None
        }
        RuntimeEvent::SlotFault { message, .. } => {
            instance.runtime_status = PluginRuntimeStatus::Crashed;
            Some(format!("{} failed: {message}", instance.name))
        }
        // Parameter readback is session-only observation. Persisted base values are changed only
        // by an explicit, acknowledged edit; otherwise merely opening a generic parameter browser
        // would dirty the project and replay an observed value on the next plug-in start.
        RuntimeEvent::ParameterValue { .. } => None,
        RuntimeEvent::ParameterCatalogPage { .. }
        | RuntimeEvent::ParameterSetAck { .. }
        | RuntimeEvent::ParameterCommandFailed { .. } => None,
        RuntimeEvent::State { bytes, .. } => {
            instance.opaque_state.clone_from(bytes);
            None
        }
        RuntimeEvent::ShutdownComplete => None,
    }
}

fn validate_plugin_load(
    project: &Project,
    descriptor: &PluginDescriptor,
    target: PluginPickerTarget,
) -> Result<(), String> {
    if !plugin_target_is_valid(project, target) {
        return Err("the target plug-in destination is out of range".into());
    }
    if descriptor.path.to_string_lossy().trim().is_empty() {
        return Err("the indexed plug-in has no file path".into());
    }
    Ok(())
}

fn plugin_slot_view(project: &Project, track: usize, slot: usize) -> Option<PluginSlotView> {
    let track_id = project.mixer_track_id_at_runtime_slot(track)?;
    project
        .mixer_insert_slots
        .iter()
        .rev()
        .filter(|slot_ref| slot_ref.track == track_id && slot_ref.slot == slot)
        .find_map(|slot_ref| {
            project
                .plugin_instances
                .iter()
                .find(|instance| instance.id == slot_ref.plugin_instance_id)
        })
        .map(|instance| PluginSlotView {
            instance_id: instance.id,
            name: instance.name.clone(),
            format: instance.format,
            role: instance.role,
            enabled: instance.enabled,
            bypass: instance.bypass,
            wet: instance.wet,
            runtime_status: instance.runtime_status,
        })
}

fn channel_plugin_view(project: &Project, channel: usize) -> Option<PluginSlotView> {
    let instance_id = project
        .channels
        .get(channel)?
        .instrument_plugin_instance_id?;
    project
        .plugin_instances
        .iter()
        .find(|instance| instance.id == instance_id)
        .map(|instance| PluginSlotView {
            instance_id: instance.id,
            name: instance.name.clone(),
            format: instance.format,
            role: instance.role,
            enabled: instance.enabled,
            bypass: instance.bypass,
            wet: instance.wet,
            runtime_status: instance.runtime_status,
        })
}

fn first_empty_mixer_slot(project: &Project, track: usize) -> Option<usize> {
    project.mixer_track_id_at_runtime_slot(track)?;
    (0..MIXER_INSERT_SLOT_COUNT).find(|slot| plugin_slot_view(project, track, *slot).is_none())
}

fn next_plugin_instance_id(project: &Project) -> Option<u64> {
    let mut used = project
        .plugin_instances
        .iter()
        .map(|instance| instance.id)
        .collect::<HashSet<_>>();
    for automation in &project.automation_lanes {
        if let AutomationTarget::PluginParameter { instance, .. } = automation.lane.target() {
            used.insert(*instance);
        }
    }
    let mut candidate = used
        .iter()
        .copied()
        .max()
        .unwrap_or(0)
        .wrapping_add(1)
        .max(1);
    for _ in 0..=used.len() {
        if !used.contains(&candidate) {
            return Some(candidate);
        }
        candidate = candidate.wrapping_add(1).max(1);
    }
    None
}

fn commit_loaded_plugin(
    project: &mut Project,
    target: PluginPickerTarget,
    descriptor: &PluginDescriptor,
) -> Result<u64, String> {
    validate_plugin_load(project, descriptor, target)?;
    let instance_id = next_plugin_instance_id(project)
        .ok_or_else(|| "the project has no available plug-in instance IDs".to_owned())?;
    let _ = remove_plugin_from_target(project, target);

    let descriptor_name = descriptor.name.trim();
    let name = if descriptor_name.is_empty() {
        descriptor
            .path
            .file_stem()
            .and_then(|name| name.to_str())
            .map(str::trim)
            .filter(|name| !name.is_empty())
            .unwrap_or("VST plug-in")
            .to_owned()
    } else {
        descriptor_name.to_owned()
    };
    project.plugin_instances.push(PluginInstance {
        id: instance_id,
        format: match descriptor.format {
            ScannedPluginFormat::Vst2 => ProjectPluginFormat::Vst2,
            ScannedPluginFormat::Vst3 => ProjectPluginFormat::Vst3,
        },
        role: if descriptor.is_instrument {
            PluginRole::Instrument
        } else {
            PluginRole::Effect
        },
        path: descriptor.path.clone(),
        uid: descriptor.id.trim().to_owned(),
        vendor: descriptor.vendor.trim().to_owned(),
        name,
        enabled: true,
        bypass: false,
        wet: 1.0,
        parameters: Default::default(),
        opaque_state: Vec::new(),
        // The discovery host opened the binary successfully, but MIDI/audio
        // graph routing is a later integration step. Keep project/UI state
        // honest until that runtime owns the instance.
        runtime_status: PluginRuntimeStatus::Unloaded,
    });
    match target {
        PluginPickerTarget::MixerSlot { track, slot } => {
            let track = project
                .mixer_track_id_at_runtime_slot(track)
                .ok_or_else(|| "the target mixer runtime slot does not exist".to_owned())?;
            project.mixer_insert_slots.push(MixerInsertSlotRef {
                track,
                slot,
                plugin_instance_id: instance_id,
            });
            project
                .mixer_insert_slots
                .sort_by_key(|slot_ref| (slot_ref.track, slot_ref.slot));
        }
        PluginPickerTarget::ChannelDevice { channel } => {
            project.channels[channel].instrument_plugin_instance_id = Some(instance_id);
        }
    }
    Ok(instance_id)
}

fn remove_plugin_from_target(project: &mut Project, target: PluginPickerTarget) -> Option<String> {
    let removed_ids = match target {
        PluginPickerTarget::MixerSlot { track, slot } => {
            let track_id = project.mixer_track_id_at_runtime_slot(track)?;
            let ids = project
                .mixer_insert_slots
                .iter()
                .filter(|slot_ref| slot_ref.track == track_id && slot_ref.slot == slot)
                .map(|slot_ref| slot_ref.plugin_instance_id)
                .collect::<HashSet<_>>();
            project
                .mixer_insert_slots
                .retain(|slot_ref| slot_ref.track != track_id || slot_ref.slot != slot);
            ids
        }
        PluginPickerTarget::ChannelDevice { channel } => project
            .channels
            .get_mut(channel)
            .and_then(|channel| channel.instrument_plugin_instance_id.take())
            .into_iter()
            .collect(),
    };
    if removed_ids.is_empty() {
        return None;
    }
    let removed_name = project
        .plugin_instances
        .iter()
        .find(|instance| removed_ids.contains(&instance.id))
        .map(|instance| instance.name.clone());
    project.plugin_instances.retain(|instance| {
        !removed_ids.contains(&instance.id)
            || project
                .mixer_insert_slots
                .iter()
                .any(|slot_ref| slot_ref.plugin_instance_id == instance.id)
            || project
                .channels
                .iter()
                .any(|channel| channel.instrument_plugin_instance_id == Some(instance.id))
    });
    removed_name
}

