    #[test]
    fn catalog_worker_reducer_ignores_stale_results_and_retains_last_good_on_error() {
        assert!(audio_catalog_refresh_can_start(None));
        assert!(!audio_catalog_refresh_can_start(Some(8)));
        let mut catalog = AudioDeviceCatalog {
            diagnostics: vec!["last-good".into()],
            ..Default::default()
        };
        let last_good = catalog.clone();
        let mut pending = Some(8);
        let mut error = None;
        assert!(!apply_audio_catalog_worker_result(
            &mut pending,
            &mut catalog,
            &mut error,
            7,
            Ok(AudioDeviceCatalog::default()),
        ));
        assert_eq!(pending, Some(8));
        assert_eq!(catalog, last_good);
        assert!(apply_audio_catalog_worker_result(
            &mut pending,
            &mut catalog,
            &mut error,
            8,
            Err("host refresh failed".into()),
        ));
        assert_eq!(pending, None);
        assert_eq!(catalog, last_good);
        assert_eq!(error.as_deref(), Some("host refresh failed"));
    }

    #[test]
    fn cached_audio_asset_reuses_the_same_pcm_arc_only_for_the_exact_project_identity() {
        let asset = AudioAsset {
            id: 17,
            name: "Cached.wav".into(),
            path: PathBuf::from("Cached.wav"),
            sample_rate: 48_000,
            channels: 2,
            bits_per_sample: 24,
            frames: 2,
            waveform_peaks: Vec::new(),
        };
        let samples: Arc<[f32]> = Arc::from([0.25_f32, -0.25, 0.5, -0.5]);
        let cached = CachedAudioAssetRegistration {
            project_session: 9,
            project_asset_id: asset.id,
            path: asset.path.clone(),
            samples: Arc::clone(&samples),
            sample_rate: asset.sample_rate,
            channels: asset.channels,
        };
        assert!(cached.matches(9, &asset));
        assert!(!cached.matches(10, &asset));
        let mut moved = asset.clone();
        moved.path = PathBuf::from("Moved.wav");
        assert!(!cached.matches(9, &moved));

        let prepared = cached.prepared_for_generation(41);
        assert_eq!(prepared.generation, 41);
        assert_eq!(prepared.project_asset_id, asset.id);
        assert!(Arc::ptr_eq(&samples, &prepared.samples));
    }

