    #[test]
    fn audio_preferences_round_trip_and_reject_corruption_or_unknown_versions() {
        let preferences = AppAudioPreferences {
            requested_output: exact_test_output_profile(),
            last_known_good_output: Some(exact_test_output_profile()),
            ..Default::default()
        };
        let encoded = serde_json::to_string(&preferences).unwrap();
        assert_eq!(
            decode_audio_preferences(Some(&encoded)),
            (preferences, None)
        );

        let (missing, missing_error) = decode_audio_preferences(None);
        assert_eq!(missing, AppAudioPreferences::default());
        assert_eq!(missing_error, None);

        let (corrupt, corrupt_error) = decode_audio_preferences(Some("{not-json"));
        assert_eq!(corrupt, AppAudioPreferences::default());
        assert!(corrupt_error.is_some());

        let unknown = AppAudioPreferences {
            version: AUDIO_PREFERENCES_VERSION + 1,
            ..Default::default()
        };
        let encoded = serde_json::to_string(&unknown).unwrap();
        let (reset, version_error) = decode_audio_preferences(Some(&encoded));
        assert_eq!(reset, AppAudioPreferences::default());
        assert!(version_error.is_some());

        let mut invalid = AppAudioPreferences::default();
        invalid.requested_output.sample_rate = AudioSampleRateRequest::Exact(0);
        let encoded = serde_json::to_string(&invalid).unwrap();
        assert_eq!(
            decode_audio_preferences(Some(&encoded)).0,
            AppAudioPreferences::default()
        );
    }

    #[test]
    fn piano_roll_preferences_round_trip_and_reject_corruption_or_invalid_metadata() {
        let preferences = PianoRollPreferences {
            scale_root: 6,
            scale: PianoScale::Dorian,
            scale_highlighting: true,
            snap_to_scale: true,
            chord_stamp: PianoChordStamp::Dominant7,
            stamp_only_one: true,
            ..PianoRollPreferences::default()
        };
        let encoded = serde_json::to_string(&preferences).unwrap();
        assert_eq!(
            decode_piano_roll_preferences(Some(&encoded)),
            (preferences.clone(), None)
        );
        assert_eq!(
            decode_piano_roll_preferences(None),
            (PianoRollPreferences::default(), None)
        );

        let (corrupt, corrupt_error) = decode_piano_roll_preferences(Some("{not-json"));
        assert_eq!(corrupt, PianoRollPreferences::default());
        assert!(corrupt_error.is_some());

        for invalid in [
            PianoRollPreferences {
                version: crate::piano_roll::PIANO_ROLL_PREFERENCES_VERSION + 1,
                ..preferences.clone()
            },
            PianoRollPreferences {
                scale_root: 12,
                ..preferences.clone()
            },
        ] {
            let encoded = serde_json::to_string(&invalid).unwrap();
            let (reset, error) = decode_piano_roll_preferences(Some(&encoded));
            assert_eq!(reset, PianoRollPreferences::default());
            assert!(error.is_some());
        }
    }

    #[test]
    fn audio_settings_draft_is_not_persisted_and_cannot_dirty_the_project() {
        let project = Project::default();
        let project_before = project_fingerprint(&project);
        let committed = AppAudioPreferences::default();
        let encoded_before = serde_json::to_string(&committed).unwrap();
        let mut draft = committed.requested_output.clone();
        draft.sample_rate = AudioSampleRateRequest::Exact(96_000);
        draft.buffer_size = AudioBufferSizeRequest::Fixed(256);

        assert_ne!(draft, committed.requested_output);
        assert_eq!(serde_json::to_string(&committed).unwrap(), encoded_before);
        assert_eq!(project_fingerprint(&project), project_before);
    }

