    fn paired_recording_note(start_device_frame: u64, end_device_frame: u64) -> PairedMidiNote {
        PairedMidiNote {
            connection_epoch: 9,
            transport_epoch: 7,
            channel: 0,
            key: 64,
            velocity: 100,
            release_velocity: 3,
            start_device_frame,
            end_device_frame,
            start_timeline_frame: start_device_frame.saturating_sub(1_000),
            end_timeline_frame: end_device_frame.saturating_sub(1_000),
            start_timestamp_us: 1,
            end_timestamp_us: 2,
            start_sequence: 4,
            end_sequence: 5,
            end: crate::midi_runtime::PairedNoteEnd::NoteOff,
        }
    }

    fn saturated_disabled_mixer_route_project() -> Project {
        let mut project = Project::blank();
        project.mixer_routes.clear();
        let track_ids = project
            .mixer_tracks
            .iter()
            .map(|track| track.id)
            .collect::<Vec<_>>();
        let taps = [
            MixerRouteTap::PreEffects,
            MixerRouteTap::PostEffects,
            MixerRouteTap::PostFader,
        ];
        'routes: for source_id in &track_ids {
            for destination_id in &track_ids {
                if source_id == destination_id {
                    continue;
                }
                for tap in taps {
                    let runtime_slot = project.mixer_routes.len();
                    project.mixer_routes.push(MixerRoute {
                        id: runtime_slot as u64 + 1,
                        runtime_slot: runtime_slot as u8,
                        source_mixer_track_id: *source_id,
                        destination: MixerRouteDestination::MainInput {
                            mixer_track_id: *destination_id,
                        },
                        tap,
                        gain: 1.0,
                        enabled: false,
                    });
                    if project.mixer_routes.len() == MIXER_GRAPH_MAX_EDGES {
                        break 'routes;
                    }
                }
            }
        }
        project.validate_mixer_graph().unwrap();
        project
    }

    #[test]
    fn mixer_display_reorder_preserves_runtime_commands_graph_and_selected_slot() {
        let mut project = Project::blank();
        let selected_runtime_slot = 7;
        let selected_id = project
            .mixer_track_id_at_runtime_slot(selected_runtime_slot)
            .unwrap();
        project
            .mixer_tracks
            .iter_mut()
            .find(|track| track.id == selected_id)
            .unwrap()
            .volume = 0.321;
        let graph_before = compile_mixer_graph(&project).unwrap().fingerprint();
        let timeline_before = timeline_compile_fingerprint(&project, 48_000);
        let index_before = project.mixer_track_index(selected_id).unwrap();

        let reordered = mixer_graph_project_candidate(
            &project,
            MixerGraphProjectEdit::MoveDisplay {
                runtime_slot: selected_runtime_slot,
                direction: -1,
            },
        )
        .unwrap();

        assert_eq!(
            reordered.mixer_track_index(selected_id),
            Some(index_before - 1)
        );
        assert_eq!(
            reordered.mixer_runtime_slot(selected_id),
            Some(selected_runtime_slot)
        );
        assert_eq!(
            compile_mixer_graph(&reordered).unwrap().fingerprint(),
            graph_before
        );
        assert_eq!(
            timeline_compile_fingerprint(&reordered, 48_000),
            timeline_before,
            "display-only order must not schedule a replacement audio graph"
        );
        assert!(mixer_control_commands(&reordered).iter().any(|command| {
            matches!(
                command,
                AudioCommand::SetTrackGain { track: 7, gain }
                    if (*gain - 0.321).abs() < f32::EPSILON
            )
        }));
        assert!(plugin_target_is_valid(
            &reordered,
            PluginPickerTarget::MixerSlot { track: 7, slot: 0 }
        ));
    }

