    #[test]
    fn invalid_mixer_route_candidates_leave_original_project_unchanged() {
        let mut project = Project::blank();
        project.mixer_routes.clear();
        project = mixer_graph_project_candidate(
            &project,
            MixerGraphProjectEdit::AddMainRoute {
                source_id: 1,
                destination_id: 2,
                tap: MixerRouteTap::PostFader,
                gain: 1.0,
                enabled: true,
            },
        )
        .unwrap();
        let original = project_fingerprint(&project);
        for edit in [
            MixerGraphProjectEdit::AddMainRoute {
                source_id: 1,
                destination_id: 1,
                tap: MixerRouteTap::PostFader,
                gain: 1.0,
                enabled: true,
            },
            MixerGraphProjectEdit::AddMainRoute {
                source_id: 2,
                destination_id: 1,
                tap: MixerRouteTap::PostFader,
                gain: 1.0,
                enabled: true,
            },
            MixerGraphProjectEdit::AddMainRoute {
                source_id: MASTER_MIXER_TRACK_ID,
                destination_id: 3,
                tap: MixerRouteTap::PostFader,
                gain: 1.0,
                enabled: false,
            },
        ] {
            assert!(mixer_graph_project_candidate(&project, edit).is_err());
            assert_eq!(project_fingerprint(&project), original);
        }

        let saturated = saturated_disabled_mixer_route_project();
        let saturated_before = project_fingerprint(&saturated);
        let error = mixer_graph_project_candidate(
            &saturated,
            MixerGraphProjectEdit::AddMainRoute {
                source_id: 1,
                destination_id: 2,
                tap: MixerRouteTap::PostFader,
                gain: 1.0,
                enabled: false,
            },
        )
        .unwrap_err();
        assert!(error.contains("128 realtime mixer route slots"));
        assert_eq!(project_fingerprint(&saturated), saturated_before);
        assert!(default_add_mixer_route_edit(&project, MASTER_MIXER_TRACK_ID).is_err());

        let mut sidechain_project = Project::blank();
        sidechain_project.mixer_routes.push(MixerRoute {
            id: 32,
            runtime_slot: 31,
            source_mixer_track_id: 1,
            destination: MixerRouteDestination::PluginSidechain {
                mixer_track_id: 2,
                slot: 0,
                input_bus: 1,
            },
            tap: MixerRouteTap::PreEffects,
            gain: 1.0,
            enabled: false,
        });
        sidechain_project.validate_mixer_graph().unwrap();
        let sidechain_before = project_fingerprint(&sidechain_project);
        assert!(
            mixer_graph_project_candidate(
                &sidechain_project,
                MixerGraphProjectEdit::UpdateMainRoute {
                    route_id: 32,
                    destination_id: 3,
                    tap: MixerRouteTap::PostFader,
                    gain: 1.0,
                    enabled: true,
                },
            )
            .is_err()
        );
        assert_eq!(project_fingerprint(&sidechain_project), sidechain_before);
    }

    #[test]
    fn mixer_route_update_roundtrips_gain_tap_enabled_and_remove_is_exact() {
        let project = Project::blank();
        let mut candidate = mixer_graph_project_candidate(
            &project,
            MixerGraphProjectEdit::AddMainRoute {
                source_id: 1,
                destination_id: 2,
                tap: MixerRouteTap::PreEffects,
                gain: 0.5,
                enabled: false,
            },
        )
        .unwrap();
        let first_id = candidate.mixer_routes.last().unwrap().id;
        candidate = mixer_graph_project_candidate(
            &candidate,
            MixerGraphProjectEdit::AddMainRoute {
                source_id: 1,
                destination_id: 3,
                tap: MixerRouteTap::PreEffects,
                gain: 0.75,
                enabled: false,
            },
        )
        .unwrap();
        let second_id = candidate.mixer_routes.last().unwrap().id;
        candidate = mixer_graph_project_candidate(
            &candidate,
            MixerGraphProjectEdit::UpdateMainRoute {
                route_id: first_id,
                destination_id: 2,
                tap: MixerRouteTap::PostEffects,
                gain: 2.5,
                enabled: true,
            },
        )
        .unwrap();
        let restored: Project =
            serde_json::from_value(serde_json::to_value(&candidate).unwrap()).unwrap();
        let updated = restored
            .mixer_routes
            .iter()
            .find(|route| route.id == first_id)
            .unwrap();
        assert_eq!(updated.tap, MixerRouteTap::PostEffects);
        assert_eq!(updated.gain, 2.5);
        assert!(updated.enabled);

        let removed = mixer_graph_project_candidate(
            &restored,
            MixerGraphProjectEdit::RemoveRoute { route_id: first_id },
        )
        .unwrap();
        assert!(
            !removed
                .mixer_routes
                .iter()
                .any(|route| route.id == first_id)
        );
        assert!(
            removed
                .mixer_routes
                .iter()
                .any(|route| route.id == second_id)
        );
    }

    #[test]
    fn mixer_graph_commit_is_one_dirty_undo_transaction() {
        let mut project = Project::blank();
        let original = project.clone();
        let candidate = mixer_graph_project_candidate(
            &project,
            MixerGraphProjectEdit::MoveDisplay {
                runtime_slot: 4,
                direction: -1,
            },
        )
        .unwrap();
        let mut history_snapshot = project.clone();
        let mut history_fingerprint = project_fingerprint(&project);
        let mut undo = Vec::new();
        let mut redo = vec![Project::default()];
        let mut dirty = false;

        assert!(commit_explicit_project_history_transaction(
            &mut project,
            &mut history_snapshot,
            &mut history_fingerprint,
            &mut undo,
            &mut redo,
            &mut dirty,
            candidate,
        ));
        assert!(dirty);
        assert!(redo.is_empty());
        assert_eq!(undo.len(), 1);
        assert_eq!(
            project_fingerprint(undo.last().unwrap()),
            project_fingerprint(&original)
        );
        assert_eq!(history_fingerprint, project_fingerprint(&project));
    }

