    #[test]
    fn midi_record_frames_map_through_tempo_map_from_a_non_rounding_clip_start() {
        let project = midi_recording_project();
        let target = resolve_midi_record_new_take_target(&project, 3, Some(44), 1).unwrap();
        let target = bind_midi_record_new_take_start(target, 0.1).unwrap();
        assert!(f64::from(target.persisted_clip_start) <= target.exact_start_beat);
        let tempo_map = TempoMap::new(120.0, None, 16.0, 48_000).unwrap();
        let mut source = paired_recording_note(1_000, 25_000);
        source.start_timeline_frame = 2_400;
        // Device and Timeline deltas are deliberately not 1:1: project conversion must use the
        // exact PairedMidiNote Timeline frames, not rebuild them from device-frame deltas.
        source.end_timeline_frame = 50_400;
        let note =
            materialize_midi_record_note(source, 1_000, 2_400, 7, target, &tempo_map).unwrap();
        assert!(note.start >= 0.0 && note.start < 1.0e-5);
        assert!((note.length - 2.0).abs() < 1.0e-5);
        assert_eq!(note.channel_id, Some(1));
        assert_eq!(note.note, 64);
    }

    #[test]
    fn midi_record_materialization_rejects_epoch_and_pattern_cycle_crossing() {
        let project = midi_recording_project();
        let target = resolve_midi_record_new_take_target(&project, 3, None, 1).unwrap();
        let target = bind_midi_record_new_take_start(target, 0.0).unwrap();
        let tempo_map = TempoMap::new(120.0, None, 32.0, 48_000).unwrap();
        let mut wrong_epoch = paired_recording_note(1_000, 25_000);
        wrong_epoch.transport_epoch = 8;
        assert!(matches!(
            materialize_midi_record_note(wrong_epoch, 1_000, 0, 7, target, &tempo_map),
            Err(MidiRecordMaterializeError::TransportEpochChanged)
        ));
        assert!(matches!(
            materialize_midi_record_note(
                paired_recording_note(385_000, 409_000),
                1_000,
                0,
                7,
                target,
                &tempo_map,
            ),
            Err(MidiRecordMaterializeError::TakeExceedsPatternPeriod)
        ));
    }

    #[test]
    fn midi_take_candidate_creates_one_new_pattern_and_one_new_clip_all_or_none() {
        let mut project = midi_recording_project();
        project.patterns[0].notes.push(PianoNote {
            id: 1,
            channel_id: Some(1),
            group_id: None,
            note: 60,
            start: 0.0,
            length: 1.0,
            velocity: 1.0,
            selected: false,
            muted: false,
        });
        let target = resolve_midi_record_new_take_target(&project, 3, Some(44), 1).unwrap();
        let target = bind_midi_record_new_take_start(target, 2.0).unwrap();
        let note = PianoNote {
            id: 0,
            channel_id: Some(1),
            group_id: None,
            note: 64,
            start: 1.0,
            length: 0.5,
            velocity: 0.75,
            selected: true,
            muted: false,
        };
        let committed =
            build_new_pattern_midi_take(&project, target, std::slice::from_ref(&note), 3.5)
                .unwrap();
        assert_eq!(project.patterns[0].notes.len(), 1);
        assert_eq!(committed.pattern_id, 2);
        assert_eq!(committed.clip_id, 1);
        assert_eq!(committed.note_count, 1);
        assert_eq!(committed.project.patterns.len(), project.patterns.len() + 1);
        assert_eq!(committed.project.clips.len(), project.clips.len() + 1);
        assert_eq!(committed.project.patterns[1].notes[0].id, 2);
        assert_eq!(committed.project.clips[1].track, 6);
        assert_eq!(committed.project.clips[1].pattern_id, 2);
        assert!(f64::from(committed.project.clips[1].start) <= 2.0);
        assert!(f64::from(committed.project.clips[1].length) >= 1.5);

        let mut invalid = note;
        invalid.id = 99;
        assert!(build_new_pattern_midi_take(&project, target, &[invalid], 3.5).is_none());
        assert_eq!(project.patterns[0].notes.len(), 1);
    }

    #[test]
    fn midi_take_history_is_one_undo_transaction_and_redo_restores_the_whole_take() {
        let mut project = midi_recording_project();
        let target = resolve_midi_record_new_take_target(&project, 3, Some(44), 1).unwrap();
        let target = bind_midi_record_new_take_start(target, 2.0).unwrap();
        let note = PianoNote {
            id: 0,
            channel_id: Some(1),
            group_id: None,
            note: 67,
            start: 0.5,
            length: 0.5,
            velocity: 0.8,
            selected: true,
            muted: false,
        };
        let candidate =
            build_new_pattern_midi_take(&project, target, std::slice::from_ref(&note), 3.0)
                .unwrap();
        let before_pattern_count = project.patterns.len();
        let before_clip_count = project.clips.len();
        let mut history_snapshot = project.clone();
        let mut history_fingerprint = project_fingerprint(&project);
        let mut undo = Vec::new();
        let mut redo = vec![Project::blank()];
        let mut dirty = false;

        let commit = commit_midi_take_history_transaction(
            &mut project,
            &mut history_snapshot,
            &mut history_fingerprint,
            &mut undo,
            &mut redo,
            &mut dirty,
            Some(candidate),
        )
        .unwrap();
        assert!(dirty);
        assert!(redo.is_empty());
        assert_eq!(undo.len(), 1);
        assert_eq!(project.patterns.len(), before_pattern_count + 1);
        assert_eq!(project.clips.len(), before_clip_count + 1);
        assert!(
            project
                .patterns
                .iter()
                .any(|pattern| pattern.id == commit.pattern_id)
        );
        assert!(project.clips.iter().any(|clip| clip.id == commit.clip_id));

        let previous = undo.pop().unwrap();
        redo.push(std::mem::replace(&mut project, previous));
        assert_eq!(project.patterns.len(), before_pattern_count);
        assert_eq!(project.clips.len(), before_clip_count);
        assert!(
            !project
                .patterns
                .iter()
                .any(|pattern| pattern.id == commit.pattern_id)
        );
        assert!(!project.clips.iter().any(|clip| clip.id == commit.clip_id));

        let next = redo.pop().unwrap();
        undo.push(std::mem::replace(&mut project, next));
        assert!(
            project
                .patterns
                .iter()
                .any(|pattern| pattern.id == commit.pattern_id)
        );
        assert!(project.clips.iter().any(|clip| clip.id == commit.clip_id));
    }

    #[test]
    fn midi_take_history_preserves_a_pending_edit_and_none_touches_nothing() {
        let baseline = midi_recording_project();
        let mut project = baseline.clone();
        let mut history_snapshot = baseline.clone();
        let mut history_fingerprint = project_fingerprint(&baseline);
        project.name = "Pending ordinary edit".into();
        let target = resolve_midi_record_new_take_target(&project, 3, None, 1).unwrap();
        let target = bind_midi_record_new_take_start(target, 0.0).unwrap();
        let note = PianoNote {
            id: 0,
            channel_id: Some(1),
            group_id: None,
            note: 60,
            start: 0.0,
            length: 0.5,
            velocity: 1.0,
            selected: true,
            muted: false,
        };
        let candidate =
            build_new_pattern_midi_take(&project, target, std::slice::from_ref(&note), 0.5)
                .unwrap();
        let mut undo = Vec::new();
        let mut redo = Vec::new();
        let mut dirty = false;
        commit_midi_take_history_transaction(
            &mut project,
            &mut history_snapshot,
            &mut history_fingerprint,
            &mut undo,
            &mut redo,
            &mut dirty,
            Some(candidate),
        )
        .unwrap();
        assert_eq!(undo.len(), 2);
        let before_take = undo.pop().unwrap();
        assert_eq!(before_take.name, "Pending ordinary edit");
        assert_eq!(before_take.patterns.len(), baseline.patterns.len());
        let before_pending_edit = undo.pop().unwrap();
        assert_eq!(before_pending_edit.name, baseline.name);

        let project_before_none = project_fingerprint(&project);
        let snapshot_before_none = project_fingerprint(&history_snapshot);
        let fingerprint_before_none = history_fingerprint;
        let undo_before_none = undo.len();
        let redo_before_none = redo.len();
        dirty = false;
        let empty_take = build_new_pattern_midi_take(&project, target, &[], 0.5);
        assert!(empty_take.is_none());
        assert!(
            commit_midi_take_history_transaction(
                &mut project,
                &mut history_snapshot,
                &mut history_fingerprint,
                &mut undo,
                &mut redo,
                &mut dirty,
                empty_take,
            )
            .is_none()
        );
        assert!(!dirty);
        assert_eq!(project_fingerprint(&project), project_before_none);
        assert_eq!(project_fingerprint(&history_snapshot), snapshot_before_none);
        assert_eq!(history_fingerprint, fingerprint_before_none);
        assert_eq!(undo.len(), undo_before_none);
        assert_eq!(redo.len(), redo_before_none);
    }

    #[test]
    fn midi_record_after_stop_intents_only_reset_after_the_exact_terminal() {
        assert_eq!(
            MidiRecordAfterStop::ContinuePlayback.merge(MidiRecordAfterStop::PauseAtCurrent),
            MidiRecordAfterStop::PauseAtCurrent
        );
        assert_eq!(
            MidiRecordAfterStop::PauseAtCurrent.merge(MidiRecordAfterStop::StopAndResetZero),
            MidiRecordAfterStop::StopAndResetZero
        );
        assert!(MidiRecordAfterStop::StopAndResetZero.pauses_after_command());
        assert!(MidiRecordAfterStop::StopAndResetZero.resets_after_terminal());
        assert!(!MidiRecordAfterStop::PauseAtCurrent.resets_after_terminal());
        assert!(!MidiRecordAfterStop::ContinuePlayback.pauses_after_command());
    }

    #[test]
    fn midi_input_receipts_require_exact_route_and_connection_epoch() {
        assert_eq!(
            classify_midi_input_route_receipt(
                7,
                11,
                MidiInputRouteEvent::Installed {
                    route_id: 7,
                    connection_epoch: 11,
                    replaced_route_id: None,
                    success: true,
                },
            ),
            MidiInputReceiptDisposition::Installed {
                replaced_route_id: None
            }
        );
        assert_eq!(
            classify_midi_input_route_receipt(
                7,
                11,
                MidiInputRouteEvent::Installed {
                    route_id: 7,
                    connection_epoch: 10,
                    replaced_route_id: None,
                    success: true,
                },
            ),
            MidiInputReceiptDisposition::Stale
        );
        assert_eq!(
            classify_midi_input_route_receipt(
                7,
                11,
                MidiInputRouteEvent::Removed {
                    route_id: 7,
                    removed: false,
                },
            ),
            MidiInputReceiptDisposition::Removed { removed: false }
        );
        assert_eq!(
            classify_midi_input_route_receipt(
                7,
                11,
                MidiInputRouteEvent::Cleared {
                    request_id: 9,
                    removed_route_id: Some(7),
                },
            ),
            MidiInputReceiptDisposition::Cleared
        );
    }

