    fn saving_quit_lifecycle(operation_id: u64) -> ProjectLifecycle {
        let mut lifecycle = ProjectLifecycle::default();
        assert!(
            lifecycle
                .request(ProjectIntent::Quit, true, false)
                .is_none()
        );
        assert!(lifecycle.begin_save(operation_id));
        lifecycle
    }

    #[test]
    fn project_lifecycle_request_matrix_rechecks_dirty_after_barriers() {
        let mut clean = ProjectLifecycle::default();
        assert!(matches!(
            clean.request(ProjectIntent::Quit, false, false),
            Some(ProjectIntent::Quit)
        ));
        assert!(clean.is_idle());

        let mut dirty = ProjectLifecycle::default();
        assert!(dirty.request(ProjectIntent::Quit, true, false).is_none());
        assert!(matches!(
            &dirty,
            ProjectLifecycle::AwaitingDecision {
                intent,
                failure: None
            } if intent.kind() == ProjectIntentKind::Quit
        ));

        let mut after_barrier = ProjectLifecycle::default();
        assert!(
            after_barrier
                .request(ProjectIntent::Quit, true, true)
                .is_none()
        );
        after_barrier.mark_stop_requested();
        assert!(matches!(
            &after_barrier,
            ProjectLifecycle::WaitingForBarriers {
                stop_requested: true,
                ..
            }
        ));
        assert!(after_barrier.barriers_cleared(true).is_none());
        assert!(matches!(
            after_barrier,
            ProjectLifecycle::AwaitingDecision { .. }
        ));
    }

    #[test]
    fn project_lifecycle_save_receipt_is_exact_and_detects_snapshot_drift() {
        let mut lifecycle = saving_quit_lifecycle(41);
        let stale = ProjectSaveCompletion {
            operation_id: 40,
            fingerprint: 700,
            outcome: ProjectSaveOutcome::Clean,
        };
        assert!(lifecycle.complete_save(&stale, 700).is_none());
        assert!(matches!(
            lifecycle,
            ProjectLifecycle::Saving {
                operation_id: 41,
                ..
            }
        ));

        let drifted = ProjectSaveCompletion {
            operation_id: 41,
            fingerprint: 700,
            outcome: ProjectSaveOutcome::Clean,
        };
        assert!(lifecycle.complete_save(&drifted, 701).is_none());
        assert!(matches!(
            &lifecycle,
            ProjectLifecycle::AwaitingDecision {
                failure: Some(message),
                ..
            } if message.contains("changed after its save snapshot")
        ));
        assert!(lifecycle.begin_save(42));
        let clean = ProjectSaveCompletion {
            operation_id: 42,
            fingerprint: 701,
            outcome: ProjectSaveOutcome::Clean,
        };
        assert!(matches!(
            lifecycle.complete_save(&clean, 701),
            Some(ProjectIntent::Quit)
        ));
    }

    #[test]
    fn project_lifecycle_save_failures_return_to_retryable_decision() {
        let cases = [
            ProjectSaveOutcome::StalePluginState { count: 2 },
            ProjectSaveOutcome::TopologyTimeout("topology timeout".into()),
            ProjectSaveOutcome::IoFailed("disk full".into()),
        ];
        for (index, outcome) in cases.into_iter().enumerate() {
            let operation_id = 60 + index as u64;
            let mut lifecycle = saving_quit_lifecycle(operation_id);
            let completion = ProjectSaveCompletion {
                operation_id,
                fingerprint: 900,
                outcome,
            };
            assert!(lifecycle.complete_save(&completion, 900).is_none());
            assert!(matches!(
                lifecycle,
                ProjectLifecycle::AwaitingDecision {
                    failure: Some(_),
                    ..
                }
            ));
            assert!(lifecycle.begin_save(operation_id + 100));
        }
    }

    #[test]
    fn project_lifecycle_discard_cancel_and_critical_failure_are_explicit() {
        let mut decision = ProjectLifecycle::default();
        assert!(decision.request(ProjectIntent::Quit, true, false).is_none());
        assert!(matches!(decision.discard(), Some(ProjectIntent::Quit)));

        let mut waiting = ProjectLifecycle::default();
        assert!(waiting.request(ProjectIntent::Quit, true, true).is_none());
        assert!(waiting.fail_critical_io("capture failed".into()));
        assert!(matches!(waiting, ProjectLifecycle::CriticalIoFailed { .. }));
        assert!(waiting.continue_after_critical_io_failure(true).is_none());
        assert!(waiting.cancel());

        let mut saving = saving_quit_lifecycle(71);
        assert!(!saving.cancel());
        assert!(saving.discard().is_none());
    }

    #[test]
    fn project_lifecycle_exit_close_command_is_one_shot() {
        let mut lifecycle = ProjectLifecycle::default();
        assert!(!lifecycle.mark_close_command_sent());
        lifecycle.arm_exit();
        assert!(lifecycle.exit_is_armed());
        assert!(lifecycle.mark_close_command_sent());
        assert!(!lifecycle.mark_close_command_sent());
    }

    #[test]
    fn only_lifecycle_manual_save_carries_a_transition_identity() {
        let ordinary = ProjectSaveRequest::Manual {
            path: PathBuf::from("ordinary.citrus"),
            lifecycle: None,
        };
        let lifecycle = ProjectSaveRequest::Manual {
            path: PathBuf::from("transition.citrus"),
            lifecycle: Some(LifecycleSaveIdentity { operation_id: 9 }),
        };
        let autosave = ProjectSaveRequest::Autosave {
            path: PathBuf::from("recovery.citrus"),
            announce: false,
        };
        assert_eq!(ordinary.lifecycle_identity(), None);
        assert_eq!(
            lifecycle.lifecycle_identity(),
            Some(LifecycleSaveIdentity { operation_id: 9 })
        );
        assert_eq!(autosave.lifecycle_identity(), None);
    }

    #[test]
    fn recovery_path_identity_rejects_aliases_of_the_reserved_file() {
        let unique = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let directory = std::env::temp_dir().join(format!(
            "citrus-lifecycle-path-{}-{unique}",
            std::process::id()
        ));
        std::fs::create_dir_all(&directory).unwrap();
        let recovery = directory.join("recovery.citrus");
        std::fs::write(&recovery, b"recovery").unwrap();
        let alias = directory.join(".").join("recovery.citrus");
        assert!(paths_refer_to_same_file(&recovery, &alias));
        assert!(!paths_refer_to_same_file(
            &recovery,
            &directory.join("project.citrus")
        ));
        std::fs::remove_file(&recovery).unwrap();
        std::fs::remove_dir(&directory).unwrap();
    }

    #[test]
    fn pattern_transport_projection_is_isolated_and_never_mutates_the_project() {
        let mut project = Project::default();
        let mut second = project.patterns[0].clone();
        second.id = 77;
        second.name = "Pattern 77".into();
        second.notes[0].note = 41;
        project.patterns.push(second);
        project.active_pattern = 1;
        let before = project_fingerprint(&project);
        let original_clip_count = project.clips.len();
        let original_automation_count = project.automation_lanes.len();

        let playback = transport_playback_project(&project, TransportMode::Pattern);

        assert_eq!(project_fingerprint(&project), before);
        assert_eq!(project.clips.len(), original_clip_count);
        assert_eq!(project.automation_lanes.len(), original_automation_count);
        assert_eq!(playback.song_length_beats, LOOP_LENGTH);
        assert_eq!(playback.patterns.len(), 1);
        assert_eq!(playback.patterns[0].id, 77);
        assert_eq!(playback.active_pattern, 0);
        assert_eq!(playback.clips.len(), 1);
        assert_eq!(playback.clips[0].kind, ClipKind::Pattern);
        assert_eq!(playback.clips[0].pattern_id, 77);
        assert_eq!(playback.clips[0].start, 0.0);
        assert_eq!(playback.clips[0].length, LOOP_LENGTH);
        assert!(playback.automation_lanes.is_empty());
        assert!(playback.audio_assets.is_empty());
        assert!(playback.audio_clip_mixer_destinations.is_empty());
        assert_eq!(playback.channels.len(), project.channels.len());
        assert_eq!(playback.mixer_tracks.len(), project.mixer_tracks.len());
        assert_eq!(
            playback.plugin_instances.len(),
            project.plugin_instances.len()
        );

        let song = transport_playback_project(&project, TransportMode::Song);
        assert_eq!(project_fingerprint(&song), project_fingerprint(&project));
        assert_eq!(song.clips.len(), project.clips.len());
        assert_eq!(song.automation_lanes.len(), project.automation_lanes.len());
    }

    #[test]
    fn pattern_transport_projection_compiles_without_playlist_automation_or_audio() {
        let project = Project::default();
        assert!(!project.automation_lanes.is_empty());
        let playback = transport_playback_project(&project, TransportMode::Pattern);
        let options = transport_timeline_compile_options(&project, TransportMode::Pattern);
        let fingerprint = timeline_playback_fingerprint(&project, TransportMode::Pattern, 48_000);
        let timeline = compile_timeline_job(TimelineCompileJob {
            generation: 1,
            fingerprint,
            sample_rate: 48_000,
            project: playback,
            options,
        })
        .result
        .unwrap();

        assert!(!timeline.events().is_empty());
        assert!(timeline.audio_clips().is_empty());
        assert!(timeline.driven_automation_targets().is_empty());
        let expected = (48_000.0 * 60.0 / 128.0 * f64::from(LOOP_LENGTH)).round() as u64;
        assert_eq!(timeline.duration_frames(), expected);
    }

    #[test]
    fn pattern_transport_length_follows_steps_and_resized_piano_content_by_whole_bars() {
        let mut project = Project::blank();
        assert_eq!(pattern_playback_length_beats(&project), 4.0);
        let channel_id = project.channels[0].id;
        project.active_pattern_mut().notes.push(PianoNote {
            id: 1,
            channel_id: Some(channel_id),
            group_id: None,
            note: 60,
            start: 7.0,
            length: 2.0,
            velocity: 0.8,
            selected: false,
            muted: false,
        });
        assert_eq!(pattern_playback_length_beats(&project), 12.0);
        project.active_pattern_mut().notes[0].start = 17.0;
        project.active_pattern_mut().notes[0].length = 5.0;
        assert_eq!(pattern_playback_length_beats(&project), 24.0);
        assert_eq!(
            transport_loop_end_beat(&project, TransportMode::Pattern),
            24.0
        );
        assert_eq!(
            transport_playback_project(&project, TransportMode::Pattern).song_length_beats,
            24.0
        );
        assert_eq!(
            transport_timeline_compile_options(&project, TransportMode::Pattern)
                .legacy_piano_period_beats,
            24.0
        );
        assert_eq!(
            transport_timeline_compile_options(&project, TransportMode::Song)
                .legacy_piano_period_beats,
            f64::from(LOOP_LENGTH)
        );

        let fingerprint = timeline_playback_fingerprint(&project, TransportMode::Pattern, 48_000);
        let timeline = compile_timeline_job(TimelineCompileJob {
            generation: 1,
            fingerprint,
            sample_rate: 48_000,
            project: transport_playback_project(&project, TransportMode::Pattern),
            options: transport_timeline_compile_options(&project, TransportMode::Pattern),
        })
        .result
        .unwrap();
        let expected_start = (48_000.0_f64 * 60.0 / 128.0 * 17.0).round() as u64;
        assert!(timeline.events().iter().any(|event| {
            event.frame == expected_start
                && matches!(
                    event.kind,
                    crate::timeline::TimelineEventKind::NoteOn { note: 60, .. }
                )
        }));

        project.song_length_beats = 24.0;
        let pattern_id = project.active_pattern().id;
        project.clips = vec![Clip {
            id: 1,
            track: 0,
            start: 0.0,
            length: 24.0,
            name: "Extended score".into(),
            color: [255, 142, 82],
            kind: ClipKind::Pattern,
            group_id: None,
            pattern_id,
            automation_id: None,
            audio_asset_id: None,
            source_offset: 0.0,
            audio_source_offset_frame: None,
            audio_source_reference: None,
            audio_length_reference: None,
            fade_in_reference: None,
            fade_out_reference: None,
            gain: 1.0,
            fade_in: 0.0,
            fade_out: 0.0,
            muted: false,
        }];
        let song_timeline = compile_timeline_job(TimelineCompileJob {
            generation: 2,
            fingerprint: timeline_compile_fingerprint(&project, 48_000),
            sample_rate: 48_000,
            project,
            options: TimelineCompileOptions::default(),
        })
        .result
        .unwrap();
        assert!(song_timeline.events().iter().any(|event| {
            event.frame == expected_start
                && matches!(
                    event.kind,
                    crate::timeline::TimelineEventKind::NoteOn { note: 60, .. }
                )
        }));
    }

    #[test]
    fn transport_fingerprints_track_mode_and_active_pattern_without_song_false_positives() {
        let mut project = Project::default();
        let mut second = project.patterns[0].clone();
        second.id = 88;
        second.name = "Pattern 88".into();
        project.patterns.push(second);

        let song_before = timeline_playback_fingerprint(&project, TransportMode::Song, 48_000);
        let pattern_before =
            timeline_playback_fingerprint(&project, TransportMode::Pattern, 48_000);
        assert_ne!(song_before, pattern_before);
        project.active_pattern = 1;
        assert_eq!(
            timeline_playback_fingerprint(&project, TransportMode::Song, 48_000),
            song_before
        );
        assert_ne!(
            timeline_playback_fingerprint(&project, TransportMode::Pattern, 48_000),
            pattern_before
        );

        let pattern_tempo = transport_tempo_map_fingerprint(&project, TransportMode::Pattern);
        project.song_length_beats += 32.0;
        assert_eq!(
            transport_tempo_map_fingerprint(&project, TransportMode::Pattern),
            pattern_tempo
        );
        project.tempo += 1.0;
        assert_ne!(
            transport_tempo_map_fingerprint(&project, TransportMode::Pattern),
            pattern_tempo
        );
    }

