    #[test]
    fn every_modal_disables_globals_and_owns_plain_escape() {
        for modal in [
            ShortcutModal::ProjectMedia,
            ShortcutModal::ProjectLifecycle,
            ShortcutModal::PianoTransform,
            ShortcutModal::PluginManager,
            ShortcutModal::Settings,
            ShortcutModal::MidiImport,
            ShortcutModal::MidiExport,
            ShortcutModal::WavExport,
            ShortcutModal::Recovery,
        ] {
            let policy = ShortcutPolicy::new(ShortcutContext {
                blocking_layer: true,
                top_modal: Some(modal),
                ..ShortcutContext::default()
            });
            for global in [
                shortcut_chord(ShortcutKey::Space, false, false, false),
                shortcut_chord(ShortcutKey::Num4, false, false, false),
                shortcut_chord(ShortcutKey::F5, false, false, false),
                shortcut_chord(ShortcutKey::Delete, false, false, false),
                shortcut_chord(ShortcutKey::S, true, false, false),
                shortcut_chord(ShortcutKey::O, true, false, false),
                shortcut_chord(ShortcutKey::N, true, false, false),
                shortcut_chord(ShortcutKey::Z, true, false, false),
            ] {
                assert_eq!(policy.resolve(global), None, "modal {modal:?}");
            }
            assert_eq!(
                policy.resolve(shortcut_chord(ShortcutKey::Escape, false, false, false)),
                Some(ShortcutAction::DismissModal(modal))
            );
        }
    }

