    #[test]
    fn shortcut_modifiers_distinguish_plain_command_shift_and_alt() {
        let policy = ShortcutPolicy::new(ShortcutContext::default());
        assert_eq!(
            policy.resolve(shortcut_chord(ShortcutKey::S, true, false, false)),
            Some(ShortcutAction::Save)
        );
        assert_eq!(
            policy.resolve(shortcut_chord(ShortcutKey::Z, true, true, false)),
            Some(ShortcutAction::Redo)
        );
        assert_eq!(
            policy.resolve(shortcut_chord(ShortcutKey::Y, true, false, false)),
            Some(ShortcutAction::Redo)
        );
        assert_eq!(
            policy.resolve(shortcut_chord(ShortcutKey::N, true, false, false)),
            Some(ShortcutAction::NewProject)
        );
        assert_eq!(
            policy.resolve(shortcut_chord(ShortcutKey::L, true, false, false)),
            Some(ShortcutAction::QuickLegato)
        );
        assert_eq!(
            policy.resolve(shortcut_chord(ShortcutKey::L, false, false, false)),
            Some(ShortcutAction::ToggleTransportMode)
        );
        assert_eq!(
            policy.resolve(shortcut_chord(ShortcutKey::L, false, false, true)),
            Some(ShortcutAction::PianoTransform(
                PianoRollTransformKind::Articulate
            ))
        );
        assert_eq!(
            policy.resolve(shortcut_chord(ShortcutKey::A, false, false, true)),
            Some(ShortcutAction::PianoTransform(
                PianoRollTransformKind::Arpeggiate
            ))
        );
        assert_eq!(
            policy.resolve(shortcut_chord(ShortcutKey::Q, false, false, true)),
            Some(ShortcutAction::PianoTransform(
                PianoRollTransformKind::Quantize
            ))
        );
        assert_eq!(
            policy.resolve(shortcut_chord(ShortcutKey::S, false, false, true)),
            Some(ShortcutAction::PianoTransform(
                PianoRollTransformKind::Strum
            ))
        );
        assert_eq!(
            policy.resolve(shortcut_chord(ShortcutKey::U, false, false, true)),
            Some(ShortcutAction::PianoTransform(PianoRollTransformKind::Chop))
        );
        assert_eq!(
            policy.resolve(shortcut_chord(ShortcutKey::F, false, false, true)),
            Some(ShortcutAction::PianoTransform(PianoRollTransformKind::Flam))
        );
        assert_eq!(
            policy.resolve(shortcut_chord(ShortcutKey::G, false, true, false)),
            Some(ShortcutAction::GroupPianoNotes)
        );
        assert_eq!(
            policy.resolve(shortcut_chord(ShortcutKey::G, false, false, true)),
            Some(ShortcutAction::UngroupPianoNotes)
        );
        assert_eq!(
            policy.resolve(shortcut_chord(ShortcutKey::S, false, false, false)),
            Some(ShortcutAction::Tool(ToolMode::Slip))
        );
        let windows_control = ShortcutModifiers::from_egui(egui::Modifiers {
            ctrl: true,
            command: true,
            ..egui::Modifiers::default()
        });
        assert!(windows_control.is_command_only());
        let mac_control = ShortcutModifiers::from_egui(egui::Modifiers {
            ctrl: true,
            command: false,
            ..egui::Modifiers::default()
        });
        assert!(!mac_control.is_plain());
        for chord in [
            shortcut_chord(ShortcutKey::S, true, false, true),
            shortcut_chord(ShortcutKey::Num1, true, false, false),
            shortcut_chord(ShortcutKey::Delete, false, true, false),
            shortcut_chord(ShortcutKey::F5, false, false, true),
            ShortcutChord {
                key: ShortcutKey::Space,
                modifiers: ShortcutModifiers {
                    non_command_control: true,
                    ..ShortcutModifiers::default()
                },
            },
        ] {
            assert_eq!(policy.resolve(chord), None);
        }
    }

    #[test]
    fn simultaneous_shortcuts_commit_one_action_by_explicit_priority() {
        let policy = ShortcutPolicy::new(ShortcutContext::default());
        let mut presses = ShortcutPresses::default();
        presses.insert(shortcut_chord(ShortcutKey::Space, false, false, false));
        presses.insert(shortcut_chord(ShortcutKey::O, true, false, false));
        assert_eq!(policy.resolve_presses(presses), Some(ShortcutAction::Open));

        presses.insert(shortcut_chord(ShortcutKey::S, true, false, false));
        assert_eq!(policy.resolve_presses(presses), Some(ShortcutAction::Save));

        let modal = ShortcutModal::MidiExport;
        let modal_policy = ShortcutPolicy::new(ShortcutContext {
            top_modal: Some(modal),
            ..ShortcutContext::default()
        });
        presses.insert(shortcut_chord(ShortcutKey::Escape, false, false, false));
        assert_eq!(
            modal_policy.resolve_presses(presses),
            Some(ShortcutAction::DismissModal(modal))
        );
    }

    #[test]
    fn playlist_viewport_round_trips_track_31_and_far_song_edits() {
        let mut viewport = default_playlist_viewport(4_096.0);
        viewport.y.set_viewport_pixels(280.0).unwrap();
        viewport.x.set_viewport_pixels(900.0).unwrap();
        viewport.y.set_normalized_scroll(1.0).unwrap();
        viewport.x.set_normalized_scroll(1.0).unwrap();

        assert!(content_span_is_visible(viewport.y, 31.0, 32.0));
        let track_pixel = viewport.y.pixel_for_content(31.5);
        assert!((0.0..viewport.y.viewport_pixels()).contains(&track_pixel));
        assert_eq!(playlist_track_at_pixel(viewport.y, track_pixel), Some(31));

        let far_beat = 4_095.5;
        assert!(content_span_is_visible(viewport.x, 4_095.0, 4_096.0));
        let beat_pixel = viewport.x.pixel_for_content(far_beat);
        assert!((0.0..viewport.x.viewport_pixels()).contains(&beat_pixel));
        assert!((viewport.x.content_at_pixel(beat_pixel) - far_beat).abs() < 1.0e-9);
    }

