    #[test]
    fn editor_wheel_zoom_keeps_anchor_stable_at_common_dpi_scales() {
        for dpi in [1.0_f32, 1.25, 1.5, 2.0] {
            let mut viewport = default_playlist_viewport(4_096.0);
            let width = 900.0 * dpi;
            let height = 500.0 * dpi;
            viewport.x.set_viewport_pixels(f64::from(width)).unwrap();
            viewport.y.set_viewport_pixels(f64::from(height)).unwrap();
            viewport
                .x
                .scroll_by_pixels(f64::from(2_500.0 * dpi))
                .unwrap();
            let anchor = 337.0 * dpi;
            let before = viewport.x.content_at_pixel(f64::from(anchor));
            let canvas = Rect::from_min_size(Pos2::ZERO, Vec2::new(width, height));
            let modifiers = egui::Modifiers {
                ctrl: true,
                ..egui::Modifiers::default()
            };
            apply_editor_wheel(
                &mut viewport,
                canvas,
                Some(Pos2::new(anchor, height * 0.5)),
                Vec2::new(0.0, -120.0),
                modifiers,
            );
            let after = viewport.x.content_at_pixel(f64::from(anchor));
            let pixel_error = (after - before).abs() * viewport.x.pixels_per_unit();
            assert!(pixel_error < 0.5, "dpi {dpi}: {pixel_error} logical px");
        }
    }

