    #[test]
    fn midi_export_mapping_is_stable_and_enforces_sixteen_channel_limit() {
        let mut project = Project::default();
        let first = project.channels[0].id;
        let third = project.channels[2].id;
        project.active_pattern_mut().notes =
            vec![routed_note(1, Some(third)), routed_note(2, Some(first))];
        let channel_ids = active_pattern_midi_export_channels(&project).unwrap();
        assert_eq!(channel_ids, vec![first, third]);
        let rows = channel_ids
            .iter()
            .copied()
            .enumerate()
            .map(|(index, project_channel_id)| MidiExportRouteRow {
                project_channel_id,
                midi_channel: index as u8,
            })
            .collect::<Vec<_>>();
        let routing = build_midi_export_channel_map(&rows, &project.channels).unwrap();
        assert_eq!(routing.midi_channel(first), Some(0));
        assert_eq!(routing.midi_channel(third), Some(1));

        let mut duplicate_midi = rows.clone();
        duplicate_midi[1].midi_channel = 0;
        assert!(
            build_midi_export_channel_map(&duplicate_midi, &project.channels)
                .unwrap_err()
                .contains("assigned more than once")
        );

        let template = project.channels[0].clone();
        project.channels = (1..=17_u32)
            .map(|id| {
                let mut channel = template.clone();
                channel.id = id;
                channel.name = format!("Channel {id}");
                channel
            })
            .collect();
        project.active_pattern_mut().notes = (1..=17_u32)
            .map(|channel_id| routed_note(u64::from(channel_id), Some(channel_id)))
            .collect();
        assert_eq!(
            active_pattern_midi_export_channels(&project),
            Err(MidiExportRoutingIssue::TooManyChannels(17))
        );
    }

    #[test]
    fn timeline_fingerprint_tracks_compiler_inputs_but_ignores_ui_state_and_peaks() {
        let mut project = Project::default();
        project
            .active_pattern_mut()
            .notes
            .push(routed_note(900, Some(1)));
        project.audio_assets.push(audio_asset());
        let mut lane = AutomationLane::new(AutomationTarget::MasterPan);
        lane.replace_points([AutomationPoint::new(0.0, 0.0)]);
        project.automation_lanes.push(ProjectAutomation {
            id: 901,
            name: "Fingerprint".into(),
            lane,
        });
        let baseline = timeline_compile_fingerprint(&project, 48_000);

        project.active_pattern_mut().notes[0].selected = true;
        project.mixer_tracks[0].peak = 0.99;
        project.audio_assets[0].waveform_peaks = vec![0.1, 0.9];
        assert_eq!(timeline_compile_fingerprint(&project, 48_000), baseline);
        assert_ne!(timeline_compile_fingerprint(&project, 44_100), baseline);

        let mut changed = project.clone();
        changed.active_pattern_mut().notes[0].id += 1;
        assert_ne!(timeline_compile_fingerprint(&changed, 48_000), baseline);
        let mut changed = project.clone();
        changed.active_pattern_mut().notes[0].channel_id = Some(2);
        assert_ne!(timeline_compile_fingerprint(&changed, 48_000), baseline);
        let mut changed = project.clone();
        changed.clips[0].audio_source_offset_frame = Some(17);
        assert_ne!(timeline_compile_fingerprint(&changed, 48_000), baseline);
        let mut changed = project.clone();
        changed
            .automation_lanes
            .last_mut()
            .unwrap()
            .lane
            .set_curve(AutomationCurve::Hold);
        assert_ne!(timeline_compile_fingerprint(&changed, 48_000), baseline);
        let mut changed = project.clone();
        changed.audio_assets[0].frames += 1;
        assert_ne!(timeline_compile_fingerprint(&changed, 48_000), baseline);
        let mut changed = project.clone();
        let descriptor = plugin_descriptor(
            ScannedPluginFormat::Vst3,
            "timeline.target",
            "Timeline Target",
            r"C:\VST3\Timeline.vst3",
        );
        commit_loaded_plugin(
            &mut changed,
            PluginPickerTarget::MixerSlot { track: 1, slot: 0 },
            &descriptor,
        )
        .unwrap();
        assert_ne!(timeline_compile_fingerprint(&changed, 48_000), baseline);
    }

    #[test]
    fn timeline_worker_result_rejects_stale_generation_fingerprint_and_rate() {
        let project = Project::default();
        let fingerprint = timeline_compile_fingerprint(&project, 48_000);
        let result = compile_timeline_job(TimelineCompileJob {
            generation: 7,
            fingerprint,
            sample_rate: 48_000,
            project,
            options: TimelineCompileOptions::default(),
        });
        assert!(timeline_result_is_current(&result, 7, fingerprint, 48_000));
        assert!(!timeline_result_is_current(&result, 8, fingerprint, 48_000));
        assert!(!timeline_result_is_current(
            &result,
            7,
            fingerprint.wrapping_add(1),
            48_000
        ));
        assert!(!timeline_result_is_current(&result, 7, fingerprint, 44_100));
    }

    #[test]
    fn timeline_default_v7_compiles_cleanly_and_work_limit_error_is_visible() {
        let project = Project::default();
        let fingerprint = timeline_compile_fingerprint(&project, 48_000);
        let compiled = compile_timeline_job(TimelineCompileJob {
            generation: 1,
            fingerprint,
            sample_rate: 48_000,
            project: project.clone(),
            options: TimelineCompileOptions::default(),
        })
        .result
        .unwrap();
        assert!(compiled.diagnostics().is_empty());

        let error = compile_timeline_job(TimelineCompileJob {
            generation: 2,
            fingerprint,
            sample_rate: 48_000,
            project,
            options: TimelineCompileOptions {
                max_work_units: 1,
                ..TimelineCompileOptions::default()
            },
        })
        .result
        .unwrap_err();
        assert!(error.contains("deterministic 1-unit work budget"));
    }

    #[test]
    fn tempo_map_fingerprint_ignores_notes_but_tracks_clock_inputs() {
        let mut project = Project::default();
        let initial = tempo_map_fingerprint(&project);
        project.channels[0].volume = 0.123;
        assert_eq!(tempo_map_fingerprint(&project), initial);

        project.tempo += 1.0;
        let changed_tempo = tempo_map_fingerprint(&project);
        assert_ne!(changed_tempo, initial);

        let mut lane = AutomationLane::new(AutomationTarget::Tempo);
        lane.replace_points([AutomationPoint::new(0.0, 100.0)]);
        project.automation_lanes.push(ProjectAutomation {
            id: 700,
            name: "Tempo".into(),
            lane,
        });
        let changed_lane = tempo_map_fingerprint(&project);
        assert_ne!(changed_lane, changed_tempo);

        project.clips.push(Clip {
            id: 701,
            track: 5,
            start: 1.0,
            length: 2.0,
            name: "Tempo placement".into(),
            color: [1, 2, 3],
            kind: ClipKind::Automation,
            group_id: None,
            pattern_id: 1,
            automation_id: Some(700),
            audio_asset_id: None,
            source_offset: 0.0,
            audio_source_offset_frame: None,
            audio_source_reference: None,
            audio_length_reference: None,
            fade_in_reference: None,
            fade_out_reference: None,
            gain: 1.0,
            fade_in: 0.0,
            fade_out: 0.0,
            muted: false,
        });
        let placed = tempo_map_fingerprint(&project);
        assert_ne!(placed, changed_lane);
        project.clips.last_mut().unwrap().source_offset = 0.5;
        assert_ne!(tempo_map_fingerprint(&project), placed);
    }

