    #[test]
    fn legacy_mixer_zero_volume_and_pan_emit_master_commands() {
        let project = Project::default();
        match legacy_mixer_automation_audio_command(
            &project,
            &AutomationTarget::MixerVolume {
                track: crate::mixer_graph::MASTER_MIXER_TRACK_ID,
            },
            0.37,
        ) {
            Some(AudioCommand::SetMaster(value)) => assert_eq!(value, 0.37),
            _ => panic!("mixer-zero volume must address the master gain command"),
        }
        match legacy_mixer_automation_audio_command(
            &project,
            &AutomationTarget::MixerPan {
                track: crate::mixer_graph::MASTER_MIXER_TRACK_ID,
            },
            -0.25,
        ) {
            Some(AudioCommand::SetMasterPan(value)) => assert_eq!(value, -0.25),
            _ => panic!("mixer-zero pan must address the master pan command"),
        }
        match legacy_mixer_automation_audio_command(
            &project,
            &AutomationTarget::MixerMute {
                track: crate::mixer_graph::MASTER_MIXER_TRACK_ID,
            },
            1.0,
        ) {
            Some(AudioCommand::SetTrackMuted { track: 0, muted }) => assert!(muted),
            _ => panic!("mixer-zero mute intentionally remains a track mute command"),
        }
        match legacy_mixer_automation_audio_command(
            &project,
            &AutomationTarget::MixerVolume { track: 1 },
            0.5,
        ) {
            Some(AudioCommand::SetTrackGain { track: 1, gain }) => assert_eq!(gain, 0.5),
            _ => panic!("non-master mixer volume must remain a track command"),
        }
    }

    #[test]
    fn callback_native_channel_automation_blocks_legacy_double_dispatch_and_replacement_leaks() {
        fn compiled_channel_pan_timeline(generator: bool) -> (Project, CompiledTimeline) {
            let mut project = Project {
                song_length_beats: 8.0,
                ..Project::default()
            };
            let channel_id = project.channels[0].id;
            let mut lane = AutomationLane::new(AutomationTarget::ChannelPan {
                channel: channel_id,
            });
            lane.replace_points([
                AutomationPoint::new(0.0, -0.5),
                AutomationPoint::new(4.0, 0.5),
            ]);
            project.automation_lanes.push(ProjectAutomation {
                id: 9_001,
                name: "Channel pan".into(),
                lane,
            });
            let mixer_track = project.channels[0].mixer_track;
            let mut mixer_lane =
                AutomationLane::new(AutomationTarget::MixerPan { track: mixer_track });
            mixer_lane.replace_points([AutomationPoint::new(0.0, 0.25)]);
            project.automation_lanes.push(ProjectAutomation {
                id: 9_002,
                name: "Mixer pan".into(),
                lane: mixer_lane,
            });
            if generator {
                let mut descriptor = plugin_descriptor(
                    ScannedPluginFormat::Vst3,
                    "generator.identity",
                    "Generator",
                    r"C:\VST3\Generator.vst3",
                );
                descriptor.is_instrument = true;
                commit_loaded_plugin(
                    &mut project,
                    PluginPickerTarget::ChannelDevice { channel: 0 },
                    &descriptor,
                )
                .unwrap();
            }
            let map = TempoMap::from_project(&project, 48_000).unwrap();
            let timeline =
                CompiledTimeline::from_project(&project, &map, TimelineCompileOptions::default())
                    .unwrap();
            (project, timeline)
        }

        let (project, native) = compiled_channel_pan_timeline(false);
        let channel_id = project.channels[0].id;
        let channel_pan = AutomationTarget::ChannelPan {
            channel: channel_id,
        };
        assert!(timeline_drives_native_channel_automation(
            &native,
            &channel_pan
        ));
        assert!(!should_dispatch_legacy_automation(
            true,
            Some(&native),
            &channel_pan
        ));
        assert!(should_dispatch_legacy_automation(
            true,
            Some(&native),
            &AutomationTarget::MasterPan
        ));
        let release = native_channel_pan_release(&project, &native, 0.0);
        assert_eq!(
            release.pan_for_track(
                project
                    .mixer_runtime_slot(project.channels[0].mixer_track)
                    .unwrap()
            ),
            Some(0.25)
        );

        // While candidate B is being prepared, the callback still owns A.
        // B's UI-rate controls must not mutate that previous revision.
        assert!(!should_dispatch_legacy_automation(
            true,
            None,
            &AutomationTarget::MasterPan
        ));
        assert!(should_dispatch_legacy_automation(
            false,
            None,
            &AutomationTarget::MasterPan
        ));

        let (_, generator) = compiled_channel_pan_timeline(true);
        assert!(!timeline_drives_native_channel_automation(
            &generator,
            &channel_pan
        ));
        assert!(should_dispatch_legacy_automation(
            true,
            Some(&generator),
            &channel_pan
        ));
    }

    #[test]
    fn legacy_runtime_canonicalizes_mixer_zero_before_project_order_resolution() {
        let mut project = Project::default();
        project.automation_lanes.clear();
        project.clips.clear();

        let mut earlier = AutomationLane::new(AutomationTarget::MasterVolume);
        earlier.replace_points([AutomationPoint::new(0.0, 0.2)]);
        let mut later = AutomationLane::new(AutomationTarget::MixerVolume {
            track: crate::mixer_graph::MASTER_MIXER_TRACK_ID,
        });
        later.replace_points([AutomationPoint::new(0.0, 0.8)]);
        project.automation_lanes.extend([
            ProjectAutomation {
                id: 1,
                name: "Earlier master spelling".into(),
                lane: earlier,
            },
            ProjectAutomation {
                id: 2,
                name: "Later mixer-zero spelling".into(),
                lane: later,
            },
        ]);

        let active = automation_runtime_lanes_at_beat(&project, 0.0);
        assert!(
            active
                .iter()
                .all(|automation| { automation.lane.target() == &AutomationTarget::MasterVolume })
        );
        let frame = automation_runtime::AutomationRuntimeFrame::evaluate(&active, 0.0);
        assert_eq!(frame.master.volume, Some(0.8));
        assert_eq!(
            frame.value_for(&AutomationTarget::MixerVolume {
                track: crate::mixer_graph::MASTER_MIXER_TRACK_ID,
            }),
            None
        );
        assert_eq!(
            project.automation_lanes[1].lane.target(),
            &AutomationTarget::MixerVolume {
                track: crate::mixer_graph::MASTER_MIXER_TRACK_ID,
            }
        );

        // Reverse the spellings while keeping the later project entry the
        // winner; enum dispatch order must never override project precedence.
        project.automation_lanes[0]
            .lane
            .set_target(AutomationTarget::MixerVolume {
                track: crate::mixer_graph::MASTER_MIXER_TRACK_ID,
            });
        project.automation_lanes[1]
            .lane
            .set_target(AutomationTarget::MasterVolume);
        let active = automation_runtime_lanes_at_beat(&project, 0.0);
        let frame = automation_runtime::AutomationRuntimeFrame::evaluate(&active, 0.0);
        assert_eq!(frame.master.volume, Some(0.8));
    }

