    #[test]
    fn same_id_readd_waits_for_unregister_ack_then_registers_prepared_pcm() {
        let unregister = AudioAssetOperation {
            engine_session: 5,
            generation: 8,
            operation_id: 20,
        };
        let register = AudioAssetOperation {
            operation_id: 21,
            ..unregister
        };
        let replacement = PreparedAudioAssetRegistration {
            generation: 8,
            project_asset_id: 7,
            samples: Arc::from([0.75_f32]),
            sample_rate: 48_000,
            channels: 1,
        };
        let mut prepared = HashMap::from([(7, replacement)]);
        let mut pending = HashMap::new();
        let mut pending_unregistrations = HashMap::from([(
            7,
            PendingAudioAssetUnregistration {
                operation: unregister,
            },
        )]);
        let mut pending_clear = None;
        let mut resident = HashMap::from([(7, 7)]);
        assert_eq!(
            required_audio_asset_state(
                [7],
                &resident,
                &pending_unregistrations,
                &HashMap::new(),
                8,
                false,
            ),
            RequiredAudioAssetState::Loading(7)
        );
        assert_eq!(
            apply_audio_asset_event_to_residency(
                AudioAssetEvent::Unregistered {
                    operation: unregister,
                    id: 7,
                    removed: true,
                },
                5,
                8,
                &mut prepared,
                &mut pending,
                &mut pending_unregistrations,
                &mut pending_clear,
                &mut resident,
            ),
            AppliedAudioAssetEvent::Unregistered
        );
        let replacement = prepared.remove(&7).unwrap();
        pending.insert(
            7,
            PendingAudioAssetRegistration {
                operation: register,
                prepared: replacement,
            },
        );
        assert_eq!(
            apply_audio_asset_event_to_residency(
                AudioAssetEvent::Registered {
                    operation: register,
                    id: 7,
                    success: true,
                },
                5,
                8,
                &mut prepared,
                &mut pending,
                &mut pending_unregistrations,
                &mut pending_clear,
                &mut resident,
            ),
            AppliedAudioAssetEvent::Registered {
                project_asset_id: 7
            }
        );
        assert_eq!(resident.get(&7), Some(&7));
    }

    #[test]
    fn clear_confirmation_requires_a_queued_current_barrier() {
        let operation = AudioAssetOperation {
            engine_session: 8,
            generation: 13,
            operation_id: 21,
        };
        let mut prepared = HashMap::new();
        let mut pending = HashMap::new();
        let mut pending_unregistrations = HashMap::new();
        let mut pending_clear = Some(PendingAudioAssetClear {
            operation,
            queued: false,
        });
        let mut resident = HashMap::from([(7, 7)]);
        let event = AudioAssetEvent::Cleared {
            operation,
            removed: 1,
        };
        assert_eq!(
            apply_audio_asset_event_to_residency(
                event,
                8,
                13,
                &mut prepared,
                &mut pending,
                &mut pending_unregistrations,
                &mut pending_clear,
                &mut resident,
            ),
            AppliedAudioAssetEvent::Ignored
        );
        assert_eq!(resident.get(&7), Some(&7));
        pending_clear.as_mut().unwrap().queued = true;
        assert_eq!(
            apply_audio_asset_event_to_residency(
                event,
                8,
                13,
                &mut prepared,
                &mut pending,
                &mut pending_unregistrations,
                &mut pending_clear,
                &mut resident,
            ),
            AppliedAudioAssetEvent::Cleared
        );
        assert!(resident.is_empty());
        assert!(pending_clear.is_none());
    }

