    #[test]
    fn active_seek_prepare_failure_waits_for_clear_before_legacy_fallback() {
        let mut sync = TimelineAudioSyncState::new(true);
        sync.accept_source(30, false);
        sync.phase = TimelineAudioSyncPhase::Active {
            generation: 30,
            epoch: 9,
        };
        let mut transport_loop_dirty = true;

        begin_timeline_fault_handoff(
            &mut sync,
            &mut transport_loop_dirty,
            Some(30),
            true,
            "Unable to prepare seek chase: invalid chase".into(),
        );

        assert_eq!(
            sync.phase,
            TimelineAudioSyncPhase::FaultClearReady { revision: 30 }
        );
        assert!(sync.retain_callback_ownership);
        assert!(!transport_loop_dirty);
        let playlist_seek = sync.request_seek(6.0, 144_000);
        assert_eq!(playlist_seek.beat, 6.0);
        assert_eq!(
            sync.phase,
            TimelineAudioSyncPhase::FaultClearReady { revision: 30 }
        );
        sync.queue_fault_clear(30, 700);
        assert_eq!(
            confirm_timeline_asset_clear(&mut sync, &mut transport_loop_dirty, 700, 30,),
            Some(6.0)
        );
        assert_eq!(sync.phase, TimelineAudioSyncPhase::Faulted);
        assert!(!sync.retain_callback_ownership);
        assert!(transport_loop_dirty);
    }

    #[test]
