    #[test]
    fn mixer_runtime_specs_compact_sparse_slots_in_physical_order() {
        let mut project = Project::default();
        let late = plugin_descriptor(
            ScannedPluginFormat::Vst3,
            "late",
            "Late",
            r"C:\VST3\Late.vst3",
        );
        let early = plugin_descriptor(
            ScannedPluginFormat::Vst2,
            "early",
            "Early",
            r"C:\VST\Early.dll",
        );
        let late_id = commit_loaded_plugin(
            &mut project,
            PluginPickerTarget::MixerSlot { track: 5, slot: 8 },
            &late,
        )
        .unwrap();
        let early_id = commit_loaded_plugin(
            &mut project,
            PluginPickerTarget::MixerSlot { track: 5, slot: 2 },
            &early,
        )
        .unwrap();
        let late_instance = project
            .plugin_instances
            .iter_mut()
            .find(|instance| instance.id == late_id)
            .unwrap();
        late_instance.enabled = false;
        late_instance.bypass = true;
        late_instance.wet = 0.25;
        late_instance.opaque_state = vec![1, 2, 3];

        let (ids, specs) = mixer_track_runtime_specs(&project, 5).unwrap();
        assert_eq!(ids, vec![early_id, late_id]);
        assert_eq!(runtime_slot_for_instance(&ids, early_id), Some(0));
        assert_eq!(runtime_slot_for_instance(&ids, late_id), Some(1));
        assert_eq!(runtime_slot_for_instance(&ids, u64::MAX), None);
        assert_eq!(specs[0].descriptor.id, "early");
        assert_eq!(specs[1].descriptor.id, "late");
        assert!(!specs[1].enabled);
        assert!(specs[1].bypassed);
        assert_eq!(specs[1].wet, 0.25);
        assert_eq!(specs[1].initial_state, vec![1, 2, 3]);
    }

    #[test]
    fn plugin_runtime_events_update_the_compact_slot_instance() {
        let mut project = Project::default();
        let first_id = commit_loaded_plugin(
            &mut project,
            PluginPickerTarget::MixerSlot { track: 1, slot: 1 },
            &plugin_descriptor(
                ScannedPluginFormat::Vst3,
                "first",
                "First",
                r"C:\VST3\First.vst3",
            ),
        )
        .unwrap();
        let second_id = commit_loaded_plugin(
            &mut project,
            PluginPickerTarget::MixerSlot { track: 1, slot: 9 },
            &plugin_descriptor(
                ScannedPluginFormat::Vst2,
                "second",
                "Second",
                r"C:\VST\Second.dll",
            ),
        )
        .unwrap();
        let ids = vec![first_id, second_id];

        assert!(
            apply_plugin_runtime_event(
                &mut project,
                &ids,
                &RuntimeEvent::SlotReady {
                    slot: 0,
                    name: "First".into(),
                    latency_samples: 64,
                    tail_samples: 0,
                },
            )
            .is_none()
        );
        assert_eq!(
            project
                .plugin_instances
                .iter()
                .find(|instance| instance.id == first_id)
                .unwrap()
                .runtime_status,
            PluginRuntimeStatus::Loaded
        );

        apply_plugin_runtime_event(
            &mut project,
            &ids,
            &RuntimeEvent::ParameterValue {
                slot: 0,
                request_id: 0,
                id: 7,
                value: 1.4,
            },
        );
        apply_plugin_runtime_event(
            &mut project,
            &ids,
            &RuntimeEvent::State {
                slot: 0,
                request_id: 0,
                bytes: vec![4, 5, 6],
            },
        );
        let first = project
            .plugin_instances
            .iter()
            .find(|instance| instance.id == first_id)
            .unwrap();
        assert_eq!(first.parameters.get(&7), None);
        assert_eq!(first.opaque_state, vec![4, 5, 6]);

        let message = apply_plugin_runtime_event(
            &mut project,
            &ids,
            &RuntimeEvent::SlotFault {
                slot: 1,
                message: "backend stopped".into(),
            },
        )
        .unwrap();
        assert!(message.contains("Second"));
        assert_eq!(
            project
                .plugin_instances
                .iter()
                .find(|instance| instance.id == second_id)
                .unwrap()
                .runtime_status,
            PluginRuntimeStatus::Crashed
        );
        assert!(
            apply_plugin_runtime_event(
                &mut project,
                &ids,
                &RuntimeEvent::State {
                    slot: ids.len(),
                    request_id: 0,
                    bytes: vec![9],
                },
            )
            .is_none()
        );
    }

    #[test]
    fn stale_project_session_events_cannot_mutate_a_reused_plugin_instance_id() {
        let mut project = Project::default();
        let instance_id = commit_loaded_plugin(
            &mut project,
            PluginPickerTarget::MixerSlot { track: 1, slot: 0 },
            &plugin_descriptor(
                ScannedPluginFormat::Vst3,
                "reused",
                "New Session Instance",
                r"C:\VST3\Reused.vst3",
            ),
        )
        .unwrap();
        let instance = project
            .plugin_instances
            .iter_mut()
            .find(|instance| instance.id == instance_id)
            .unwrap();
        instance.runtime_status = PluginRuntimeStatus::Unloaded;
        instance.parameters.insert(7, 0.25);
        instance.opaque_state = vec![9, 8, 7];

        let old_session = 41;
        let project_session = next_project_session(old_session);
        let ids = [instance_id];
        let stale_events = [
            RuntimeEvent::SlotReady {
                slot: 0,
                name: "Old Session Instance".into(),
                latency_samples: 2048,
                tail_samples: 4096,
            },
            RuntimeEvent::ParameterValue {
                slot: 0,
                request_id: 0,
                id: 7,
                value: 0.99,
            },
            RuntimeEvent::State {
                slot: 0,
                request_id: 77,
                bytes: vec![1, 2, 3],
            },
            RuntimeEvent::SlotFault {
                slot: 0,
                message: "old worker failed".into(),
            },
        ];
        for event in &stale_events {
            assert!(
                apply_plugin_runtime_event_for_session(
                    &mut project,
                    project_session,
                    old_session,
                    &ids,
                    event,
                )
                .is_none()
            );
        }
        let instance = project
            .plugin_instances
            .iter()
            .find(|instance| instance.id == instance_id)
            .unwrap();
        assert_eq!(instance.runtime_status, PluginRuntimeStatus::Unloaded);
        assert_eq!(instance.parameters.get(&7), Some(&0.25));
        assert_eq!(instance.opaque_state, vec![9, 8, 7]);

        assert!(
            apply_plugin_runtime_event_for_session(
                &mut project,
                project_session,
                project_session,
                &ids,
                &RuntimeEvent::SlotReady {
                    slot: 0,
                    name: "New Session Instance".into(),
                    latency_samples: 64,
                    tail_samples: 0,
                },
            )
            .is_none()
        );
        assert_eq!(
            project
                .plugin_instances
                .iter()
                .find(|instance| instance.id == instance_id)
                .unwrap()
                .runtime_status,
            PluginRuntimeStatus::Loaded
        );
    }

