    #[test]
    fn mixer_track_snapshot_rolls_back_only_the_target_track() {
        let mut project = Project::default();
        let original_id = commit_loaded_plugin(
            &mut project,
            PluginPickerTarget::MixerSlot { track: 2, slot: 3 },
            &plugin_descriptor(
                ScannedPluginFormat::Vst2,
                "original",
                "Original",
                r"C:\VST\Original.dll",
            ),
        )
        .unwrap();
        let other_id = commit_loaded_plugin(
            &mut project,
            PluginPickerTarget::MixerSlot { track: 7, slot: 0 },
            &plugin_descriptor(
                ScannedPluginFormat::Vst3,
                "other",
                "Other",
                r"C:\VST3\Other.vst3",
            ),
        )
        .unwrap();
        let previous = snapshot_mixer_plugin_track(&project, 2);
        let replacement_id = commit_loaded_plugin(
            &mut project,
            PluginPickerTarget::MixerSlot { track: 2, slot: 3 },
            &plugin_descriptor(
                ScannedPluginFormat::Vst3,
                "replacement",
                "Replacement",
                r"C:\VST3\Replacement.vst3",
            ),
        )
        .unwrap();
        let candidate = snapshot_mixer_plugin_track(&project, 2);
        project
            .plugin_instances
            .iter_mut()
            .find(|instance| instance.id == replacement_id)
            .unwrap()
            .runtime_status = PluginRuntimeStatus::Loaded;
        project
            .plugin_instances
            .iter_mut()
            .find(|instance| instance.id == other_id)
            .unwrap()
            .wet = 0.33;
        assert!(mixer_track_matches_state(&project, 2, &candidate));

        restore_mixer_plugin_track(&mut project, 2, &previous);
        assert_eq!(
            plugin_slot_view(&project, 2, 3).unwrap().instance_id,
            original_id
        );
        assert!(
            project
                .plugin_instances
                .iter()
                .all(|instance| instance.id != replacement_id)
        );
        assert_eq!(
            project
                .plugin_instances
                .iter()
                .find(|instance| instance.id == other_id)
                .unwrap()
                .wet,
            0.33
        );
    }

