    #[test]
    fn generator_note_off_retry_is_bounded_and_keeps_overlapping_pitch_instances() {
        let mut pending = vec![
            PendingGeneratorNoteOff {
                note_instance_id: 1,
                channel_id: 7,
                note: 60,
                transport_epoch: 9,
                due_frame: 100,
            },
            PendingGeneratorNoteOff {
                note_instance_id: 2,
                channel_id: 7,
                note: 60,
                transport_epoch: 9,
                due_frame: 100,
            },
            PendingGeneratorNoteOff {
                note_instance_id: 3,
                channel_id: 8,
                note: 62,
                transport_epoch: 9,
                due_frame: 200,
            },
        ];
        let due = take_due_generator_note_offs(&mut pending, 9, 150, 1);
        assert_eq!(due.len(), 1);
        assert_eq!(pending.len(), 2);
        assert!(pending.iter().any(|note_off| note_off.due_frame <= 150));

        requeue_generator_note_offs(&mut pending, due.clone(), 3);
        requeue_generator_note_offs(&mut pending, due, 3);
        assert_eq!(pending.len(), 3);
        assert_eq!(
            pending
                .iter()
                .filter(|note_off| note_off.channel_id == 7 && note_off.note == 60)
                .count(),
            2
        );
        assert_eq!(
            pending
                .iter()
                .map(|note_off| note_off.note_instance_id)
                .collect::<HashSet<_>>()
                .len(),
            3
        );
        pending.push(PendingGeneratorNoteOff {
            note_instance_id: 4,
            channel_id: 7,
            note: 64,
            transport_epoch: 8,
            due_frame: 0,
        });
        let _ = take_due_generator_note_offs(&mut pending, 9, 0, 0);
        assert!(pending.iter().all(|note_off| note_off.transport_epoch == 9));
    }

