    #[test]
    fn timeline_generator_gate_requires_exact_confirmed_instances_and_is_per_channel() {
        let requirements = [
            GeneratorRouteRequirement {
                channel_id: 2,
                plugin_instance_id: 20,
                mixer_track: 3,
            },
            GeneratorRouteRequirement {
                channel_id: 7,
                plugin_instance_id: 70,
                mixer_track: 4,
            },
        ];
        let confirmed = [
            ConfirmedGeneratorRoute {
                channel_id: 2,
                endpoint_id: 200,
                plugin_instance_id: 20,
                mixer_track: 3,
            },
            ConfirmedGeneratorRoute {
                channel_id: 7,
                endpoint_id: 700,
                plugin_instance_id: 70,
                mixer_track: 4,
            },
        ];
        assert_eq!(
            required_generator_route_state(&requirements, &confirmed, &HashSet::new()),
            RequiredGeneratorRouteState::Ready
        );

        let pending = HashSet::from([7]);
        assert_eq!(
            required_generator_route_state(&requirements, &confirmed, &pending),
            RequiredGeneratorRouteState::Pending {
                channel_id: 7,
                plugin_instance_id: 70,
            }
        );

        let drifted = [
            confirmed[0],
            ConfirmedGeneratorRoute {
                plugin_instance_id: 71,
                ..confirmed[1]
            },
        ];
        assert!(matches!(
            required_generator_route_state(&requirements, &drifted, &HashSet::new()),
            RequiredGeneratorRouteState::Failed(_)
        ));
        let missing_endpoint = [ConfirmedGeneratorRoute {
            endpoint_id: 0,
            ..confirmed[0]
        }];
        assert!(matches!(
            required_generator_route_state(&requirements[..1], &missing_endpoint, &HashSet::new()),
            RequiredGeneratorRouteState::Failed(_)
        ));
        assert_eq!(
            required_generator_route_state(&requirements[..1], &confirmed, &HashSet::from([7])),
            RequiredGeneratorRouteState::Ready
        );
    }

    #[test]
    fn queued_parameter_edit_draft_is_a_hard_save_barrier_until_timeout() {
        let mut edits = PluginParameterEditState::default();
        let route = ParameterEditRoute {
            project_session: 4,
            endpoint: ParameterEndpoint {
                kind: ParameterEndpointKind::Insert,
                id: 8,
            },
            instance_id: 12,
            slot: 1,
            parameter_id: 19,
        };
        assert!(matches!(
            edits.request_edit(route, 0.75),
            Ok(ParameterEditRequest::Submit(_))
        ));
        assert!(!edits.has_pending());
        assert_eq!(edits.reserved_len(), 1);
        assert_eq!(
            parameter_edit_save_barrier_status(edits.reserved_len(), Duration::ZERO),
            ParameterEditSaveBarrierStatus::Waiting
        );
        assert_eq!(
            parameter_edit_save_barrier_status(
                edits.reserved_len(),
                PLUGIN_PARAMETER_EDIT_SAVE_TIMEOUT
            ),
            ParameterEditSaveBarrierStatus::TimedOut
        );
        assert_eq!(edits.fail_all().len(), 1);
        assert_eq!(
            parameter_edit_save_barrier_status(edits.reserved_len(), Duration::ZERO),
            ParameterEditSaveBarrierStatus::Drained
        );
    }

