    #[test]
    fn save_barrier_accepts_only_matching_generation_and_expires_stale_instances() {
        let started_at = Instant::now();
        let mut barrier = PluginStateSaveBarrier {
            request: ProjectSaveRequest::Manual {
                path: PathBuf::from("barrier.citrus"),
                lifecycle: None,
            },
            request_id: 77,
            requests_initialized: true,
            pending_requests: vec![PluginStateProbe::Insert {
                project_session: 1,
                track: 3,
                endpoint_id: 30,
                slot: 1,
                instance_id: 13,
            }],
            waiting: HashSet::from([11, 12]),
            stale: HashSet::from([10]),
            started_at,
            parameter_edits_drained: true,
        };
        barrier.observe_state(11, 76);
        assert!(barrier.waiting.contains(&11));
        barrier.observe_state(11, 77);
        assert!(!barrier.waiting.contains(&11));
        barrier.observe_fault(12);
        assert!(!barrier.ready());
        barrier.observe_fault(13);
        assert!(barrier.ready());
        assert_eq!(barrier.stale, HashSet::from([10, 12, 13]));

        let mut timeout = PluginStateSaveBarrier {
            request: ProjectSaveRequest::Autosave {
                path: PathBuf::from("recovery.citrus"),
                announce: false,
            },
            request_id: 78,
            requests_initialized: true,
            pending_requests: vec![PluginStateProbe::Generator {
                project_session: 1,
                channel_id: 4,
                endpoint_id: 40,
                instance_id: 22,
            }],
            waiting: HashSet::from([20, 21]),
            stale: HashSet::new(),
            started_at: started_at.checked_sub(PLUGIN_STATE_SAVE_TIMEOUT).unwrap(),
            parameter_edits_drained: true,
        };
        assert!(timeout.timed_out(Instant::now()));
        timeout.expire_unresolved();
        assert!(timeout.ready());
        assert_eq!(timeout.stale, HashSet::from([20, 21, 22]));
    }

